window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch02"]={"id":"ch02","title":"第二章 细胞质膜及跨膜运输","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"膜结构 · 流动性 · 被动/主动运输","modules":[{"i":0,"name":"模块一：生物膜结构模型与组成","slides":[{"i":0,"sec":"第一节 膜的组成","title":"细胞质膜与跨膜运输·开篇 (p1)","notes":"由膜脂、蛋白质、糖类组成，与细胞基本的生命活动密切相关。进化上：质膜的形成是非细胞生命(病毒)与细胞生物的重要分界点；细胞内膜系统的发展是细胞生物由低等到高等发展的反映。生物膜=质膜+细胞内膜系统。","page":1,"level":"掌握","img":"assets/img/ch02/p001.jpg","anim":null,"fig":null,"points":["质膜由膜脂、蛋白质、糖类组成","质膜的形成是非细胞生命(病毒)与细胞生物的分界点","生物膜=质膜+细胞内膜系统"],"check":{"q":"关于质膜与生物膜，下列说法正确的是（　）","o":["A. 质膜的形成是非细胞生命(病毒)与细胞生物的重要分界点","B. 细胞内膜系统与细胞进化程度无关","C. 病毒也具有典型的质膜结构","D. 生物膜仅指质膜"],"a":"A","e":"质膜由膜脂、蛋白质、糖类组成，其形成是非细胞生命与细胞生物的重要分界点；生物膜=质膜+细胞内膜系统。","oe":["正确，质膜形成是病毒与细胞生物的分界点。","内膜系统发展反映细胞由低等到高等。","病毒为非细胞生命，无典型质膜。","生物膜除质膜外，还包括细胞内膜系统。"]},"cards":[{"front":"生物膜由哪几部分组成？","back":"质膜+细胞内膜系统","mnemonic":"膜=外膜+内膜","type":"组成","useImg":false,"blank":"质膜","blank2":"细胞内膜系统"},{"front":"质膜的形成在进化上有何意义？","back":"是非细胞生命(病毒)与细胞生物的重要分界点","mnemonic":"","type":"定义","useImg":false,"blank":"分界点","blank2":"非细胞生命"}],"mem":"膜=外膜+内膜","big":"assets/img/ch02/big/p001.jpg","summary":"由膜脂、蛋白质、糖类组成，与细胞基本的生命活动密切相关","goal":"学完应能掌握并运用「细胞质膜与跨膜运输·开篇」的核心内容，能解释其机制、比较相关概念。","intuition":"质膜像细胞的“国界+海关”：既把细胞与外界分开，又负责物质进出和信息传递。"},{"i":1,"sec":"第一节 膜的组成","title":"膜的基本功能 (p2)","notes":"①屏障、半透膜，维护细胞内微环境的相对稳定；②细胞与外界进行物质、能量、信息交换。膜是细胞与外界环境的边界与交流界面。","page":2,"level":"掌握","img":"assets/img/ch02/p002.jpg","anim":null,"fig":null,"points":["质膜的基本功能：①界定细胞、维持内环境稳定；②控制物质进出(选择透过性)；③信息传递(受体)；④细胞识别(糖链)；⑤连接与支撑。"],"check":{"q":"下列属于质膜基本功能的是？","o":["A. 作为主要场所合成ATP","B. 控制物质进出并参与信息传递","C. 储存和复制遗传物质","D. 合成细胞所需的全部蛋白质"],"a":"B","e":"质膜作为边界与交流界面，具有选择透过性物质运输、信息传递、细胞识别及连接支撑等功能。","oe":["错：ATP合成主要在线粒体，不符合本页所学概念","对：对应质膜运输与信息传递功能","错：遗传物质存在于核或拟核，不符合本页所学概念","错：蛋白质由核糖体合成，不符合本页所学概念"],"basis":"控制物质进出(选择透过性)；信息传递(受体)"},"cards":[{"front":"细胞膜的两大基本功能是什么？","back":"①屏障、半透膜，维持内环境稳定；②与外界进行物质、能量、信息交换","mnemonic":"屏障+交流","type":"功能","useImg":false,"blank":"半透膜","blank2":"屏障"}],"mem":"屏障+交流","big":"assets/img/ch02/big/p002.jpg","summary":"①屏障、半透膜，维护细胞内微环境的相对稳定；②细胞与外界进行物质、能量、信息交换","goal":"学完应能掌握并运用「膜的基本功能」的核心内容，能解释其机制、比较相关概念。","intuition":"膜像细胞的“围墙+门卫+邮局”：既把细胞与外界隔开，又负责物质运输、信息接收和细胞识别。"},{"i":2,"sec":"第一节 膜的组成","title":"流动镶嵌模型 (p3)","notes":"流动镶嵌模型(1972 Singer & Nicolson)：①具有极性头部和非极性尾部的磷脂双分子层是生物膜的基本结构组分；②不同膜蛋白与膜脂双分子层亲和性不同、作用方式不同、位置不同；③脂类和蛋白质的流动性与不对称性是相互作用的基础；④这种相互作用又一定程度限制了膜蛋白和膜脂的流动性。","page":3,"level":"掌握","img":"assets/img/ch02/p003.jpg","anim":"fluid_mosaic","fig":null,"points":["1972年 Singer & Nicolson 提出流动镶嵌模型","磷脂双分子层是生物膜的基本结构组分","膜脂与膜蛋白具流动性和不对称性，并相互作用、相互限制"],"check":{"q":"关于流动镶嵌模型，下列说法正确的是？","o":["A. 生物膜是静态、刚性的结构","B. 膜蛋白均匀铺展并固定于脂双层表面","C. 磷脂双分子层是基本结构组分，膜脂与蛋白具流动性和不对称性","D. 膜脂分子在双层中完全不能移动"],"a":"C","e":"流动镶嵌模型认为磷脂双分子层是基本结构组分，膜脂与膜蛋白具有流动性、不对称性并相互限制。","oe":["错：生物膜具有流动性，并非刚性","错：膜蛋白分布不均且可移动，不符合本页所学概念","对：符合流动镶嵌模型核心观点，与笔记原文相符","错：膜脂可进行侧向扩散，不符合本页所学概念"],"basis":"磷脂双分子层是生物膜的基本结构组分…流动性与不对称性"},"cards":[{"front":"流动镶嵌模型由谁于何时提出？","back":"1972年 Singer & Nicolson","mnemonic":"","type":"定义","useImg":false,"blank":"Singer & Nicolson","blank2":"1972年"},{"front":"流动镶嵌模型的四个要点是什么？","back":"①磷脂双分子层为基本结构；②膜蛋白位置/作用方式不同；③脂与蛋白具流动性和不对称性；④相互作用限制流动性","mnemonic":"双层、蛋白、流动、限制","type":"组成","useImg":true,"blank":"磷脂双分子层","blank2":"膜蛋白位置/作用方式不同"}],"mem":"双层、蛋白、流动、限制","big":"assets/img/ch02/big/p003.jpg","summary":"流动镶嵌模型(1972 Singer & Nicolson)：①具有极性头部和非极性尾部的磷脂双分子层是生物膜的基本结构组分；②不同膜蛋白与膜脂双分子层亲和性不同、作用方式不同、位","goal":"学完应能掌握并运用「流动镶嵌模型」的核心内容，能解释其机制、比较相关概念。","intuition":"流动镶嵌模型像“漂着冰山的水面”：磷脂双分子层是流动的“海水”，膜蛋白像“冰山”镶嵌其中、能侧向漂移；内外两面的“风景”还不同（不对称）。"},{"i":3,"sec":"第一节 膜的组成","title":"三明治模型与流体镶嵌模型 (p4)","notes":"三明治模型(蛋白质分布描述有差异)→流体镶嵌模型。流体镶嵌模型要点：①不同蛋白质镶嵌于脂双层的方式不同——不对称性；②膜具流动性(蛋白质、脂类)。","page":4,"level":"理解","img":"assets/img/ch02/p004.jpg","anim":"fluid_mosaic_models","fig":"膜结构模型的历史：1935 年 Davson-Danielli“三明治”模型(脂双层两侧铺蛋白) → 1972 年 Singer-Nicolson 流动镶嵌模型(蛋白镶嵌在流动的脂双层中)。图对比两模型，突出“膜是流动的、蛋白是镶嵌的”。","points":["三明治模型后被流体镶嵌模型取代","流体镶嵌模型要点：蛋白质以不同方式镶嵌于脂双层(不对称性)、膜具流动性"],"check":{"q":"关于流体镶嵌模型，下列说法正确的是（　）","o":["A. 不同蛋白质镶嵌于脂双层的方式不同，膜具不对称性","B. 膜脂不能发生流动","C. 蛋白质均匀覆盖在脂双层两侧","D. 膜是静止不动的"],"a":"A","e":"流体镶嵌模型要点为：不同蛋白质以不同方式镶嵌于脂双层，膜具不对称性，且膜脂和膜蛋白均具流动性。","oe":["正确，蛋白质镶嵌方式不同且膜不对称。","膜脂可侧向扩散、旋转，具流动性。","蛋白质镶嵌方式多样，并非均匀覆盖。","膜具有流动性，并非静止不动的结构。"]},"cards":null,"mem":"三明治模型→流体镶嵌：蛋白不对称+膜流动","big":"assets/img/ch02/big/p004.jpg","summary":"三明治模型(蛋白质分布描述有差异)→流体镶嵌模型","goal":"学完应能理解并说明「三明治模型与流体镶嵌模型」。"},{"i":4,"sec":"第一节 膜的组成","title":"脂筏模型 (p6)","notes":"细胞膜脂筏模型(Lipid raft model,1988)：在甘油磷脂为主体的膜上，胆固醇、鞘磷脂等富集区域形成相对独立的'脂筏'，其上承载执行特定生物功能的某些膜蛋白。①非离子去垢剂(如Triton X-100)可将脂筏从质膜分离，蛋白质组学分析含250多种蛋白；②脂筏是异质性、高度动态、分子排列较紧密的膜脂微区域；③参与细胞信息传递、物质运输等。","page":6,"level":"掌握","img":"assets/img/ch02/p006.jpg","anim":"lipid_raft","fig":"脂筏(lipid raft)：膜上富含胆固醇和鞘脂的微区，比周围膜更有序、更厚，聚集特定蛋白(如 GPI 锚定蛋白、信号分子)。图显示脂筏是“漂浮”在流动性膜中的有序平台，参与信号转导和物质运输。","points":["1988年提出脂筏模型：胆固醇、鞘磷脂富集形成脂筏","脂筏是异质性、高度动态、排列较紧密的膜脂微区域","可被Triton X-100分离，含250多种蛋白，参与信息传递与物质运输"],"check":{"q":"关于脂筏模型，下列说法正确的是（　）","o":["A. 胆固醇、鞘磷脂等富集形成相对独立的微区域","B. 脂筏是均匀分布的膜结构","C. 脂筏不能参与细胞信息传递","D. 非离子去垢剂不能分离脂筏"],"a":"A","e":"脂筏是胆固醇、鞘磷脂富集形成的异质性、动态膜脂微区域，可被Triton X-100等非离子去垢剂分离，参与信息传递和物质运输。","oe":["正确，胆固醇与鞘磷脂富集形成脂筏","脂筏是异质性、高度动态的微区域","脂筏参与细胞信息传递与物质运输","非离子去垢剂可将脂筏从质膜分离"]},"cards":[{"front":"脂筏模型由谁于何时提出？","back":"1988年提出","mnemonic":"","type":"定义","useImg":false,"blank":"1988年提出"},{"front":"脂筏是什么？有何特点？","back":"膜上胆固醇、鞘磷脂富集的微区域；异质性、高度动态、排列紧密；参与信息传递和物质运输","mnemonic":"胆固醇+鞘磷脂=脂筏","type":"定义","useImg":true,"blank":"膜上胆固醇、鞘磷脂富集的微区域","blank2":"异质性"}],"mem":"胆固醇+鞘磷脂=脂筏","big":"assets/img/ch02/big/p006.jpg","terms":[{"t":"脂筏","en":"lipid raft","d":"膜脂双层中富含胆固醇和鞘脂、较为有序的微区；1988年提出脂筏模型，是膜功能分区的重要形式。"}],"summary":"细胞膜脂筏模型(Lipid raft model,1988)：在甘油磷脂为主体的膜上，胆固醇、鞘磷脂等富集区域形成相对独立的'脂筏'，其上承载执行特定生物功能的某些膜蛋白","goal":"学完应能掌握并运用「脂筏模型」的核心内容，能解释其机制、比较相关概念。","intuition":"脂筏像膜上的“浮岛”：富含胆固醇和鞘脂的较有序微区，聚集特定蛋白，参与信号与运输。"},{"i":5,"sec":"第一节 膜的组成","title":"膜的组成组分 (p7)","notes":"二、膜的组成组分。①膜脂——磷脂(甘油磷脂>50%，膜脂基本成分)、鞘磷脂；②糖脂/糖蛋白——短的寡糖通过共价键与膜脂或膜蛋白相连；③膜蛋白。","page":7,"level":"掌握","img":"assets/img/ch02/p007.jpg","anim":null,"fig":null,"points":["膜脂：磷脂（甘油磷脂占50%以上，为基本成分）、鞘磷脂","糖脂/糖蛋白：寡糖共价连于膜脂或膜蛋白","膜蛋白"],"check":{"q":"膜脂中含量最多、被视为膜脂基本成分的是？","o":["A. 甘油磷脂","B. 胆固醇","C. 糖脂","D. 中性脂肪"],"a":"A","e":"膜脂主要包括磷脂(甘油磷脂占膜脂50%以上)、鞘磷脂和糖脂，甘油磷脂是基本成分。","oe":["对：笔记注明其占膜脂50%以上","错：属膜脂但非含量最多的基本成分","错：糖脂在膜脂中含量较少，不符合本页所学概念","错：中性脂肪主要起储能作用，不符合本页所学概念"],"basis":"磷脂(甘油磷脂>50%，膜脂基本成分)"},"cards":[{"front":"膜由哪些组分构成？","back":"膜脂(磷脂、鞘磷脂)；糖脂/糖蛋白；膜蛋白","mnemonic":"脂+糖+蛋白","type":"组成","useImg":false,"blank":"膜脂","blank2":"膜蛋白"},{"front":"膜脂中含量最多的成分是什么？","back":"甘油磷脂，占膜脂50%以上，是膜脂基本成分","mnemonic":"","type":"组成数字","useImg":false,"blank":"甘油磷脂","blank2":"占膜脂50%以上"}],"mem":"脂+糖+蛋白","big":"assets/img/ch02/big/p007.jpg","summary":"①膜脂——磷脂(甘油磷脂>50%，膜脂基本成分)、鞘磷脂；②糖脂/糖蛋白——短的寡糖通过共价键与膜脂或膜蛋白相连；③膜蛋白","goal":"学完应能掌握并运用「膜的组成组分」的核心内容，能解释其机制、比较相关概念。","intuition":"生物膜主要由脂类、蛋白质和糖类组成：脂类搭骨架，蛋白干具体活，糖多挂在膜外当“身份证”。"},{"i":6,"sec":"第一节 膜的组成","title":"三种膜脂分子 (p8)","notes":"三种膜脂分子：A甘油磷脂、B鞘磷脂和糖脂、C胆固醇。都是两性分子——同时具有亲水和疏水两种性质。这是形成脂双层的基础。","page":8,"level":"掌握","img":"assets/img/ch02/p008.jpg","anim":null,"fig":"膜脂主要有三种：①甘油磷脂(磷脂酰胆碱等，占 50% 以上，构成脂双层骨架)；②鞘脂(鞘磷脂、糖脂)；③胆固醇(调节流动性)。图对比三种脂质的结构与分布。","points":["三种膜脂：甘油磷脂、鞘磷脂和糖脂、胆固醇","都是两性分子（兼亲水与疏水）","两性性质是形成脂双层的基础"],"check":{"q":"组成生物膜的三种主要膜脂分子是（　）","o":["A. 甘油三酯、胆固醇、糖原","B. 磷脂、蛋白质、核酸","C. 甘油磷脂、脂肪酸、氨基酸","D. 甘油磷脂、鞘磷脂和糖脂、胆固醇"],"a":"D","e":"三种膜脂为甘油磷脂、鞘磷脂和糖脂、胆固醇，都是兼有亲水和疏水性质的兩性分子。","oe":["甘油三酯与糖原都不是膜脂的种类","蛋白质和核酸并不属于膜脂的范畴","脂肪酸、氨基酸不是主要膜脂类型","正确，即上述三种主要的膜脂分子"]},"cards":[{"front":"三种主要膜脂分子是什么？","back":"甘油磷脂、鞘磷脂和糖脂、胆固醇","mnemonic":"甘油、鞘、固醇","type":"组成","useImg":true,"blank":"甘油磷脂","blank2":"鞘磷脂和糖脂"},{"front":"膜脂分子为何能形成脂双层？","back":"都是两性分子，同时具有亲水和疏水性质","mnemonic":"两性分子=一头亲水一头疏水","type":"定义","useImg":false,"blank":"两性分子","blank2":"亲水和疏水性质"}],"mem":"甘油、鞘、固醇","big":"assets/img/ch02/big/p008.jpg","summary":"三种膜脂分子：A甘油磷脂、B鞘磷脂和糖脂、C胆固醇","goal":"学完应能掌握并运用「三种膜脂分子」的核心内容，能解释其机制、比较相关概念。","intuition":"膜脂三大类是磷脂、糖脂和胆固醇：磷脂最多、是主角，糖脂参与识别，胆固醇当“调节器”。"},{"i":7,"sec":"第一节 膜的组成","title":"甘油磷脂 (p9)","notes":"甘油磷脂：磷脂酰胆碱(卵磷脂)、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇。为膜脂基本成分，占整个膜脂50%以上。具有一个极性头和两条疏水尾。","page":9,"level":"掌握","img":"assets/img/ch02/p009.jpg","anim":null,"fig":null,"points":["含磷脂酰胆碱(卵磷脂)、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇","是膜脂基本成分，占整个膜脂50%以上","一个极性头部 + 两条疏水尾部"],"check":{"q":"甘油磷脂分子的结构特点是？","o":["A. 两个极性头部和一条疏水尾部","B. 头部与尾部均具有极性","C. 由三个脂肪酸与甘油组成","D. 一个极性头部和两条疏水尾部"],"a":"D","e":"甘油磷脂包括磷脂酰胆碱、磷脂酰丝氨酸等，具有一个极性头部和两条疏水尾部。","oe":["错：甘油磷脂只有一个极性头部，不符合本页所学概念","错：疏水尾部不带电荷、没有极性","错：磷脂由甘油骨架连磷酸与两条脂链","对：笔记明确其一头两尾，与笔记原文相符"],"basis":"具有一个极性头和两条疏水尾"},"cards":[{"front":"甘油磷脂包括哪几种？","back":"磷脂酰胆碱(卵磷脂)、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇","mnemonic":"胆丝乙肌","type":"组成","useImg":false,"blank":"磷脂酰胆碱","blank2":"磷脂酰丝氨酸"},{"front":"甘油磷脂的结构特点是什么？","back":"一个极性头和两条疏水尾","mnemonic":"一头两尾","type":"定义","useImg":true,"blank":"极性头","blank2":"疏水尾"}],"mem":"胆丝乙肌","big":"assets/img/ch02/big/p009.jpg","summary":"甘油磷脂：磷脂酰胆碱(卵磷脂)、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇","goal":"学完应能掌握并运用「甘油磷脂」的核心内容，能解释其机制、比较相关概念。","intuition":"甘油磷脂像“一根带两个尾巴的棒”：甘油骨架+磷酸+两条脂肪酸尾，是膜脂中最主要的一类。"},{"i":8,"sec":"第一节 膜的组成","title":"鞘脂 (p10)","notes":"鞘脂：鞘氨醇的衍生物，主要在高尔基体合成，分鞘磷脂、鞘糖脂两类。具极性头部基团(亲水)和非极性尾部基团(疏水)。鞘磷脂不以甘油为骨架，而以鞘氨醇为骨架。","page":10,"level":"掌握","img":"assets/img/ch02/p010.jpg","anim":null,"fig":null,"points":["鞘氨醇的衍生物，主要在高尔基体合成","分鞘磷脂与鞘糖脂两类","鞘磷脂以鞘氨醇为骨架，不以甘油为骨架"],"check":{"q":"关于鞘脂，下列说法正确的是（　）","o":["A. 以甘油为骨架","B. 主要在细胞核内合成","C. 只含有非极性尾部","D. 以鞘氨醇为骨架，主要在高尔基体合成"],"a":"D","e":"鞘脂是鞘氨醇的衍生物，主要在高尔基体合成，分为鞘磷脂和鞘糖脂，具极性头部和非极性尾部。","oe":["鞘脂以鞘氨醇为骨架，并不以甘油为骨架。","主要在高尔基体合成，而非细胞核。","鞘脂兼有极性头部和非极性尾部。","正确，以鞘氨醇为骨架且在高尔基体合成。"]},"cards":[{"front":"鞘脂以什么为骨架？在哪里合成？","back":"以鞘氨醇为骨架(非甘油)；主要在高尔基体合成","mnemonic":"鞘氨醇骨架，高尔基合成","type":"定位","useImg":false,"blank":"鞘氨醇","blank2":"高尔基体"},{"front":"鞘脂分为哪两类？","back":"鞘磷脂和鞘糖脂","mnemonic":"","type":"组成","useImg":false,"blank":"鞘磷脂","blank2":"鞘糖脂"}],"mem":"鞘氨醇骨架，高尔基合成","big":"assets/img/ch02/big/p010.jpg","summary":"鞘脂：鞘氨醇的衍生物，主要在高尔基体合成，分鞘磷脂、鞘糖脂两类","goal":"学完应能掌握并运用「鞘脂」的核心内容，能解释其机制、比较相关概念。","intuition":"鞘脂以鞘氨醇为骨架，像“换了骨架的磷脂”：脑和神经膜中含量高。"},{"i":9,"sec":"第一节 膜的组成","title":"胆固醇 (p11)","notes":"胆固醇：含4个闭环的碳氢化合物，亲水头部为一个羟基。①自身不能形成脂双层，只能插入磷脂分子之间参与生物膜形成；②调节膜的流动性，增加膜稳定性及降低水溶性物质通透性；③脂筏基本结构成分，很多重要生物活性分子的前体；④动物细胞质膜含胆固醇，植物细胞为豆固醇，真菌细胞为麦角固醇，多数细菌质膜不含固醇。","page":11,"level":"掌握","img":"assets/img/ch02/p011.jpg","anim":null,"fig":null,"points":["含4个闭环，亲水头部为一个羟基","自身不能形成脂双层，只能插入磷脂之间","调节膜流动性、增加稳定性、降低水溶性物质通透性","动物为胆固醇、植物为豆固醇、真菌为麦角固醇，多数细菌不含固醇"],"check":{"q":"关于胆固醇，下列说法正确的是（　）","o":["A. 亲水头部为一个羟基","B. 自身可单独形成脂双层","C. 不能调节膜的流动性","D. 植物细胞质膜所含固醇为胆固醇"],"a":"A","e":"胆固醇含4个闭环，亲水头部为一个羟基，插入磷脂间调节膜流动性与稳定性；植物细胞为豆固醇，真菌为麦角固醇。","oe":["正确，胆固醇亲水头部为一个羟基","胆固醇只能插入磷脂间，不能单独成层","胆固醇可调节膜流动性并增加稳定性","植物细胞质膜所含的固醇为豆固醇"]},"cards":[{"front":"胆固醇的分子结构特点是什么？","back":"含4个闭环的碳氢化合物；亲水头部为一个羟基","mnemonic":"四环一羟基","type":"组成数字","useImg":true,"blank":"碳氢化合物","blank2":"羟基"},{"front":"胆固醇在生物膜中有哪些作用？","back":"不能自身形成脂双层，插入磷脂间；调节流动性、增加稳定性、降低水溶性物质通透性；脂筏成分；激素前体","mnemonic":"插磷脂、调流动、做前体","type":"功能","useImg":false,"blank":"脂筏","blank2":"磷脂"},{"front":"动物、植物、真菌、细菌质膜的固醇分别是什么？","back":"动物为胆固醇；植物为豆固醇；真菌为麦角固醇；多数细菌不含固醇","mnemonic":"动胆植豆真麦角，细菌多半没有它","type":"对比","useImg":false,"blank":"胆固醇","blank2":"豆固醇"}],"mem":"四环一羟基","big":"assets/img/ch02/big/p011.jpg","summary":"胆固醇：含4个闭环的碳氢化合物，亲水头部为一个羟基","goal":"学完应能掌握并运用「胆固醇」的核心内容，能解释其机制、比较相关概念。","intuition":"胆固醇像膜里的“双面调节器”：多了让膜变硬、少了膜太松；它嵌在磷脂之间，调节流动性和稳定性。"},{"i":10,"sec":"第一节 膜的组成","title":"血型抗原 (p12)","notes":"Blood group antigens(血型抗原)：A、B、AB、O血型由红细胞膜上糖脂/糖蛋白的寡糖链决定，是膜糖类参与细胞识别与免疫的经典例子。","page":12,"level":"理解","img":"assets/img/ch02/p012.jpg","anim":null,"fig":"ABO 血型抗原由糖脂的糖链决定：O 型为基础糖链，A 型加 N-乙酰半乳糖胺，B 型加半乳糖。图显示糖链末端糖基的差异决定血型，说明糖脂的糖基位于质膜外侧、参与细胞识别。","points":["A、B、AB、O血型由红细胞膜糖脂/糖蛋白的寡糖链决定","是膜糖类参与细胞识别与免疫的经典例子"],"check":{"q":"ABO血型由红细胞膜上的什么决定（　）","o":["A. 膜蛋白的激酶活性","B. 糖脂/糖蛋白的寡糖链","C. 膜上胆固醇的含量","D. 脂双分子层的厚度"],"a":"B","e":"A、B、AB、O血型由红细胞膜上糖脂/糖蛋白的寡糖链决定，是膜糖类参与细胞识别与免疫的经典例子。","oe":["膜蛋白的激酶活性并不决定ABO血型。","正确，ABO血型由膜表面寡糖链决定。","膜上胆固醇含量与ABO血型的决定无关。","脂双分子层厚度与ABO血型的决定无关。"]},"cards":null,"mem":"ABO血型由红细胞膜糖脂/糖蛋白寡糖链决定","big":"assets/img/ch02/big/p012.jpg","summary":"Blood group antigens(血型抗原)：A、B、AB、O血型由红细胞膜上糖脂/糖蛋白的寡糖链决定，是膜糖类参与细胞识别与免疫的经典例子","goal":"学完应能理解并说明「血型抗原」。"},{"i":11,"sec":"第一节 膜的组成","title":"膜脂的不对称性 (p13-15)","notes":"膜脂在细胞内外两侧分布不对称：①磷脂、糖脂分布表现完全不对称性——糖脂位于细胞外侧(非胞质侧)；②胆固醇几乎均等地分布在两侧单层；③糖蛋白和糖脂的糖基部分均位于质膜外侧(非胞质面)；④膜脂不对称性指同一种膜脂分布在两侧的比例不同。膜脂和膜蛋白在生物膜上均呈不对称分布。","page":13,"level":"掌握","img":"assets/img/ch02/p013.jpg","anim":"lipid_asymmetry","fig":null,"points":["磷脂、糖脂分布完全不对称：糖脂位于细胞外侧","胆固醇几乎均等地分布在两侧单层","糖蛋白和糖脂的糖基均位于质膜外侧","不对称性指同一种膜脂在两侧分布比例不同"],"check":{"q":"关于膜脂的不对称性，下列说法正确的是（　）","o":["A. 糖脂位于细胞质侧","B. 胆固醇严格均匀分布","C. 糖蛋白的糖基位于质膜外侧","D. 同一种膜脂在两侧比例相同"],"a":"C","e":"糖脂和糖蛋白的糖基均位于质膜非胞质侧（外侧）；磷脂分布不对称，胆固醇在两侧近乎均等分布。","oe":["糖脂位于细胞外侧，并非胞质侧位置","胆固醇在两侧近乎均等分布，并非严格均匀","正确，糖蛋白的糖基位于质膜外侧","膜脂不对称指同种膜脂两侧比例不同"]},"cards":[{"front":"膜脂不对称性表现在哪些方面？","back":"磷脂、糖脂分布完全不对称；糖脂位于细胞外侧；胆固醇两侧近乎均等；糖基均在质膜外侧","mnemonic":"糖在外，胆均分","type":"对比","useImg":true,"blank":"糖脂","blank2":"胆固醇"},{"front":"膜脂不对称性的定义是什么？","back":"同一种膜脂分布在脂双层两侧的比例不同","mnemonic":"同脂两侧量不同","type":"定义","useImg":false,"blank":"膜脂","blank2":"脂双层"}],"mem":"糖在外，胆均分","big":"assets/img/ch02/big/p013.jpg","summary":"膜脂在细胞内外两侧分布不对称：①磷脂、糖脂分布表现完全不对称性——糖脂位于细胞外侧(非胞质侧)；②胆固醇几乎均等地分布在两侧单层；③糖蛋白和糖脂的糖基部分均位于质膜外侧(非胞质面)","goal":"学完应能掌握并运用「膜脂的不对称性」的核心内容，能解释其机制、比较相关概念。","intuition":"膜脂不对称像“两层不同配方”：糖脂只在外层、某些磷脂只在内层，两层各摆各的。这层不对称是细胞识别与信号方向性的物质基础。"},{"i":12,"sec":"第一节 膜的组成","title":"膜脂的运动性 (p16)","notes":"膜脂运动方式：①同一侧的侧向运动(基本运动方式)；②双层分子之间的翻转运动(flip-flop，较慢)；③尾部摆动；④绕轴心自旋。运动性赋予膜流动性。","page":16,"level":"掌握","img":"assets/img/ch02/p016.jpg","anim":"membrane_fluidity","fig":null,"points":["侧向运动（基本运动方式）","翻转运动（flip-flop，较慢）","尾部摆动、绕轴心自旋"],"check":{"q":"膜脂最基本的运动方式是（　）","o":["A. 双层分子间的翻转运动","B. 同一侧的侧向运动","C. 尾部摆动","D. 绕轴心自旋"],"a":"B","e":"膜脂运动包括侧向运动、翻转运动、尾部摆动和自旋，其中同一侧的侧向运动是基本运动方式。","oe":["翻转运动（flip-flop）速度较慢，并非基本方式","正确，侧向运动是膜脂基本运动方式","尾部摆动是运动方式之一，非最基本的","绕轴自旋是运动方式之一，非最基本的"]},"cards":[{"front":"膜脂有哪几种运动方式？","back":"同侧侧向运动（基本方式）；双层间翻转运动（慢）；尾部摆动；绕轴心自旋","mnemonic":"侧翻摆旋","type":"流程","useImg":true,"blank":"翻转运动","blank2":"侧向运动"},{"front":"膜脂运动性赋予膜什么性质？","back":"流动性","mnemonic":"动起来才流动","type":"功能","useImg":false,"blank":"流动性"}],"mem":"侧翻摆旋","big":"assets/img/ch02/big/p016.jpg","terms":[{"t":"翻转运动","en":"flip-flop","d":"脂分子从脂双层的一层翻转到另一层，发生很慢，需翻转酶催化；区别于同一层内的侧向运动。"}],"summary":"膜脂运动方式：①同一侧的侧向运动(基本运动方式)；②双层分子之间的翻转运动(flip-flop，较慢)；③尾部摆动；④绕轴心自旋","goal":"学完应能掌握并运用「膜脂的运动性」的核心内容，能解释其机制、比较相关概念。","intuition":"膜脂像在“原地扭动的人群”：能侧向换位、旋转、摆尾，偶尔才翻到另一层（翻转运动很慢）。"},{"i":13,"sec":"第一节 膜的组成","title":"膜脂的特性 (p17)","notes":"膜脂两大特性：①不对称性；②流动性(Membrane Fluidity)→可塑性/伸缩性，使膜能变形、融合、分裂。\n\n【本页英文讲解】\n本页介绍膜脂（membrane lipid）的两大特性。一是膜脂分布的不对称性（asymmetry），即脂双层内外两层所含脂质的种类与比例不同；二是膜的流动性（membrane fluidity），指膜脂分子能侧向扩散、旋转甚至翻转，赋予膜可塑性、伸缩性，使细胞膜能变形、融合与分裂。流动性是质膜执行物质运输、细胞识别等功能的基础，其影响因素（脂肪酸饱和度、胆固醇、温度）是翟中和《细胞生物学》第4版第四章的常考点。","page":17,"level":"掌握","img":"assets/img/ch02/p017.jpg","anim":null,"fig":null,"points":["膜脂两大特性：不对称性、流动性","流动性赋予膜可塑性/伸缩性，使膜能变形、融合、分裂"],"check":{"q":"膜脂的两大特性是（　）","o":["A. 选择透过性和催化性","B. 对称性和刚性","C. 不对称性和流动性","D. 收缩性和传导性"],"a":"C","e":"膜脂具有不对称性(内外层脂质种类比例不同)和流动性(可侧向扩散、旋转、翻转)，流动性赋予膜可塑性、伸缩性。","oe":["选择透过性是膜整体功能，非膜脂特性。","膜脂不对称且具流动性，非对称刚性。","正确，膜脂具不对称性和流动性。","收缩性和传导性并非膜脂的两大特性。"]},"cards":[{"front":"膜脂的两大特性是什么？","back":"不对称性；流动性（可塑性/伸缩性，使膜能变形、融合、分裂）","mnemonic":"不流两字记心间","type":"对比","useImg":false,"blank":"不对称性","blank2":"流动性"}],"mem":"不流两字记心间","big":"assets/img/ch02/big/p017.jpg","summary":"膜脂两大特性：①不对称性；②流动性(Membrane Fluidity)→可塑性/伸缩性，使膜能变形、融合、分裂","goal":"学完应能掌握并运用「膜脂的特性」的核心内容，能解释其机制、比较相关概念。","intuition":"膜脂是兼性分子、有两副“面孔”（亲水头、疏水尾），这决定了它能自装配成双层，也带来流动性与不对称两大特性。"},{"i":14,"sec":"第一节 膜的组成","title":"膜的动态特性 (p18)","notes":"质膜的动态特性：运动细胞前缘的形成、膜蛋白的侧向移动等，都体现膜的动态性。膜流动性是细胞进行物质运输、运动、分裂等生命活动的必要条件。","page":18,"level":"理解","img":"assets/img/ch02/p018.jpg","anim":null,"fig":null,"points":["运动细胞前缘形成、膜蛋白移动等体现膜的动态性","膜流动性是细胞进行生命活动的必要条件"],"check":{"q":"下列现象最能体现质膜动态特性的是（　）","o":["A. 运动细胞前缘的形成和膜蛋白的移动","B. 细胞壁的加厚","C. 核仁的消失","D. 染色体的凝集"],"a":"A","e":"运动细胞前缘的形成、膜蛋白的移动等体现膜的动态性，膜流动性是细胞进行生命活动的必要条件。","oe":["正确，前缘形成和膜蛋白移动体现膜动态性。","细胞壁加厚与膜动态性无直接关系。","核仁消失属核内变化，非膜动态。","染色体凝集属核内事件，非膜动态。"]},"cards":null,"mem":"运动前缘、膜蛋白移动体现膜的动态性","big":"assets/img/ch02/big/p018.jpg","summary":"质膜的动态特性：运动细胞前缘的形成、膜蛋白的侧向移动等，都体现膜的动态性","goal":"学完应能理解并说明「膜的动态特性」。"},{"i":15,"sec":"第一节 膜的组成","title":"两性分子自装配成脂双层 (p19-20)","notes":"膜脂具有一个亲水头部和一到两条疏水尾部，是两性物质。在水溶液中能自动、自我装配形成脂双分子层，总是形成连续、不破裂的结构。疏水尾部不带电荷、无极性、不能与水形成氢键，暴露于水中能量上不利→自发把尾部埋在内侧、头部朝向水。","page":19,"level":"掌握","img":"assets/img/ch02/p019.jpg","anim":"lipid_selfassembly","fig":null,"points":["膜脂为两性分子（亲水头 + 疏水尾）","在水溶液中自发装配成连续、不破裂的脂双层","驱动力：疏水尾部暴露于水中能量不利，故埋在内侧、头部朝向水"],"check":{"q":"膜脂在水溶液中自发形成脂双层的驱动力是？","o":["A. 头部之间形成共价键交联","B. 疏水尾部避开水相，使体系能量上更有利","C. 尾部之间形成氢键网络","D. 靠ATP水解提供能量"],"a":"B","e":"膜脂为两性分子，疏水尾部暴露于水中能量上不利，故自发将尾部埋在内侧、头部朝向水相。","oe":["错：自装配并非共价交联，不符合本页所学概念","对：尾部暴露水中能量不利故自发内埋","错：疏水尾部不能与水形成氢键，不符合本页所学概念","错：膜脂自装配不需要ATP，不符合本页所学概念"],"basis":"疏水尾部…暴露于水中能量上不利→自发把尾部埋在内侧"},"cards":[{"front":"膜脂为什么能自我装配成脂双层？","back":"膜脂是两性分子（亲水头+疏水尾）；疏水尾暴露水中能量不利，自发埋在内侧、头部朝水","mnemonic":"头亲水尾怕水，自动排成双层","type":"流程","useImg":true,"blank":"两性分子","blank2":"疏水尾"},{"front":"脂双层自我装配的结构特点是什么？","back":"连续、不破裂的封闭结构","mnemonic":"连续不破","type":"定义","useImg":false,"blank":"封闭结构"}],"mem":"头亲水尾怕水，自动排成双层","big":"assets/img/ch02/big/p019.jpg","summary":"膜脂具有一个亲水头部和一到两条疏水尾部，是两性物质","goal":"学完应能掌握并运用「两性分子自装配成脂双层」的核心内容，能解释其机制、比较相关概念。","intuition":"膜脂自装配像“油滴入水”：磷脂一端亲水、一端疏水，在水里会自动把疏水尾藏到里面、亲水头朝外，形成双层。这靠疏水作用“自发”完成，不需要酶和能量，是细胞膜能自我封闭、自修复的基础。"},{"i":16,"sec":"第一节 膜的组成","title":"脂质体 (p21)","notes":"脂质体(liposome)：人工把纯磷脂/磷脂酰胆碱加入水中，可自我装配形成封闭的、直径25nm-1mm的球形小泡。电镜可显示其脂双层结构。是研究膜的良好模型。","page":21,"level":"掌握","img":"assets/img/ch02/p021.jpg","anim":null,"fig":"脂质体(liposome)：磷脂在水溶液中自发形成的封闭双层囊泡，内部包裹水相。可用来运载药物(DNA/蛋白)。图显示脂质体的双层结构与内部空腔。","points":["纯磷脂/磷脂酰胆碱加入水中自装配成封闭球形小泡","直径25nm–1mm，电镜可见脂双层结构","是研究生物膜的良好模型"],"check":{"q":"关于脂质体，下列说法正确的是（　）","o":["A. 纯磷脂加入水中可自我装配成封闭球形小泡，直径25nm—1mm","B. 其直径均小于1nm","C. 只能由蛋白质组装而成","D. 不能用于研究生物膜"],"a":"A","e":"脂质体是纯磷脂/磷脂酰胆碱加入水中自我装配形成的封闭球形小泡，直径25nm—1mm，电镜可见脂双层，是研究膜的良好模型。","oe":["正确，纯磷脂自组装成25nm—1mm的小泡。","直径为25nm—1mm，并非小于1nm。","脂质体由磷脂组装而成，而非蛋白质。","脂质体是研究生物膜的良好模型。"]},"cards":[{"front":"什么是脂质体？","back":"纯磷脂加入水中自我装配形成的封闭球形小泡，直径25nm-1mm，具脂双层结构","mnemonic":"磷脂入水成小球","type":"定义","useImg":true,"blank":"脂双层结构","blank2":"封闭球形小泡"},{"front":"脂质体在膜研究中的意义是什么？","back":"是研究生物膜的良好模型","mnemonic":"人工膜模型","type":"功能","useImg":false,"blank":"生物膜"}],"mem":"磷脂入水成小球","big":"assets/img/ch02/big/p021.jpg","summary":"脂质体(liposome)：人工把纯磷脂/磷脂酰胆碱加入水中，可自我装配形成封闭的、直径25nm-1mm的球形小泡","goal":"学完应能掌握并运用「脂质体」的核心内容，能解释其机制、比较相关概念。","intuition":"脂质体像“人工膜小泡”：把磷脂做成球形双层，可研究膜、也能当药物载体。"},{"i":17,"sec":"第一节 膜的组成","title":"脂质体的应用 (p22-23)","notes":"脂质体应用：①生物膜特性研究模型(膜蛋白可插入脂质体)；②抗体分子可使脂质体选择性结合到细胞表面→药物靶向递送；③膜蛋白功能研究、药物载体、疫苗佐剂等。","page":22,"level":"理解","img":"assets/img/ch02/p022.jpg","anim":null,"fig":null,"points":["脂质体可作生物膜研究模型，膜蛋白可插入其中","经抗体修饰后可选择性结合细胞表面，用于药物靶向递送"],"check":{"q":"用抗体分子修饰脂质体后，可实现的主要用途是？","o":["A. 在脂质体内合成蛋白质","B. 为细胞提供ATP能量","C. 使脂质体选择性结合细胞，靶向递送药物","D. 作为遗传物质复制的模板"],"a":"C","e":"脂质体可作生物膜研究模型，经抗体修饰后能选择性结合细胞表面，用于药物靶向递送。","oe":["错：脂质体不是蛋白合成场所，不符合本页所学概念","错：脂质体不产生ATP，不符合本页所学概念","对：笔记明确抗体修饰实现靶向递送","错：脂质体不是复制模板，不符合本页所学概念"],"basis":"抗体分子可使脂质体选择性结合到细胞表面→药物靶向递送"},"cards":null,"mem":"脂质体：膜模型、靶向给药、功能研究/佐剂","big":"assets/img/ch02/big/p022.jpg","summary":"脂质体应用：①生物膜特性研究模型(膜蛋白可插入脂质体)；②抗体分子可使脂质体选择性结合到细胞表面→药物靶向递送；③膜蛋白功能研究、药物载体、疫苗佐剂等","goal":"学完应能理解并说明「脂质体的应用」。"},{"i":18,"sec":"第一节 膜的组成","title":"膜脂的功能 (p24)","notes":"膜脂的功能：①构成膜的基本骨架；②也是膜蛋白执行功能的场所——蛋白通过疏水端同膜脂作用，使蛋白镶嵌在膜上执行功能；③一般情况下膜脂本身不参与生化生理功能(但有些膜脂如PI参与信号转导)。","page":24,"level":"掌握","img":"assets/img/ch02/p024.jpg","anim":null,"fig":null,"points":["构成膜的基本骨架","是膜蛋白执行功能的场所（蛋白以疏水端与膜脂作用）","一般情况下膜脂本身不参与生化生理功能（个别如PI参与信号转导）"],"check":{"q":"关于膜脂的功能，下列说法不正确的是（　）","o":["A. 为膜蛋白执行功能提供场所","B. 构成膜的基本骨架","C. 有些膜脂如PI参与信号转导","D. 一般情况下膜脂本身参与生化生理功能"],"a":"D","e":"膜脂构成膜骨架并作为膜蛋白作用的场所；一般情况下膜脂本身不参与生化生理功能，但如PI等个别膜脂参与信号转导。","oe":["膜蛋白通过疏水端与膜脂作用发挥功能。","构成膜的基本骨架属于膜脂的功能之一。","如PI等个别膜脂可参与细胞信号转导。","正确，一般膜脂本身不参与生化生理功能。"]},"cards":[{"front":"膜脂的功能有哪些？","back":"构成膜的基本骨架；为膜蛋白提供作用场所；一般本身不参与生理功能（少数如PI参与信号转导）","mnemonic":"骨架加舞台，一般不演戏","type":"功能","useImg":false,"blank":"基本骨架","blank2":"膜蛋白"}],"mem":"骨架加舞台，一般不演戏","big":"assets/img/ch02/big/p024.jpg","summary":"膜脂的功能：①构成膜的基本骨架；②也是膜蛋白执行功能的场所——蛋白通过疏水端同膜脂作用，使蛋白镶嵌在膜上执行功能；③一般情况下膜脂本身不参与生化生理功能(但有些膜脂如PI参与信号转","goal":"学完应能掌握并运用「膜脂的功能」的核心内容，能解释其机制、比较相关概念。","intuition":"膜脂不只是“背景板”：它构成膜骨架、划分区室、参与信号（如 PIP2）和识别，很多功能靠特定脂类完成。"},{"i":19,"sec":"第一节 膜的组成","title":"膜蛋白 (p25)","notes":"膜蛋白：生物膜的特定功能主要由蛋白质决定。一般功能越复杂的膜，其膜蛋白种类越多。按与膜结合方式分为：①膜内在蛋白/跨膜蛋白(intrinsic/integral)；②外周膜蛋白；③脂锚定蛋白。","page":25,"level":"掌握","img":"assets/img/ch02/p025.jpg","anim":"membrane_protein_types","fig":null,"points":["生物膜的特定功能主要由蛋白质决定，功能越复杂膜蛋白种类越多","按结合方式分：膜内在(跨膜)蛋白、外周膜蛋白、脂锚定蛋白"],"check":{"q":"关于膜蛋白，下列说法正确的是（　）","o":["A. 膜的功能主要由蛋白质决定，功能越复杂的膜膜蛋白种类越多","B. 外周膜蛋白属于跨膜蛋白","C. 膜蛋白的种类与膜功能无关","D. 膜蛋白都均匀分布在脂双层中"],"a":"A","e":"生物膜的特定功能主要由蛋白质决定，功能越复杂的膜其膜蛋白种类越多；膜蛋白分为膜内在蛋白、外周膜蛋白和脂锚定蛋白。","oe":["正确，膜功能主要由蛋白质决定。","外周膜蛋白附着膜表面，并非跨膜蛋白。","膜蛋白种类与数量决定膜的特定功能。","膜蛋白分布不对称，并非均匀分布。"]},"cards":[{"front":"膜蛋白按与膜结合方式分为哪几类？","back":"膜内在蛋白/跨膜蛋白；外周膜蛋白；脂锚定蛋白","mnemonic":"内在、外周、脂锚定","type":"组成数字","useImg":true,"blank":"膜蛋白","blank2":"外周膜蛋白"},{"front":"生物膜的功能主要由什么决定？","back":"膜蛋白；功能越复杂的膜，膜蛋白种类越多","mnemonic":"蛋白多，功能强","type":"功能","useImg":false,"blank":"膜蛋白","blank2":"功能越复杂的膜"}],"mem":"内在、外周、脂锚定","big":"assets/img/ch02/big/p025.jpg","terms":[{"t":"跨膜蛋白","en":"intrinsic / integral protein","d":"嵌入并贯穿脂双层的膜蛋白，跨膜区多为疏水α螺旋，需去垢剂才能从膜上分离。"}],"summary":"膜蛋白：生物膜的特定功能主要由蛋白质决定","goal":"学完应能掌握并运用「膜蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"膜蛋白是膜的“工作人员”：有的当通道、泵、受体、酶，决定膜的功能；按结合方式分内在、外周、脂锚定三类。"},{"i":20,"sec":"第一节 膜的组成","title":"去垢剂 (p26-27)","notes":"去垢剂(detergent)用于溶解膜蛋白：①离子型去垢剂(如SDS)——高浓度可破坏蛋白质离子键和氢键等非共价键，甚至改变亲水部分构象；②非离子型去垢剂(如Triton X-100)——温和，可溶解膜蛋白并保持活性。利用Triton X-100等温和去垢剂溶解膜蛋白是分离纯化的常用方法。","page":26,"level":"掌握","img":"assets/img/ch02/p026.jpg","anim":null,"fig":"去垢剂(如 SDS、Triton X-100)能插入膜并破坏疏水作用，把膜蛋白溶解下来。图显示去垢剂分子包裹膜蛋白的疏水区，使其保持可溶。去垢剂是膜蛋白提取和研究的常用试剂。","points":["去垢剂用于溶解膜蛋白","离子型去垢剂(如SDS)：破坏非共价键，甚至改变构象","非离子型去垢剂(如Triton X-100)：温和，可保持膜蛋白活性"],"check":{"q":"关于用去垢剂溶解膜蛋白，下列说法正确的是（　）","o":["A. 去垢剂不能溶解膜蛋白","B. 离子型去垢剂作用十分温和","C. SDS属于非离子型去垢剂","D. 非离子型去垢剂如Triton X-100较温和，可保持膜蛋白活性"],"a":"D","e":"去垢剂用于溶解膜蛋白，离子型如SDS可破坏非共价键甚至改变构象，非离子型如Triton X-100较温和，能保持膜蛋白活性。","oe":["去垢剂正是用于溶解和分离膜蛋白的。","离子型去垢剂作用较强，并非温和。","SDS属于离子型去垢剂，作用较强。","正确，Triton X-100温和且能保持活性。"]},"cards":[{"front":"去垢剂溶解膜蛋白的原理是什么？","back":"两亲性分子，可插入膜脂与膜蛋白间，破坏疏水相互作用，使膜蛋白溶出","mnemonic":"去垢剂像楔子，撬开膜脂与蛋白","type":"功能","useImg":false,"blank":"两亲性分子","blank2":"疏水相互作用"},{"front":"离子型与非离子型去垢剂有何区别？","back":"离子型(如SDS)：破坏非共价键，可能变性；非离子型(如Triton X-100)：温和，保持蛋白活性","mnemonic":"SDS猛，Triton温柔","type":"对比","useImg":false,"blank":"离子型","blank2":"非离子型"}],"mem":"去垢剂像楔子，撬开膜脂与蛋白","big":"assets/img/ch02/big/p026.jpg","summary":"去垢剂(detergent)用于溶解膜蛋白：①离子型去垢剂(如SDS)——高浓度可破坏蛋白质离子键和氢键等非共价键，甚至改变亲水部分构象；②非离子型去垢剂(如Triton X-10","goal":"学完应能掌握并运用「去垢剂」的核心内容，能解释其机制、比较相关概念。","intuition":"去垢剂像“拆膜洗剂”：一端亲水一端亲脂，能把膜打散、溶解内在蛋白，是提取膜蛋白的工具。"},{"i":21,"sec":"第一节 膜的组成","title":"内在跨膜整合蛋白 (p28)","notes":"膜内在蛋白(integral/intrinsic protein)：以α-螺旋或β-折叠方式跨膜。如跨膜受体、通道蛋白、载体蛋白；细菌外膜上的孔蛋白以β-折叠跨膜。","page":28,"level":"掌握","img":"assets/img/ch02/p028.jpg","anim":"tm_protein_structure","fig":"跨膜蛋白的两种常见跨膜结构：①α 螺旋——疏水氨基酸侧链朝外、与脂尾作用，是最常见的跨膜方式；②β 桶——β 折叠卷成桶状，见于孔道蛋白(如孔蛋白)。图对比两种跨膜结构。","points":["以α-螺旋或β-折叠方式跨膜","如跨膜受体、通道蛋白、载体蛋白；细菌外膜孔蛋白以β-折叠跨膜","需去垢剂才能从膜上溶解"],"check":{"q":"关于膜内在蛋白，下列说法正确的是（　）","o":["A. 以α-螺旋或β-折叠方式跨膜","B. 以非共价键结合在膜脂极性头部","C. 细菌外膜孔蛋白以α-螺旋跨膜","D. 改变离子强度即可将其洗脱"],"a":"A","e":"膜内在蛋白以α-螺旋或β-折叠跨膜，如受体、通道、载体蛋白；细菌外膜孔蛋白以β-折叠跨膜，需去垢剂溶解。","oe":["正确，内在蛋白以α-螺旋或β-折叠跨膜","以非共价键结合极性头部的是外周蛋白","孔蛋白以β-折叠跨膜，不是α-螺旋","内在蛋白需去垢剂溶解，改变离子强度无效"]},"cards":[{"front":"膜内在蛋白的跨膜结构方式有哪些？","back":"α-螺旋跨膜；β-折叠跨膜(如细菌外膜孔蛋白)","mnemonic":"α螺旋穿膜，β桶成孔","type":"组成","useImg":true,"blank":"α-螺旋跨膜","blank2":"β-折叠跨膜"},{"front":"膜内在蛋白的典型例子有哪些？","back":"跨膜受体；通道蛋白；载体蛋白；细菌外膜孔蛋白","mnemonic":"受体通道载体孔，都是内在蛋白","type":"例证","useImg":false,"blank":"跨膜受体","blank2":"通道蛋白"}],"mem":"α螺旋穿膜，β桶成孔","big":"assets/img/ch02/big/p028.jpg","summary":"膜内在蛋白(integral/intrinsic protein)：以α-螺旋或β-折叠方式跨膜","goal":"学完应能掌握并运用「内在跨膜整合蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"内在（整合）蛋白像“钉进双层里的柱子”：跨膜区的疏水氨基酸嵌在脂双层中，必须用去垢剂才能把它拔出来。"},{"i":22,"sec":"第一节 膜的组成","title":"胰岛素跨膜受体 (p29)","notes":"胰岛素跨膜受体：典型的跨膜受体蛋白，含胞外配体结合区、跨膜区、胞内激酶区，是膜内在蛋白的实例。","page":29,"level":"理解","img":"assets/img/ch02/p029.jpg","anim":null,"fig":"胰岛素受体是单次跨膜的受体酪氨酸激酶：胞外结合胰岛素，跨膜段固定，胞内激酶域自磷酸化后启动信号。图说明跨膜蛋白可把胞外信号传到胞内，是“膜的信息传递功能”实例。","points":["胰岛素受体含胞外配体结合区、跨膜区、胞内激酶区","是典型的膜内在蛋白(跨膜蛋白)实例"],"check":{"q":"胰岛素跨膜受体属于（　）","o":["A. 外周膜蛋白","B. 脂锚定蛋白","C. 膜内在蛋白(跨膜蛋白)","D. 细胞质基质蛋白"],"a":"C","e":"胰岛素跨膜受体含胞外配体结合区、跨膜区和胞内激酶区，是典型的膜内在蛋白(跨膜蛋白)实例。","oe":["外周膜蛋白不跨膜，与受体结构不符。","脂锚定蛋白是通过脂锚定在膜上。","正确，具跨膜区，属膜内在蛋白。","该受体位于膜上，非胞质基质蛋白。"]},"cards":null,"mem":"胰岛素受体：胞外配体区+跨膜区+胞内激酶区","big":"assets/img/ch02/big/p029.jpg","summary":"胰岛素跨膜受体：典型的跨膜受体蛋白，含胞外配体结合区、跨膜区、胞内激酶区，是膜内在蛋白的实例","goal":"学完应能理解并说明「胰岛素跨膜受体」。"},{"i":23,"sec":"第一节 膜的组成","title":"外周膜蛋白 (p30-31)","notes":"外周膜蛋白(peripheral proteins)：以非共价键结合在膜脂极性头部或膜内在蛋白上。人红细胞膜骨架蛋白中的血影蛋白、肌动蛋白属于外周蛋白。电镜显示其在膜内侧形成网状骨架。","page":30,"level":"掌握","img":"assets/img/ch02/p030.jpg","anim":null,"fig":null,"points":["以非共价键结合在膜脂极性头部或膜内在蛋白上","人红细胞膜骨架的血影蛋白、肌动蛋白属外周蛋白","电镜显示其在膜内侧形成网状骨架"],"check":{"q":"关于外周膜蛋白，下列说法正确的是（　）","o":["A. 需用去垢剂才能溶解","B. 人红细胞膜骨架中的血影蛋白属于外周蛋白","C. 以共价键嵌入脂双层内部","D. 电镜下位于膜外侧形成网状骨架"],"a":"B","e":"外周蛋白以非共价键结合膜脂极性头部或内在蛋白，血影蛋白、肌动蛋白属之，电镜下在膜内侧形成网状骨架。","oe":["外周蛋白用高盐或改变pH即可洗脱","正确，血影蛋白属于外周膜蛋白类","外周蛋白以非共价键结合，不嵌入脂双层","外周蛋白在膜内侧形成网状骨架结构"]},"cards":[{"front":"外周膜蛋白如何与膜结合？","back":"以非共价键结合在膜脂极性头部或膜内在蛋白上","mnemonic":"非共价，贴在外","type":"定义","useImg":true,"blank":"非共价键","blank2":"膜脂极性头部"},{"front":"人红细胞膜骨架中的外周蛋白有哪些？","back":"血影蛋白；肌动蛋白；在膜内侧形成网状骨架","mnemonic":"血影加肌动，网架撑红膜","type":"例证","useImg":false,"blank":"血影蛋白","blank2":"肌动蛋白"}],"mem":"非共价，贴在外","big":"assets/img/ch02/big/p030.jpg","summary":"外周膜蛋白(peripheral proteins)：以非共价键结合在膜脂极性头部或膜内在蛋白上","goal":"学完应能掌握并运用「外周膜蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"外周蛋白像“扒在膜表面的助手”：靠离子键、氢键贴在膜外侧或内侧，不用去垢剂，改改盐浓度/酸碱度就能洗脱。"},{"i":24,"sec":"第一节 膜的组成","title":"脂锚定蛋白 (p32)","notes":"脂锚定蛋白：与膜脂的特定脂类以共价连接于膜上。虽位于外周，但改变pH或离子强度不能从膜上去除，需特定的酶才能释放。如小G蛋白(Ras等)。","page":32,"level":"掌握","img":"assets/img/ch02/p032.jpg","anim":"lipid_anchors","fig":"脂锚定蛋白通过脂质锚连在膜上：①GPI 锚定蛋白——锚在膜外侧；②Src 等——N 端豆蔻酰化/棕榈酰化锚在胞质侧；③Ras——C 端异戊二烯化。图对比三种脂锚定方式。","points":["以共价键与膜脂的特定脂类连接","改变pH或离子强度不能去除，需特定酶才能释放","如小G蛋白(Ras等)"],"check":{"q":"关于脂锚定蛋白，下列说法正确的是（　）","o":["A. 改变pH或离子强度即可去除","B. 属于内在跨膜蛋白","C. 与膜脂特定脂类共价连接于膜上","D. 小G蛋白Ras属于普通外周蛋白"],"a":"C","e":"脂锚定蛋白以共价键与膜脂特定脂类连接，改变pH或离子强度不能去除，需特定酶释放，如小G蛋白Ras。","oe":["改变pH或离子强度不能去除脂锚定蛋白","脂锚定蛋白位于外周，并非跨膜蛋白","正确，其与膜脂特定脂类共价连接","Ras属于脂锚定蛋白，不是普通外周蛋白"]},"cards":[{"front":"脂锚定蛋白与膜如何连接？","back":"与膜脂特定脂类以共价键连接","mnemonic":"共价锚，脂中藏","type":"定义","useImg":false,"blank":"共价键","blank2":"膜脂特定脂类"},{"front":"脂锚定蛋白为何不能用高盐或改变pH去除？","back":"因是共价连接，需特定酶才能释放；如小G蛋白Ras","mnemonic":"共价锚定，酶才能解","type":"定位","useImg":false,"blank":"特定酶","blank2":"小G蛋白Ras"}],"mem":"共价锚，脂中藏","big":"assets/img/ch02/big/p032.jpg","summary":"脂锚定蛋白：与膜脂的特定脂类以共价连接于膜上","goal":"学完应能掌握并运用「脂锚定蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"脂锚定蛋白像“用一根油绳拴在膜上的蛋白”：通过共价连到脂分子锚在膜上，改 pH/离子强度去不掉，得用酶剪断。"},{"i":25,"sec":"第一节 膜的组成","title":"膜蛋白的分离 (p33)","notes":"如何分离各种类型膜蛋白？——根据膜蛋白与膜结合方式：外周蛋白可用高盐/改变pH/离子强度洗脱；内在蛋白需去垢剂溶解；脂锚定蛋白需特定酶(如磷脂酶)释放。","page":33,"level":"理解","img":"assets/img/ch02/p033.jpg","anim":null,"fig":"膜蛋白的分离：外周膜蛋白用高盐/极端 pH 即可洗脱；整合膜蛋白需去垢剂或有机溶剂破坏脂双层。图对比外周蛋白(松散结合)与整合蛋白(嵌入疏水区)的分离条件。","points":["外周蛋白可用高盐/改变pH或离子强度洗脱","内在蛋白需去垢剂溶解，脂锚定蛋白需特定酶释放"],"check":{"q":"分离膜内在蛋白常用的方法是（　）","o":["A. 高盐洗脱","B. 改变pH","C. 磷脂酶处理","D. 去垢剂溶解"],"a":"D","e":"外周蛋白可用高盐/改变pH/离子强度洗脱，内在蛋白需去垢剂溶解，脂锚定蛋白需特定酶释放。","oe":["高盐洗脱是分离外周蛋白的常用方法","改变pH或离子强度用于洗脱外周蛋白","磷脂酶处理用于释放脂锚定蛋白类","正确，内在蛋白需用去垢剂才能溶解"]},"cards":null,"mem":"外周蛋白高盐洗脱；内在去垢剂；脂锚定用酶","big":"assets/img/ch02/big/p033.jpg","summary":"如何分离各种类型膜蛋白","goal":"学完应能理解并说明「膜蛋白的分离」。"},{"i":26,"sec":"第一节 膜的组成","title":"限制膜蛋白侧向运动的因素 (p34)","notes":"膜蛋白的运动及限制膜蛋白侧向运动的4种方式：①胞内骨架成分；②细胞外基质中的分子；③其他扩散屏障(如紧密连接)；④膜蛋白与其它膜蛋白/脂筏的结合。","page":34,"level":"掌握","img":"assets/img/ch02/p034.jpg","anim":null,"fig":"膜蛋白的运动受限制：①被细胞骨架锚定；②被细胞外基质连接；③与其他细胞连接形成屏障；④形成大复合体。图显示膜蛋白并非完全自由扩散，其运动受多种因素约束。","points":["胞内骨架成分","细胞外基质中的分子","扩散屏障（如紧密连接）","膜蛋白与其它膜蛋白/脂筏的结合"],"check":{"q":"下列因素中，能限制膜蛋白侧向运动的是？","o":["A. 膜脂分子的极性头部","B. 细胞内钙离子浓度","C. 细胞核内的组蛋白","D. 细胞骨架锚定、细胞外基质连接及扩散屏障"],"a":"D","e":"膜蛋白并非完全自由扩散，可被胞内骨架、细胞外基质、扩散屏障及蛋白间结合所限制。","oe":["错：极性头部不限制侧向扩散，不符合本页所学概念","错：与膜蛋白运动限制无关，不符合本页所学概念","错：组蛋白位于核内，不参与，不符合本页所学概念","对：均为笔记所列限制方式，与笔记原文相符"],"basis":"①胞内骨架成分；②细胞外基质中的分子；③其他扩散屏障"},"cards":[{"front":"限制膜蛋白侧向运动的因素有哪些？","back":"胞内骨架成分；细胞外基质分子；扩散屏障(如紧密连接)；与其他膜蛋白/脂筏结合","mnemonic":"骨架、基质、屏障、结合","type":"流程","useImg":true,"blank":"扩散屏障","blank2":"胞内骨架成分"}],"mem":"骨架、基质、屏障、结合","big":"assets/img/ch02/big/p034.jpg","summary":"膜蛋白的运动及限制膜蛋白侧向运动的4种方式：①胞内骨架成分；②细胞外基质中的分子；③其他扩散屏障(如紧密连接)；④膜蛋白与其它膜蛋白/脂筏的结合","goal":"学完应能掌握并运用「限制膜蛋白侧向运动的因素」的核心内容，能解释其机制、比较相关概念。","intuition":"膜蛋白不是想怎么漂就怎么漂：被细胞骨架网、紧密连接、蛋白间相互作用等“卡住”，所以分布有区域性。"},{"i":27,"sec":"第一节 膜的组成","title":"上皮细胞极性 (p35)","notes":"肠内壁上皮细胞：面向肠腔的表面为细胞顶端表面(protein A朝向)；朝向组织和血液的为基底和侧面(转运蛋白B)。膜蛋白的不对称分布决定了细胞极性——上皮细胞顶端与基底面的蛋白组成不同。","page":35,"level":"理解","img":"assets/img/ch02/p035.jpg","anim":null,"fig":"上皮细胞的极性：顶面(apical)和基底面(basolateral)的膜蛋白/脂质组成不同，由紧密连接(tight junction)分隔，防止膜蛋白扩散。图显示极性细胞的顶-底膜蛋白分布差异。","points":["肠上皮细胞顶端面与基底/侧面转运蛋白分布不同","膜蛋白的不对称分布决定了细胞极性"],"check":{"q":"肠上皮细胞顶端与基底面蛋白组成不同，这体现了（　）","o":["A. 膜蛋白的均匀分布","B. 膜脂的对称分布","C. 细胞核的极性","D. 膜蛋白分布不对称导致细胞极性"],"a":"D","e":"肠上皮细胞顶端表面与基底、侧面转运蛋白分布不同，膜蛋白的不对称分布决定了细胞极性。","oe":["膜蛋白在膜上并非均匀分布，而具不对称性。","该现象体现膜蛋白分布，而非膜脂对称。","这是质膜蛋白分布极性，非核极性。","正确，膜蛋白不对称分布决定细胞极性。"]},"cards":null,"mem":"肠上皮：顶端蛋白A、基底侧蛋白B→细胞极性","big":"assets/img/ch02/big/p035.jpg","terms":[{"t":"顶面","en":"apical","d":"上皮细胞朝向管腔或外界的一侧游离面。"},{"t":"基底面","en":"basolateral","d":"上皮细胞朝向基膜及相邻细胞的一面。"},{"t":"紧密连接","en":"tight junction","d":"位于上皮细胞顶面与侧面交界处，封闭细胞间隙、阻止膜蛋白和脂扩散，维持细胞极性。"}],"summary":"肠内壁上皮细胞：面向肠腔的表面为细胞顶端表面(protein A朝向)；朝向组织和血液的为基底和侧面(转运蛋白B)","goal":"学完应能理解并说明「上皮细胞极性」。"},{"i":28,"sec":"第一节 膜的组成","title":"膜的流动性 (p36)","notes":"膜的流动性——膜脂的流动性和膜蛋白的运动是细胞进行生命活动的必要条件。膜流动性使细胞能进行物质运输、信号转导、细胞融合、分裂等。","page":36,"level":"掌握","img":"assets/img/ch02/p036.jpg","anim":"cell_fusion","fig":null,"points":["膜脂的流动性和膜蛋白的运动是细胞生命活动的必要条件","膜流动性使细胞能进行物质运输、信号转导、融合与分裂"],"check":{"q":"关于膜的流动性，下列说法正确的是（　）","o":["A. 膜脂流动性和膜蛋白运动是细胞生命活动的必要条件","B. 膜流动性仅由膜蛋白提供","C. 膜流动性不利于细胞融合","D. 膜流动性会阻碍物质运输"],"a":"A","e":"膜脂的流动性和膜蛋白的运动是细胞进行生命活动的必要条件，使细胞能进行物质运输、信号转导、融合与分裂等。","oe":["正确，膜流动性是生命活动的必要条件。","流动性由膜脂和膜蛋白共同体现。","膜的流动性有利于细胞的融合与分裂。","膜的流动性有利于细胞的物质运输。"]},"cards":[{"front":"膜的流动性对细胞有何意义？","back":"是物质运输、信号转导、细胞融合、分裂等生命活动的必要条件","mnemonic":"流动才有活力","type":"功能","useImg":false,"blank":"物质运输","blank2":"信号转导"}],"mem":"流动才有活力","big":"assets/img/ch02/big/p036.jpg","summary":"膜的流动性——膜脂的流动性和膜蛋白的运动是细胞进行生命活动的必要条件","goal":"学完应能掌握并运用「膜的流动性」的核心内容，能解释其机制、比较相关概念。","intuition":"膜的流动性像“温热的果冻”：脂分子能侧向扩散、旋转、摆动，膜蛋白也能漂移。没有流动性，细胞就无法变形、融合、分裂。"},{"i":29,"sec":"第一节 膜的组成","title":"FRAP技术 (p37)","notes":"荧光漂白恢复技术(FRAP, Fluorescence Recovery After Photo-bleaching)：用荧光标记膜蛋白/膜脂→激光漂白局部区域→观察荧光恢复速度→测定膜分子的扩散速率，是研究膜流动性的经典方法。","page":37,"level":"掌握","img":"assets/img/ch02/p037.jpg","anim":"frap","fig":"荧光漂白恢复(FRAP)实验：用激光漂白膜上一小块荧光标记的蛋白，观察周围荧光扩散回来恢复的速度，从而测膜蛋白的流动性。图显示漂白区荧光逐渐恢复，证明膜是流动的。","points":["用荧光标记膜蛋白或膜脂","激光漂白某一局部区域","观察荧光恢复速度→测定膜分子的扩散速率，是研究膜流动性的经典方法"],"check":{"q":"荧光漂白恢复技术（FRAP）主要用于（　）","o":["A. 测定膜分子的扩散速率","B. 测定膜蛋白的分子量","C. 观察膜的厚度","D. 分离不同类型的膜蛋白"],"a":"A","e":"FRAP用荧光标记膜分子，激光漂白局部后观察荧光恢复速度，从而测定膜分子的扩散速率，是研究膜流动性的经典方法。","oe":["正确，用于测定膜分子的扩散速率","测定蛋白质分子量常用电泳等方法","FRAP技术不用于测定膜的厚度","分离膜蛋白依据结合方式而非FRAP"]},"cards":[{"front":"FRAP技术的基本原理是什么？","back":"荧光标记膜分子→激光漂白局部→观察荧光恢复速度→测扩散速率","mnemonic":"漂白再恢复，速度测流动","type":"流程","useImg":true,"blank":"荧光恢复速度","blank2":"激光漂白局部"}],"mem":"漂白再恢复，速度测流动","big":"assets/img/ch02/big/p037.jpg","summary":"荧光漂白恢复技术(FRAP, Fluorescence Recovery After Photo-bleaching)：用荧光标记膜蛋白/膜脂→激光漂白局部区域→观察荧光恢复速度→","goal":"学完应能掌握并运用「FRAP技术」的核心内容，能解释其机制、比较相关概念。","intuition":"FRAP 像“漂白一小块再等周围荧光补回来”：用强光把局部荧光漂白，再测荧光恢复速度，就能算出膜蛋白/脂的流动快慢。","experiment":"【方法】FRAP：先用强激光漂白膜上一小块荧光，再记录该区域荧光恢复曲线；恢复越快说明膜蛋白/脂的流动性越高。"},{"i":30,"sec":"第一节 膜的组成","title":"影响膜流动性的因素-温度 (p38)","notes":"3.1 温度——最主要的影响因素。37℃以上膜脂相对流动的液态存在；温度降低到某一点时，膜脂由液晶(流动)态转变为凝胶态(相变温度Tm)。温度越高，流动性越大。\n【什么是 Tm】Tm 即相变温度(phase-transition temperature)，指膜脂在凝胶态与液晶态之间转变的临界温度：温度高于 Tm 时膜脂呈液晶态(可流动)，低于 Tm 时呈凝胶态(排列有序、僵硬)。Tm 主要由膜脂的脂肪酸链决定：脂肪酸链越不饱和(双键多、顺式折弯)、链越短，Tm 越低、流动性越好；越饱和、链越长，Tm 越高。胆固醇本身不直接决定 Tm，但能调节膜的流动性(详见 p45)。","page":38,"level":"掌握","img":"assets/img/ch02/p038.jpg","anim":null,"fig":null,"points":["温度是影响膜流动性的最主要因素","温度越高，流动性越大","降至相变温度Tm时，膜脂由液晶态转为凝胶态"],"check":{"q":"关于温度对膜流动性的影响，下列叙述正确的是？","o":["A. 温度升高流动性增大，降到相变温度以下由液晶态变凝胶态","B. 温度升高流动性减小","C. 温度变化不影响膜流动性","D. 温度降低时膜脂始终维持液晶态"],"a":"A","e":"温度是影响膜流动性的最主要因素，温度越高流动性越大，降至相变温度Tm时由液晶态转为凝胶态。","oe":["对：符合相变与流动性描述，与笔记原文相符","错：温度升高时膜流动性应增大，不符合本页所学概念","错：温度是主要影响因素，不符合本页所学概念","错：低温下转变为凝胶态，不符合本页所学概念"],"basis":"温度越高，流动性越大…由液晶态转变为凝胶态"},"cards":[{"front":"温度如何影响膜脂流动性？","back":"温度升高流动性增大；降至相变温度Tm以下，由液晶态转为凝胶态","mnemonic":"热则流，冷则凝","type":"定义","useImg":false,"blank":"相变温度","blank2":"液晶态"}],"mem":"热则流，冷则凝","big":"assets/img/ch02/big/p038.jpg","summary":"温度——最主要的影响因素","goal":"学完应能掌握并运用「影响膜流动性的因素-温度」的核心内容，能解释其机制、比较相关概念。","intuition":"膜像“随温度软硬的黄油”：温度升高更流动，降到相变温度 Tm 以下就从液晶态变凝胶态。"},{"i":31,"sec":"第一节 膜的组成","title":"脂肪酸尾部的聚集 (p39)","notes":"脂肪酸尾部聚集得越密集、越有规则，该脂双层越粘滞、流动性越低。饱和脂肪酸尾部排列紧密，使膜流动性较低；不饱和脂肪酸因双键折弯则相反。","page":39,"level":"理解","img":"assets/img/ch02/p039.jpg","anim":null,"fig":null,"points":["脂肪酸尾部聚集越密集、越规则，双层越粘滞、流动性越低","饱和脂肪酸尾部排列紧密，流动性低"],"check":{"q":"脂肪酸尾部聚集得越密集、越有规则，则该双层（　）","o":["A. 越薄","B. 越容易融合","C. 越粘滞，流动性越低","D. 流动性越高"],"a":"C","e":"脂肪酸尾部聚集越密集、越有规则，双层越粘滞，流动性越低；饱和脂肪酸尾部排列紧密，流动性低。","oe":["尾部聚集程度与膜的厚薄无直接关系。","膜流动性低不利于细胞膜的融合过程。","正确，排列越密集则越粘滞、流动性越低。","排列紧密使流动性降低，而非升高。"]},"cards":null,"mem":"饱和脂肪酸尾排列密→双层粘滞、流动性低","big":"assets/img/ch02/big/p039.jpg","summary":"脂肪酸尾部聚集得越密集、越有规则，该脂双层越粘滞、流动性越低","goal":"学完应能理解并说明「脂肪酸尾部的聚集」。"},{"i":32,"sec":"第一节 膜的组成","title":"膜脂结构组成对流动性的影响 (p40)","notes":"3.2 膜脂结构和组成对膜流动性的影响：①脂肪酸链的长度——短链脂肪酸含量丰富，膜流动性高；②脂肪酸链的不饱和程度——不饱和度高(双键多)流动性高；③胆固醇——调节流动性。","page":40,"level":"掌握","img":"assets/img/ch02/p040.jpg","anim":null,"fig":null,"points":["短链脂肪酸含量丰富→膜流动性高","脂肪酸不饱和程度高(双键多)→流动性高","胆固醇对流动性起调节作用"],"check":{"q":"下列因素中能提高膜流动性的是（　）","o":["A. 长链饱和脂肪酸含量高","B. 短链脂肪酸含量丰富、不饱和程度高","C. 胆固醇大量增加","D. 脂肪酸不饱和度低"],"a":"B","e":"短链脂肪酸含量丰富、不饱和程度高(双键多)时膜流动性高；长链饱和脂肪酸降低流动性，胆固醇起调节作用。","oe":["长链饱和脂肪酸使膜流动性降低。","正确，短链与高不饱和度均提高流动性。","胆固醇对膜流动性起双向调节作用。","脂肪酸不饱和度低则膜流动性较低。"]},"cards":[{"front":"膜脂的哪些结构因素影响膜的流动性？","back":"①脂肪酸链长度：链越短，流动性越高；②不饱和程度：双键越多，流动性越高；③胆固醇：调节流动性。","mnemonic":"短链多双键，流动更顺畅","type":"组成数字","useImg":false,"blank":"胆固醇","blank2":"不饱和程度"}],"mem":"短链多双键，流动更顺畅","big":"assets/img/ch02/big/p040.jpg","summary":"膜脂结构和组成对膜流动性的影响：①脂肪酸链的长度——短链脂肪酸含量丰富，膜流动性高；②脂肪酸链的不饱和程度——不饱和度高(双键多)流动性高；③胆固醇——调节流动性","goal":"学完应能掌握并运用「膜脂结构组成对流动性的影响」的核心内容，能解释其机制、比较相关概念。","intuition":"膜的流动性由“配方”决定：不饱和脂肪酸和短链多→更流动；饱和和长链多→更容易凝固。"},{"i":33,"sec":"第一节 膜的组成","title":"卵磷脂分子 (p41)","notes":"卵磷脂分子(磷脂酰胆碱)是膜脂的典型代表，由一个极性头(胆碱+磷酸+甘油)和两条疏水尾(脂肪酸链)构成，是兼性分子，在水中可自装配成脂双层。","page":41,"level":"理解","img":"assets/img/ch02/p041.jpg","anim":null,"fig":null,"points":["卵磷脂(磷脂酰胆碱)是膜脂的典型代表","含一个极性头(胆碱+磷酸+甘油)和两条脂肪酸疏水尾"],"check":{"q":"卵磷脂(磷脂酰胆碱)分子的结构特点是（　）","o":["A. 由鞘氨醇构成骨架","B. 两个极性头和一条疏水尾","C. 一个极性头(胆碱+磷酸+甘油)和两条疏水尾","D. 只有极性头，无疏水尾"],"a":"C","e":"卵磷脂是膜脂的典型代表，含一个极性头(胆碱+磷酸+甘油)和两条脂肪酸疏水尾；以鞘氨醇为骨架的是鞘脂。","oe":["卵磷脂以甘油为骨架，鞘氨醇为鞘脂骨架。","卵磷脂为一个极性头、两条疏水尾。","正确，卵磷脂为极性头加两条疏水尾。","卵磷脂含两条疏水尾，并非没有。"]},"cards":null,"mem":"卵磷脂=极性头(胆碱+磷酸+甘油)+两条疏水尾","big":"assets/img/ch02/big/p041.jpg","summary":"卵磷脂分子(磷脂酰胆碱)是膜脂的典型代表，由一个极性头(胆碱+磷酸+甘油)和两条疏水尾(脂肪酸链)构成，是兼性分子，在水中可自装配成脂双层","goal":"学完应能理解并说明「卵磷脂分子」。"},{"i":34,"sec":"第一节 膜的组成","title":"饱和与不饱和脂肪酸 (p42)","notes":"饱和脂肪酸(猪肉、奶制品)不含双键→分子间排列紧密→室温下固态；不饱和脂肪酸(植物油如玉米油)含双键→分子弯曲、排列疏松→室温下液态。这解释了膜流动性与脂肪酸饱和度的关系。","page":42,"level":"掌握","img":"assets/img/ch02/p042.jpg","anim":null,"fig":"脂肪酸的饱和度影响膜的流动性：饱和脂肪酸(如硬脂酸)直链排列紧密，降低流动性；不饱和脂肪酸(含双键)弯曲、排列疏松，提高流动性。图对比两种尾部对脂双层排列的影响。","points":["饱和脂肪酸不含双键，分子排列紧密，室温下呈固态","不饱和脂肪酸含双键，分子弯曲、排列疏松，室温下呈液态"],"check":{"q":"关于脂肪酸饱和度与膜流动性的关系，下列说法正确的是（　）","o":["A. 饱和脂肪酸含双键，使膜流动性增大","B. 不饱和脂肪酸含双键，分子弯曲、排列疏松","C. 饱和脂肪酸使膜在室温下呈液态","D. 不饱和脂肪酸排列紧密，流动性小"],"a":"B","e":"饱和脂肪酸不含双键，分子排列紧密，室温下呈固态；不饱和脂肪酸含双键，分子弯曲、排列疏松，室温下呈液态。","oe":["饱和脂肪酸不含双键，故流动性小","正确，不饱和脂肪酸含双键，排列疏松","饱和脂肪酸在室温下呈固态状态存在","不饱和脂肪酸排列疏松，流动性大"]},"cards":[{"front":"饱和脂肪酸与不饱和脂肪酸对膜流动性的影响有何不同？","back":"饱和脂肪酸无双键，排列紧密，室温固态，流动性低；不饱和脂肪酸含双键，分子弯曲、排列疏松，室温液态，流动性高。","mnemonic":"饱和直紧硬，不饱和弯松软","type":"对比","useImg":false,"blank":"不饱和脂肪酸","blank2":"饱和脂肪酸"}],"mem":"饱和直紧硬，不饱和弯松软","big":"assets/img/ch02/big/p042.jpg","summary":"饱和脂肪酸(猪肉、奶制品)不含双键→分子间排列紧密→室温下固态；不饱和脂肪酸(植物油如玉米油)含双键→分子弯曲、排列疏松→室温下液态","goal":"学完应能掌握并运用「饱和与不饱和脂肪酸」的核心内容，能解释其机制、比较相关概念。","intuition":"饱和脂肪酸像“直筷子”能排紧、膜更硬；不饱和脂肪酸带折弯像“弯筷子”，排不紧、膜更流动。"},{"i":35,"sec":"第一节 膜的组成","title":"固醇结构 (p43)","notes":"固醇(甾醇)的基本结构是4环碳氢化合物。动物细胞膜中的固醇为胆固醇，植物为豆固醇/豆甾醇，真菌为麦角固醇。","page":43,"level":"理解","img":"assets/img/ch02/p043.jpg","anim":null,"fig":null,"points":["固醇的基本结构是4环碳氢化合物","动物为胆固醇，植物为豆固醇/豆甾醇，真菌为麦角固醇"],"check":{"q":"关于固醇(甾醇)，下列说法正确的是（　）","o":["A. 真菌细胞膜中主要含豆固醇","B. 基本结构是4环碳氢化合物，动物细胞膜中为胆固醇","C. 胆固醇不是膜脂的成分","D. 动物细胞膜中主要含麦角固醇"],"a":"B","e":"固醇的基本结构是4环碳氢化合物；动物为胆固醇，植物为豆固醇/豆甾醇，真菌为麦角固醇。","oe":["真菌细胞膜中为麦角固醇，豆固醇属植物。","正确，固醇为4环结构，动物中为胆固醇。","胆固醇是动物细胞膜的重要膜脂成分。","动物细胞膜中为胆固醇，而非麦角固醇。"]},"cards":null,"mem":"固醇四环：动物胆固醇、植物豆固醇、真菌麦角","big":"assets/img/ch02/big/p043.jpg","summary":"固醇(甾醇)的基本结构是4环碳氢化合物","goal":"学完应能理解并说明「固醇结构」。"},{"i":36,"sec":"第一节 膜的组成","title":"胆固醇在膜中的位置 (p44)","notes":"胆固醇分子(绿色)插入脂双层中：甾环区与磷脂的脂肪酸链相互作用，羟基朝向水相。胆固醇调节膜的流动性和稳定性。","page":44,"level":"理解","img":"assets/img/ch02/p044.jpg","anim":null,"fig":"胆固醇嵌在磷脂之间：其刚性环状结构使膜脂排列更有序，在高温下限制运动、低温下阻止紧密堆积。图显示胆固醇位于疏水尾部区域，是“流动性缓冲器”。","points":["胆固醇插入脂双层，甾环区与磷脂脂肪酸链相互作用","羟基朝向水相，调节膜的流动性和稳定性"],"check":{"q":"关于胆固醇在膜中的位置和作用，下列说法正确的是（　）","o":["A. 甾环区与磷脂脂肪酸链相互作用","B. 羟基朝向膜内部疏水区","C. 胆固醇不参与调节膜流动性","D. 胆固醇位于膜中央与头部结合"],"a":"A","e":"胆固醇插入脂双层，甾环区与磷脂脂肪酸链相互作用，羟基朝向水相，调节膜的流动性和稳定性。","oe":["正确，甾环区与磷脂脂肪酸链相互作用","羟基亲水，朝向水相而非膜疏水区","胆固醇可调节膜的流动性和稳定性","胆固醇插入脂双层中，并非位于中央"]},"cards":null,"mem":"胆固醇插脂双层：羟基朝水，调节流动性与稳定","big":"assets/img/ch02/big/p044.jpg","summary":"胆固醇分子(绿色)插入脂双层中：甾环区与磷脂的脂肪酸链相互作用，羟基朝向水相","goal":"学完应能理解并说明「胆固醇在膜中的位置」。"}],"mcq":[{"id":"ch02_mcq_1","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"生物膜流动镶嵌模型的提出者和年份是？","o":["A. Singer & Nicolson,1972","B. Watson & Crick,1953","C. Robertson,1964","D. Singer,1988"],"a":"A","e":"1972年Singer和Nicolson提出流动镶嵌模型：磷脂双分子层为基本骨架，蛋白质镶嵌其中，膜具流动性。","kp":"ch02_s0_2","oe":["正确。1972年Singer和Nicolson提出流动镶嵌模型，故正确。","错。Watson和Crick于1953年提出DNA双螺旋结构，与膜模型无关。","错。Robertson提出的是单位膜模型，不是流动镶嵌模型。","错。Singer提出流动镶嵌模型的年份是1972年，而非1988年。"]},{"id":"ch02_mcq_2","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"占整个膜脂50%以上的膜脂是？","o":["A. 胆固醇","B. 甘油磷脂","C. 鞘脂","D. 糖脂"],"a":"B","e":"甘油磷脂为膜脂基本成分，占整个膜脂50%以上。包括磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇。","kp":"ch02_s0_7","oe":["错。胆固醇属固醇类，含量远低于甘油磷脂，不是含量最高的膜脂。","正确。甘油磷脂占整个膜脂50%以上，是膜脂的基本成分，故正确。","错。鞘脂含量少于甘油磷脂，不是占膜脂50%以上的成分。","错。糖脂含量也低于甘油磷脂，不是含量最高的膜脂。"]},{"id":"ch02_mcq_3","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"关于胆固醇在膜中的作用,错误的是？","o":["A. 自身不能形成脂双层","B. 调节膜的流动性","C. 是脂筏基本结构成分","D. 是膜脂含量最高的成分"],"a":"D","e":"胆固醇自身不能形成脂双层，只能插入磷脂之间；调节流动性、增加稳定性；是脂筏成分。含量最高的膜脂是甘油磷脂。","kp":"ch02_s0_36","oe":["正确。胆固醇自身不能形成脂双层，只能插入磷脂分子之间。","正确。胆固醇能调节膜的流动性，叙述正确。","正确。胆固醇是脂筏的基本结构成分，叙述正确。","错误。膜脂中含量最高的是甘油磷脂而非胆固醇，故选D。"]},{"id":"ch02_mcq_4","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"膜脂运动的基本方式是？","o":["A. 翻转运动","B. 侧向运动","C. 尾部摆动","D. 自旋"],"a":"B","e":"同一侧的侧向运动是膜脂运动的基本方式。翻转运动(flip-flop)较慢，需酶协助。","kp":"ch02_s0_12","oe":["错。翻转运动速度很慢且需酶协助，不是膜脂运动的基本方式。","正确。同一侧磷脂分子间的侧向运动是膜脂运动的基本方式，故正确。","错。尾部摆动只是脂肪酸尾的一种运动形式，不是基本方式。","错。自旋是膜脂的一种运动形式，但基本方式是侧向运动。"]},{"id":"ch02_mcq_5","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"膜脂和膜蛋白在膜上的分布特点是？","o":["A. 完全对称","B. 不对称分布","C. 随机分布","D. 只在胞外侧"],"a":"B","e":"膜脂和膜蛋白在生物膜上均呈不对称分布；糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。","kp":"ch02_s0_11","oe":["错。膜脂和膜蛋白在膜上的分布并不完全对称。","正确。膜脂和膜蛋白在生物膜上均呈不对称分布，故正确。","错。膜成分的分布有规律地不对称，而非随机分布。","错。除胞外侧外，胞质面也有膜蛋白分布，并非只在胞外侧。"]},{"id":"ch02_mcq_6","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"膜内在蛋白(integral protein)的跨膜方式是？","o":["A. 仅α-螺旋","B. α-螺旋或β-折叠","C. 仅β-折叠","D. 无规则"],"a":"B","e":"内在跨膜整合蛋白以α-螺旋或β-折叠方式跨膜；细菌外膜孔蛋白以β-折叠跨膜。","kp":"ch02_s0_21","oe":["错。膜内在蛋白的跨膜方式不限于α-螺旋。","正确。内在整合蛋白以α-螺旋或β-折叠方式跨膜，故正确。","错。并非只有β-折叠，多数跨膜蛋白以α-螺旋跨膜。","错。跨膜区有规则的二级结构，并非无规则。"]},{"id":"ch02_mcq_7","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"人红细胞膜骨架蛋白中的血影蛋白属于？","o":["A. 内在蛋白","B. 外周蛋白","C. 脂锚定蛋白","D. 通道蛋白"],"a":"B","e":"血影蛋白、肌动蛋白以非共价键结合在膜内侧，属于外周膜蛋白，构成膜骨架。","kp":"ch02_s0_23","oe":["错。血影蛋白以非共价键结合于膜内侧，属外周蛋白而非内在蛋白。","正确。血影蛋白以非共价键结合膜内侧，属外周蛋白并构成膜骨架，故正确。","错。血影蛋白不与膜脂共价连接，不属于脂锚定蛋白。","错。血影蛋白是膜骨架蛋白，不是通道蛋白。"]},{"id":"ch02_mcq_8","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"需要用特定酶才能从膜上释放的膜蛋白是？","o":["A. 外周蛋白","B. 脂锚定蛋白","C. 内在蛋白","D. 跨膜蛋白"],"a":"B","e":"脂锚定蛋白与膜脂共价连接，改变pH或离子强度不能去除，需特定酶(如磷脂酶)才能释放。","kp":"ch02_s0_24","oe":["错。外周蛋白改变pH或离子强度即可去除，不需要特定酶。","正确。脂锚定蛋白与膜脂共价连接，需特定酶如磷脂酶才能释放，故正确。","错。内在蛋白通常需去垢剂溶解，而不是用特定酶释放。","错。跨膜蛋白属内在蛋白，其释放主要靠去垢剂而非特定酶。"]},{"id":"ch02_mcq_9","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"影响膜流动性最主要的因素是？","o":["A. pH","B. 温度","C. 离子强度","D. 膜蛋白种类"],"a":"B","e":"温度是影响膜流动性最主要的因素。温度降低到相变温度时膜脂由液晶态转变为凝胶态。","kp":"ch02_s0_30","oe":["pH改变膜脂与膜蛋白的带电状态，但不是决定流动性的最主要因素。","温度是影响膜流动性最主要的因素，降至相变温度时膜脂由液晶态转为凝胶态。","离子强度主要影响膜表面电荷与静电作用，对膜流动性影响并非最主要。","膜蛋白种类影响膜的功能，而膜流动性主要由脂质分子的性质决定。"]},{"id":"ch02_mcq_10","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"下列关于膜流动性的说法正确的是？","o":["A. 脂肪酸链越长流动性越高","B. 不饱和脂肪酸越多流动性越高","C. 胆固醇总是增加流动性","D. 饱和脂肪酸越多流动性越高"],"a":"B","e":"短链脂肪酸、不饱和脂肪酸(双键多)使流动性高；长链、饱和脂肪酸降低流动性；胆固醇双向调节。","kp":"ch02_s0_30","oe":["脂肪酸链越长，疏水相互作用越强，膜流动性越低，故该说法错误。","不饱和脂肪酸含双键、尾部弯曲，使膜脂排列疏松，流动性升高，正确。","胆固醇具双向调节作用：高温降低流动性、低温阻止凝固，并非总是增加。","饱和脂肪酸链排列紧密，越多则膜流动性越低，故该说法错误。"]},{"id":"ch02_mcq_11","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"研究膜分子扩散速率的经典技术是？","o":["A. FRAP","B. PCR","C. SDS-PAGE","D. 电镜"],"a":"A","e":"荧光漂白恢复技术(FRAP)：标记→激光漂白→观察荧光恢复→测定扩散速率。","kp":"ch02_s0_29","oe":["FRAP荧光漂白恢复技术可标记并漂白膜分子，观察荧光恢复以测扩散速率，正确。","PCR是体外扩增DNA的技术，与膜分子扩散速率研究无关。","SDS-PAGE是分离蛋白质的电泳技术，不能测定膜分子扩散速率。","电镜用于观察膜的超微结构，无法直接测定膜分子的扩散速率。"]},{"id":"ch02_mcq_12","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"人工脂双层对下列哪种物质通透性最低？","o":["A. O2","B. H2O","C. 葡萄糖","D. Na+等离子"],"a":"D","e":"离子几乎不能通过人工脂双层，需通道/载体蛋白。通透性：疏水分子>小极性分子>大极性分子>离子。","kp":"ch02_s0_15","oe":["O2为疏水小分子，可自由溶于脂双层并扩散，通透性高。","H2O为小极性分子，可缓慢通过脂双层，通透性并非最低。","葡萄糖为大极性分子，通透性较低但仍可测出，不是最低。","Na+等为带电离子，几乎不能通过人工脂双层，通透性最低，正确。"]},{"id":"ch02_mcq_13","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"通道蛋白的特点是？","o":["A. 需与运输分子结合","B. 只参与被动运输,转运速率最快","C. 逆浓度梯度运输","D. 需消耗ATP"],"a":"B","e":"通道蛋白形成亲水通道，不需与底物结合，只参与被动运输，转运速率最快；有电压/配体/应力三种门控。","kp":"ch02_s0_25","oe":["通道蛋白形成亲水通道，转运时无需与被转运分子结合，故该说法错误。","通道蛋白只介导被动运输且转运速率最快，符合其特点，正确。","通道蛋白只能顺电化学梯度转运，不能逆浓度梯度运输。","通道蛋白介导被动运输，不需要消耗ATP。"]}],"judge":[{"id":"ch02_judge_1","modI":0,"q":"流动镶嵌模型由Singer和Nicolson于1972年提出。","a":"对","e":"1972年Singer和Nicolson提出流动镶嵌模型，是膜结构研究的里程碑。","kp":"ch02_s0_2","oe":["1972年Singer和Nicolson提出流动镶嵌模型，是膜结构研究的里程碑。","误记为1972年由其他学者提出，或年代记错，故判错。"]},{"id":"ch02_judge_2","modI":0,"q":"甘油磷脂是膜脂中含量最高的成分，占膜脂50%以上。","a":"对","e":"甘油磷脂为膜脂基本成分，占整个膜脂50%以上。","kp":"ch02_s0_7","oe":["甘油磷脂是膜脂基本成分，占整个膜脂50%以上，含量最高。","误把胆固醇或糖脂当成含量最高成分，故判错。"]},{"id":"ch02_judge_3","modI":0,"q":"胆固醇自身能形成脂双层，是构成膜骨架的主要成分。","a":"错","e":"胆固醇自身不能形成脂双层，只能插入磷脂分子之间，起调节流动性等作用。","kp":"ch02_s0_9","oe":["若以为胆固醇能独立形成脂双层则判对，混淆了它与磷脂的作用。","胆固醇自身不能形成脂双层，只能插入磷脂分子间调节流动性，非膜骨架。"]},{"id":"ch02_judge_4","modI":0,"q":"膜脂和膜蛋白在膜上呈不对称分布，糖脂的糖基位于细胞外侧。","a":"对","e":"膜脂、膜蛋白均呈不对称分布；糖蛋白和糖脂的糖基位于质膜外侧(非胞质面)。","kp":"ch02_s0_11","oe":["膜脂与膜蛋白均不对称分布，糖脂糖基位于质膜外侧非胞质面。","误以为糖基位于胞质面或膜分布对称，故判错。"]},{"id":"ch02_judge_5","modI":0,"q":"温度降低到相变温度以下时，膜脂由液晶态转变为凝胶态，流动性降低。","a":"对","e":"温度是影响膜流动性最主要的因素；降至相变温度以下膜脂由液晶态变凝胶态。","kp":"ch02_s0_30","oe":["温度降至相变温度以下，膜脂由液晶态转为凝胶态，流动性降低。","误以为降温使流动性升高，或相变方向记反，故判错。"]},{"id":"ch02_judge_6","modI":0,"q":"不饱和脂肪酸含量越高，膜流动性越低。","a":"错","e":"不饱和脂肪酸含双键、分子弯曲、排列疏松，含量越高流动性越高。","kp":"ch02_s0_34","oe":["若以为不饱和脂肪酸多则流动性低则判对，实则相反。","不饱和脂肪酸含双键、分子弯曲、排列疏松，含量越高流动性越高。"]}],"fill":[{"id":"ch02_fill_1","modI":0,"q":"生物膜流动镶嵌模型由________和________于________年提出。","a":"Singer,Nicolson,1972","kp":"ch02_s0_2","oe":["1972年Singer提出流动镶嵌模型，强调膜脂双层的流动性。","Nicolson与Singer共同提出流动镶嵌模型，阐明膜蛋白镶嵌分布。","该模型于1972年提出，取代了此前的三明治模型。"]},{"id":"ch02_fill_2","modI":0,"q":"膜脂三大类是________、________和________,都是________分子。","a":"甘油磷脂,鞘脂,胆固醇,两性","kp":"ch02_s0_6","oe":["甘油磷脂是膜脂主要成分，以甘油为骨架连接两条脂肪酸链。","鞘脂以鞘氨醇为骨架，是膜脂的另一大类。","胆固醇插入磷脂之间，调节膜的流动性和稳定性。","三类膜脂均含亲水头和疏水尾，属两性分子。"]},{"id":"ch02_fill_3","modI":0,"q":"占膜脂50%以上的是________；不能自身形成脂双层、只能插入磷脂之间的是________。","a":"甘油磷脂,胆固醇","kp":"ch02_s0_15","oe":["甘油磷脂占膜脂50%以上，是构成脂双层的主要成分。","胆固醇不能自身形成脂双层，只能插入磷脂分子之间起调节作用。"]},{"id":"ch02_fill_4","modI":0,"q":"膜脂运动的基本方式是________；双层分子间的________运动较慢。","a":"侧向运动,翻转(flip-flop)","kp":"ch02_s0_12","oe":["膜脂分子在同一层内进行侧向运动，是最基本的运动方式。","脂分子从一层翻转到另一层的翻转运动很慢，需酶协助。"]},{"id":"ch02_fill_5","modI":0,"q":"膜内在蛋白以________或________方式跨膜；外周蛋白以________键结合在膜上。","a":"α-螺旋,β-折叠,非共价","kp":"ch02_s0_21","oe":["膜内在蛋白多以α-螺旋跨膜，疏水氨基酸侧链与膜脂疏水区结合。","部分跨膜蛋白以β-折叠桶形式跨膜，可形成通道结构。","外周蛋白以非共价键(离子键、氢键)结合在膜表面或内在蛋白上。"]},{"id":"ch02_fill_6","modI":0,"q":"影响膜流动性最主要的因素是________；不饱和脂肪酸越多,流动性越________。","a":"温度,高","kp":"ch02_s0_30","oe":["温度是影响膜流动性最主要的因素，适当升温使流动性增大。","不饱和脂肪酸越多，脂肪酸链排列越松散，膜流动性越高。"]},{"id":"ch02_fill_12","modI":0,"q":"脂筏是膜上________、________等富集的微区域,1988年提出________模型。","a":"胆固醇,鞘磷脂,脂筏(Lipid raft)","kp":"ch02_s0_4","oe":["脂筏富含胆固醇，使膜局部有序、增厚并降低流动性。","鞘磷脂长饱和酰链与胆固醇紧密堆积，形成有序筏状微区。","1988年Simons提出脂筏模型，指膜上富含胆固醇和鞘磷脂的微区。"]}],"short":[{"id":"ch02_short_1","modI":0,"q":"简述生物膜流动镶嵌模型的主要内容。","a":"流动镶嵌模型(1972, Singer & Nicolson)主要内容：\n\n①磷脂双分子层是生物膜的基本结构组分——磷脂具有极性头部(亲水)和非极性尾部(疏水)，在水溶液中自动装配成脂双层；\n②膜蛋白以不同方式镶嵌于脂双层：内在蛋白(跨膜)、外周蛋白(非共价结合)、脂锚定蛋白(共价连接)；\n③膜脂和膜蛋白具有流动性——膜脂可侧向运动、翻转、摆动、自旋；膜蛋白可侧向扩散；\n④膜脂和膜蛋白分布具有不对称性——糖脂/糖蛋白的糖基位于质膜外侧；\n⑤脂类与蛋白质的流动性和不对称性是它们相互作用及与其他生物大分子相互作用的基础；\n⑥这种相互作用又一定程度上限制了膜蛋白和膜脂的流动性。\n\n【发展】此后提出脂筏模型(1988)：膜上胆固醇、鞘磷脂富集形成相对独立的微区域。\n【意义】解释了膜的许多性质：物质运输、信号转导、细胞融合等。","kp":"ch02_s0_2"},{"id":"ch02_short_2","modI":0,"q":"简述膜脂的种类、特性及其对膜流动性的影响。","a":"膜脂分三大类：\n①甘油磷脂(占膜脂50%以上)：磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇；\n②鞘脂：鞘氨醇衍生物，分鞘磷脂、鞘糖脂，主要在高尔基体合成；\n③胆固醇：4环碳氢化合物，自身不能形成脂双层，插入磷脂之间。\n都是两性分子(亲水头+疏水尾)。\n\n膜脂特性：\n①不对称性——磷脂、糖脂分布完全不对称，糖脂位于胞外侧，胆固醇均等分布；\n②流动性——侧向运动(基本)、翻转、尾部摆动、自旋。\n\n影响膜流动性的因素：\n①温度(最主要)——温度高流动性大，降至相变温度以下变凝胶态；\n②脂肪酸链长度——短链流动性高；\n③不饱和程度——不饱和度高(双键多)流动性高；\n④胆固醇——双向调节(相变温度以上降低流动性、以下防止凝固)。","kp":"ch02_s0_32"},{"id":"ch02_short_3","modI":0,"q":"简述膜蛋白的类型及分离方法。","a":"膜蛋白类型(按与膜结合方式)：\n\n①膜内在蛋白/跨膜蛋白(intrinsic/integral)：以α-螺旋或β-折叠跨膜，如跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白。\n②外周膜蛋白(peripheral)：以非共价键结合在膜脂极性头部或内在蛋白上，如红细胞膜骨架的血影蛋白、肌动蛋白。\n③脂锚定蛋白：与膜脂特定脂类共价连接，虽位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放，如小G蛋白。\n\n分离方法：\n①外周蛋白——高盐、改变pH或离子强度可洗脱；\n②内在蛋白——需去垢剂(离子型如SDS，非离子型如Triton X-100)溶解；\n③脂锚定蛋白——需特定酶释放。\n\n去垢剂：离子型(SDS)破坏非共价键、可能变性；非离子型(Triton X-100)温和、保持活性。","kp":"ch02_s0_25"}],"calc":[{"id":"ch02_calc_1","modI":0,"q":"论述生物膜的不对称性及其生物学意义。","a":"膜脂和膜蛋白的不对称分布是生物膜的基本特征,具有重要功能意义","steps":"【不对称性的表现】\n①膜脂：磷脂、糖脂分布完全不对称——糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布在两侧；同一种膜脂两侧比例不同。\n②膜蛋白：分布不对称——如肠上皮细胞顶端面与基底面的转运蛋白不同(protein A、B)。\n③糖类：糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。\n\n【生物学意义】\n①决定细胞极性——上皮细胞顶端与基底面功能不同(吸收vs转运)；\n②细胞识别与免疫——糖基位于外侧，血型抗原(A/B/AB/O)由膜糖脂/糖蛋白决定；\n③信号转导——受体、G蛋白等不对称分布，保证信号方向性；\n④物质运输——载体/通道蛋白定向分布，实现跨细胞转运(如小肠吸收葡萄糖)；\n⑤细胞融合、分裂、运动的基础。\n\n【结论】不对称性与流动性共同构成生物膜的两大特征，是膜功能多样性的分子基础。","kp":"ch02_s0_11"},{"id":"ch02_calc_3","modI":0,"q":"论述膜流动性及其影响因素和生物学意义。","a":"膜流动性是生物膜的基本特征,由多种因素调节,是生命活动的必要条件","steps":"【流动性的表现】\n膜脂：侧向运动(基本)、翻转运动(慢)、尾部摆动、绕轴自旋；膜蛋白：侧向扩散。\n\n【影响因素】\n①温度(最主要)：温度高流动性大；降至相变温度以下，膜脂由液晶态→凝胶态；\n②脂肪酸链长度：短链含量高→流动性高；\n③不饱和程度：不饱和脂肪酸(双键多)使分子弯曲、排列疏松→流动性高；饱和脂肪酸排列紧密→流动性低；\n④胆固醇：双向调节——相变温度以上减弱脂肪酸链运动、降低流动性；以下阻止紧密排列、防止凝固；\n⑤膜蛋白与骨架的限制。\n\n【研究方法】FRAP(荧光漂白恢复)测定扩散速率。\n\n【生物学意义】\n①物质运输：膜融合、胞吞胞吐；\n②信号转导：受体聚集、脂筏动态；\n③细胞运动、分裂、融合；\n④膜蛋白功能发挥。\n\n【结论】膜流动性使细胞能进行各种生命活动，是细胞生存的必要条件。","kp":"ch02_s0_30"}],"term":[{"id":"ch02_term_1","modI":0,"term":"流动镶嵌模型(Fluid Mosaic Model)","def":"①1972年Singer和Nicolson提出的生物膜结构模型（定义）。②内容：磷脂双分子层为基本骨架；膜蛋白以不同方式镶嵌其中；膜脂和膜蛋白具流动性；分布具不对称性（内容）。③意义：解释膜的多种性质(运输、信号、融合)，是膜生物学的里程碑（意义）。","kps":"踩分点:①提出者年份(1分)②内容(2分)③意义(1分)","kp":"ch02_s0_2"},{"id":"ch02_term_2","modI":0,"term":"脂筏(Lipid Raft)","def":"①膜上胆固醇、鞘磷脂等富集形成的相对独立的微区域(1988提出)（定义）。②特点：异质性、高度动态、分子排列较紧密（特点）。③组成：含250多种蛋白；非离子去垢剂(如Triton X-100)可分离（组成）。④功能：参与细胞信息传递、物质运输等（功能）。","kps":"踩分点:①定义(1分)②特点(1分)③组成(1分)④功能(1分)","kp":"ch02_s0_4"},{"id":"ch02_term_3","modI":0,"term":"膜脂的不对称性","def":"①同一种膜脂在脂双层两侧分布比例不同、呈不对称分布的现象（定义）。②表现：磷脂、糖脂分布完全不对称，糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布（表现）。③意义：决定细胞极性、细胞识别(血型抗原)、信号转导方向性（意义）。","kps":"踩分点:①定义(1分)②表现(2分)③意义(1分)","kp":"ch02_s0_11"},{"id":"ch02_term_4","modI":0,"term":"膜流动性(Membrane Fluidity)","def":"①膜脂和膜蛋白在膜内运动的能力（定义）。②膜脂运动方式：侧向运动(基本)、翻转、尾部摆动、自旋（方式）。③影响因素：温度(最主要)、脂肪酸链长度、不饱和程度、胆固醇（因素）。④意义：是细胞进行物质运输、信号转导、融合、分裂等生命活动的必要条件（意义）。","kps":"踩分点:①定义(1分)②运动方式(1分)③影响因素(1分)④意义(1分)","kp":"ch02_s0_13"},{"id":"ch02_term_5","modI":0,"term":"膜内在蛋白(Integral Protein)","def":"①与膜脂疏水区紧密结合、需去垢剂才能溶解的膜蛋白（定义）。②跨膜方式：α-螺旋或β-折叠（方式）。③举例：跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白（举例）。④分离：需离子型/非离子型去垢剂溶解（分离）。","kps":"踩分点:①定义(1分)②跨膜方式(1分)③举例(1分)④分离(1分)","kp":"ch02_s0_21"},{"id":"ch02_term_6","modI":0,"term":"外周膜蛋白(Peripheral Protein)","def":"①以非共价键结合在膜脂极性头部或内在蛋白上的膜蛋白（定义）。②特点：不插入脂双层疏水区（特点）。③举例：红细胞膜骨架的血影蛋白、肌动蛋白（举例）。④分离：高盐、改变pH或离子强度可洗脱（分离）。","kps":"踩分点:①定义(1分)②特点(1分)③举例(1分)④分离(1分)","kp":"ch02_s0_23"},{"id":"ch02_term_7","modI":0,"term":"脂锚定蛋白","def":"①与膜脂特定脂类以共价键连接于膜上的膜蛋白（定义）。②特点：位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放（特点）。③举例：小G蛋白(Ras等)（举例）。","kps":"踩分点:①定义(1分)②特点(2分)③举例(1分)","kp":"ch02_s0_24"},{"id":"ch02_term_8","modI":0,"term":"脂质体(Liposome)","def":"①人工把纯磷脂/磷脂酰胆碱加入水中自我装配形成的封闭球形小泡，直径25nm-1mm（定义）。②结构：脂双层包围水相（结构）。③应用：生物膜研究模型、膜蛋白研究、药物靶向递送载体（应用）。","kps":"踩分点:①定义(1分)②结构(1分)③应用(2分)","kp":"ch02_s0_16"},{"id":"ch02_term_9","modI":0,"term":"去垢剂(Detergent)","def":"①能溶解膜蛋白的两亲性物质（定义）。②分类：离子型(如SDS)——破坏非共价键、可能变性；非离子型(如Triton X-100)——温和、保持活性（分类）。③用途：溶解膜内在蛋白、分离纯化膜蛋白（用途）。","kps":"踩分点:①定义(1分)②分类(2分)③用途(1分)","kp":"ch02_s0_20"}]},{"i":1,"name":"模块二：跨膜运输","slides":[{"i":0,"sec":"第一节 膜的组成","title":"胆固醇对流动性的调节 (p45)","notes":"胆固醇对细胞膜磷脂分子流动性的调节作用随温度不同而改变：相变温度以上，它能使磷脂的脂肪酸链运动性减弱，从而降低细胞膜磷脂分子的流动性；相变温度以下，它又能阻止脂肪酸链紧密排列，防止膜凝固。胆固醇是膜流动性的'缓冲器'。","page":45,"level":"掌握","img":"assets/img/ch02/p045.jpg","anim":null,"fig":"胆固醇对膜流动性的双向调节：温度较高时，胆固醇限制磷脂运动、降低流动性；温度较低时，胆固醇阻止磷脂尾紧密堆积、维持流动性。图给出流动性-温度曲线在有无胆固醇时的差异。","points":["相变温度以上：使脂肪酸链运动性减弱，降低流动性","相变温度以下：阻止脂肪酸链紧密排列，防止膜凝固","胆固醇是膜流动性的“缓冲器”"],"check":{"q":"关于胆固醇对细胞膜磷脂流动性的调节，叙述正确的是（　）","o":["A. 通过与膜脂共价结合使膜永久凝固","B. 随温度升高不断促进磷脂分子流动","C. 相变温度以上降低膜流动性，相变温度以下防止膜凝固","D. 只存在于植物细胞膜并提高其流动性"],"a":"C","e":"胆固醇是膜流动性的“缓冲器”，高温时减弱脂肪酸链运动、低温时阻止其紧密排列。","oe":["胆固醇与膜脂非共价结合，不会使膜永久凝固。","胆固醇对流动性起缓冲作用，并非随温度升高而促进流动。","温度高时减弱脂肪酸链运动而降低流动性，低温时阻止紧密排列，正确。","胆固醇主要存在于动物细胞膜，植物细胞膜中含量很少。"]},"cards":[{"front":"胆固醇如何在不同温度下调节膜流动性？","back":"相变温度以上：减弱脂肪酸链运动，降低流动性；相变温度以下：阻止脂肪酸链紧密排列，防止膜凝固。","mnemonic":"高温刹车，低温防冻——膜的缓冲器","type":"功能","useImg":false,"blank":"相变温度","blank2":"流动性"}],"mem":"高温刹车，低温防冻——膜的缓冲器","big":"assets/img/ch02/big/p045.jpg","summary":"胆固醇对细胞膜磷脂分子流动性的调节作用随温度不同而改变：相变温度以上，它能使磷脂的脂肪酸链运动性减弱，从而降低细胞膜磷脂分子的流动性；相变温度以下，它又能阻止脂肪酸链紧密排列，防止","goal":"学完应能掌握并运用「胆固醇对流动性的调节」的核心内容，能解释其机制、比较相关概念。","intuition":"胆固醇像“双向缓冲器”：温度高时它压住乱动、降低流动性；温度低时它又插进去阻止脂链排紧、防止膜凝固。"},{"i":1,"sec":"第二节 跨膜运输","title":"跨膜运输的途径 (p46)","notes":"跨膜运输的途径：①被动运输(passive transport)——顺浓度梯度，不需能量；②主动运输(active transport)——逆浓度梯度，需能量。Transmembrane Transport of Ions and Small Molecules。\n\n【本页英文讲解】\n本页概括跨膜运输（transmembrane transport）的两条基本途径。被动运输（passive transport）指物质顺浓度梯度（或电化学梯度）跨膜，不需细胞代谢供能；主动运输（active transport）指物质逆浓度梯度跨膜，需消耗能量。该页点明离子与小分子跨膜运输的总框架，是翟中和《细胞生物学》第4版第五章物质跨膜运输的纲领性内容，常考两类运输的区别、特点与实例。","page":46,"level":"掌握","img":"assets/img/ch02/p046.jpg","anim":null,"fig":null,"points":["被动运输：顺浓度梯度，不需能量","主动运输：逆浓度梯度，需能量","两者最本质区别在于是否逆浓度梯度、是否耗能"],"check":{"q":"被动运输与主动运输最本质的区别是（　）","o":["A. 被动运输只运输水，主动运输只运输离子","B. 被动运输顺浓度梯度不耗能，主动运输逆浓度梯度耗能","C. 被动运输需载体蛋白，主动运输不需任何蛋白","D. 两者都逆浓度梯度进行，只是所需载体不同"],"a":"B","e":"被动运输顺浓度(电化学)梯度、不耗能；主动运输逆浓度梯度、需消耗能量。","oe":["两类运输均可运送多种离子与小分子，并不限于水和离子。","被动运输顺电化学梯度、不耗能，主动运输逆梯度、需消耗能量。","被动运输中的协助扩散才需载体，主动运输同样需载体蛋白。","被动运输顺浓度梯度，只有主动运输逆浓度梯度进行。"]},"cards":[{"front":"跨膜运输有哪两条基本途径？","back":"①被动运输：顺浓度梯度，不需能量；②主动运输：逆浓度梯度，需能量。","mnemonic":"被动顺流不耗能，主动逆流要供能","type":"流程","useImg":false,"blank":"被动运输","blank2":"主动运输"}],"mem":"被动顺流不耗能，主动逆流要供能","big":"assets/img/ch02/big/p046.jpg","summary":"跨膜运输的途径：①被动运输(passive transport)——顺浓度梯度，不需能量；②主动运输(active transport)——逆浓度梯度，需能量","goal":"学完应能掌握并运用「跨膜运输的途径」的核心内容，能解释其机制、比较相关概念。","intuition":"物质过膜像“进城的不同方式”：小的可自由穿、有的走通道/载体、有的靠泵耗能，大的靠膜泡运输。"},{"i":2,"sec":"第二节 跨膜运输","title":"人工脂双层的通透性 (p47)","notes":"Permeability of a synthetic lipid bilayer：人工脂双层对小分子/离子的通透性不同。疏水分子(O2、CO2、N2、激素)易通过；小的不带电极性分子(H2O、尿素、甘油)较易；大的不带电极性分子(葡萄糖、蔗糖)难通过；离子(Na+、K+、Cl-)几乎不能通过。","page":47,"level":"掌握","img":"assets/img/ch02/p047.jpg","anim":"membrane_permeability","fig":"人工膜对物质的通透性顺序：疏水小分子(O₂、CO₂、苯)易透过；水、尿素次之；葡萄糖、离子(Na⁺、K⁺)难透过。图用透过速率排序，说明“越小越疏水越易透过”。","points":["疏水分子(O₂、CO₂、N₂、激素)最易通过人工脂双层","小的不带电极性分子(H₂O、尿素、甘油)较易通过","大的不带电分子(葡萄糖、蔗糖)难通过；离子几乎不能通过"],"check":{"q":"下列物质中最容易通过人工脂双层的是（　）","o":["A. 葡萄糖","B. K+","C. O2、CO2等疏水分子","D. 蔗糖"],"a":"C","e":"疏水分子（O2、CO2、N2、激素）最易通过人工脂双层，离子几乎不能通过，葡萄糖、蔗糖等大分子难通过。","oe":["葡萄糖为大分子不带电极性分子，难通过","K+等离子几乎不能通过人工脂双层","正确，O2、CO2等疏水分子最易通过","蔗糖为大分子，难以通过人工脂双层"]},"cards":[{"front":"人工脂双层对不同物质的通透性顺序如何？","back":"疏水分子(O2、CO2、N2、激素)最易通过；小不带电极性分子(H2O、尿素、甘油)较易；大不带电极性分子(葡萄糖、蔗糖)难通过；离子(Na+、K+、Cl-)几乎不能通过。","mnemonic":"疏水易过，离子难行","type":"对比","useImg":true,"blank":"疏水分子","blank2":"离子"}],"mem":"疏水易过，离子难行","big":"assets/img/ch02/big/p047.jpg","summary":"Permeability of a synthetic lipid bilayer：人工脂双层对小分子/离子的通透性不同","goal":"学完应能掌握并运用「人工脂双层的通透性」的核心内容，能解释其机制、比较相关概念。","intuition":"用人工脂双层做“裸门测试”：不带泵和通道时，只有小、不带电、脂溶性的分子容易过，亲水/带电的几乎过不去——说明真细胞需要专门的转运蛋白。"},{"i":3,"sec":"第二节 跨膜运输","title":"水的极性 (p48)","notes":"共价键中电子共享不均等时产生极性和部分正、负电荷，如水(H2O)。水是极性分子，虽小但跨膜需水通道。","page":48,"level":"理解","img":"assets/img/ch02/p048.jpg","anim":null,"fig":null,"points":["共价键中电子共享不均产生极性，水是极性分子","水虽小但跨膜主要依赖水通道"],"check":{"q":"关于水分子及其跨膜运输，叙述正确的是（　）","o":["A. 水为极性分子，因此不能通过细胞膜","B. 水是极性小分子，虽小但跨膜需水通道","C. 水是非极性脂溶性分子，可自由简单扩散","D. 水的极性源于分子内电子共享完全均匀"],"a":"B","e":"水的共价键中电子共享不均而产生极性，它虽是极性小分子但跨膜主要依赖水通道。","oe":["水虽为极性但仍可经水通道蛋白跨膜，并非完全不能透过。","水的共价键电子共享不均产生极性，跨膜主要依赖水通道。","水为极性分子、脂溶性差，难以直接自由扩散穿过脂双层。","水分子中氧吸电子，电子共享不均才产生极性。"]},"cards":null,"mem":"水是极性分子，虽小仍靠水通道跨膜","big":"assets/img/ch02/big/p048.jpg","summary":"共价键中电子共享不均等时产生极性和部分正、负电荷，如水(H2O)","goal":"学完应能理解并说明「水的极性」。"},{"i":4,"sec":"第二节 跨膜运输","title":"被动运输 (p49)","notes":"选择性的跨膜物质运输。1)被动运输——顺浓度梯度：①简单扩散——不需要能量、不需载体，如O2、CO2；②协助扩散——需载体/通道蛋白，顺浓度梯度，不耗能。","page":49,"level":"掌握","img":"assets/img/ch02/p049.jpg","anim":"facilitated_diffusion","fig":null,"points":["被动运输顺浓度梯度、不耗能","简单扩散不需载体，如O₂、CO₂","协助扩散需载体或通道蛋白，顺浓度梯度、不耗能"],"check":{"q":"下列属于被动运输中简单扩散特点的是（　）","o":["A. 顺浓度梯度，不需能量也不需载体蛋白","B. 需通道蛋白协助并逆浓度梯度运输","C. 需ATP供能并逆浓度梯度运输","D. 需载体蛋白协助并顺浓度梯度运输"],"a":"A","e":"简单扩散如O2、CO2，顺浓度梯度直接穿过脂双层，不耗能也不需载体。","oe":["简单扩散如O2、CO2，顺浓度梯度直接穿过脂双层，不耗能不需载体。","需通道蛋白且逆浓度梯度与简单扩散的特点不符。","需ATP、逆浓度梯度的是主动运输，不属于简单扩散。","需载体蛋白、顺浓度梯度的是协助扩散，不是简单扩散。"]},"cards":[{"front":"被动运输包括哪两种方式？各有何特点？","back":"①简单扩散：不需能量、不需载体，如O2、CO2；②协助扩散：需载体或通道蛋白，顺浓度梯度，不耗能。","mnemonic":"简单靠自由，协助靠蛋白","type":"对比","useImg":false,"blank":"协助扩散","blank2":"简单扩散"}],"mem":"简单靠自由，协助靠蛋白","big":"assets/img/ch02/big/p049.jpg","summary":"选择性的跨膜物质运输","goal":"学完应能掌握并运用「被动运输」的核心内容，能解释其机制、比较相关概念。","intuition":"被动运输像“水往低处流”：顺浓度梯度、不耗能。简单扩散是“直接淌过去”（如 O₂、CO₂）；协助扩散则要“过闸机”——靠通道或载体蛋白帮忙，但依然只下坡、不烧 ATP。"},{"i":5,"sec":"第二节 跨膜运输","title":"通道蛋白 (p50)","notes":"通道蛋白：在膜上形成跨膜的亲水通道，使离子从中通过，不需要与运输分子结合。只参与被动运输，转运速率最快。三种门控：膜电压门控、配体门控、应力门控。","page":50,"level":"掌握","img":"assets/img/ch02/p050.jpg","anim":"channel_gating","fig":"通道蛋白的门控机制：①电压门控(膜电位变化)；②配体门控(配体结合)；③机械门控(机械力)。图对比三种门控方式。通道只开放时才能通透，且不与被转运物结合。","points":["形成跨膜亲水通道，不需与被转运分子结合","只参与被动运输，转运速率最快","三种门控：膜电压门控、配体门控、应力门控"],"check":{"q":"关于通道蛋白，下列说法正确的是（　）","o":["A. 运输时需与运输分子结合","B. 可参与主动运输","C. 转运速率比载体蛋白慢","D. 形成跨膜亲水通道，只参与被动运输"],"a":"D","e":"通道蛋白形成跨膜亲水通道，不需与被转运分子结合，只参与被动运输，转运速率最快，有电压、配体、应力三种门控。","oe":["通道蛋白不需要与被转运分子结合","通道蛋白只参与被动运输，不参与主动运输","通道蛋白转运速率最快，比载体快","正确，形成亲水通道，只参与被动运输"]},"cards":[{"front":"通道蛋白运输物质有何特点？有哪几种门控方式？","back":"形成跨膜亲水通道，不需与运输分子结合，只参与被动运输，转运速率最快；门控方式：膜电压门控、配体门控、应力门控。","mnemonic":"通道不结合，最快被动运；电压配体应力三开门","type":"功能","useImg":true,"blank":"跨膜亲水通道","blank2":"被动运输"}],"mem":"通道不结合，最快被动运；电压配体应力三开门","big":"assets/img/ch02/big/p050.jpg","summary":"通道蛋白：在膜上形成跨膜的亲水通道，使离子从中通过，不需要与运输分子结合","goal":"学完应能掌握并运用「通道蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"通道蛋白像“专供某类离子的闸门”：打开时离子顺梯度快速通过，比载体快得多；它不结合转运、只开孔，门控决定开与关。"},{"i":6,"sec":"第二节 跨膜运输","title":"葡萄糖协助扩散 (p51-52)","notes":"动物细胞葡萄糖的协助扩散：载体蛋白GLUT家族通过构象变化将葡萄糖运到细胞内。Glut1介导葡萄糖进入红细胞(维持血糖浓度稳定)、通过血脑屏障。除脂溶性分子和小的不带电分子以简单扩散通过外，几乎所有小有机分子及无机离子穿过细胞膜都需膜蛋白协助。","page":51,"level":"掌握","img":"assets/img/ch02/p051.jpg","anim":null,"fig":"GLUT(葡萄糖载体)通过构象变化转运葡萄糖：结合葡萄糖 → 构象改变 → 把葡萄糖释放到膜另一侧。图显示 GLUT 的“交替构象”模型，属易化扩散(顺浓度梯度、不耗能)。","points":["GLUT家族通过构象变化将葡萄糖运入细胞","Glut1介导葡萄糖进入红细胞、通过血脑屏障","属顺浓度梯度的协助扩散"],"check":{"q":"红细胞摄取葡萄糖所通过的运输方式是（　）","o":["A. 直接以简单扩散方式自由穿过脂双层","B. 经GLUT1载体蛋白介导的协助扩散","C. 经Na+/K+泵介导的主动运输","D. 经水通道蛋白AQP1顺浓度梯度运输"],"a":"B","e":"GLUT1通过构象变化将葡萄糖运入红细胞，属顺浓度梯度的协助扩散。","oe":["葡萄糖为极性分子，不溶于脂双层，无法直接简单扩散。","GLUT1以构象变化介导葡萄糖进入红细胞，属顺浓度梯度协助扩散。","葡萄糖不能经Na+/K+泵转运，该泵专司Na+、K+。","AQP1是水通道，只转运水而不运输葡萄糖。"]},"cards":[{"front":"动物细胞葡萄糖协助扩散的载体是什么？Glut1有何作用？","back":"载体为GLUT家族，通过构象变化转运葡萄糖；Glut1介导葡萄糖进入红细胞，维持血糖浓度稳定，并通过血脑屏障。","mnemonic":"GLUT变构运糖，Glut1进红细胞和脑","type":"例证","useImg":false,"blank":"GLUT家族","blank2":"构象变化"}],"mem":"GLUT变构运糖，Glut1进红细胞和脑","big":"assets/img/ch02/big/p051.jpg","summary":"动物细胞葡萄糖的协助扩散：载体蛋白GLUT家族通过构象变化将葡萄糖运到细胞内","goal":"学完应能掌握并运用「葡萄糖协助扩散」的核心内容，能解释其机制、比较相关概念。","intuition":"葡萄糖靠载体协助扩散像“坐扶梯下坡”：顺浓度梯度、不耗能，但必须有扶手（载体）把分子带过去；红细胞、肌细胞用 GLUT 这类载体。","derive":"【饱和动力学】载体介导的运输服从 v = (Vmax·[S])/(Km + [S])：\n• [S]≪Km 时近似线性(一级)，• [S]≫Km 时趋于 Vmax（饱和）。\n据此可把“有 Vmax、可被竞争性抑制”的协助扩散/主动运输，与“无饱和”的简单扩散区分开。"},{"i":7,"sec":"第二节 跨膜运输","title":"ADP/ATP载体蛋白 (p53)","notes":"线粒体内膜上的ADP/ATP载体蛋白：交换ADP(进)和ATP(出)，是一种小分子膜蛋白，属于载体蛋白介导的跨膜运输，为细胞供能提供保障。","page":53,"level":"理解","img":"assets/img/ch02/p053.jpg","anim":"atp_adp_carrier","fig":null,"points":["线粒体内膜ADP/ATP载体交换ADP(进)与ATP(出)","属载体蛋白介导的跨膜运输"],"check":{"q":"线粒体内膜上ADP/ATP载体蛋白的运输特点是（　）","o":["A. 通道蛋白介导的自由扩散，不具特异性","B. ATP进线粒体、ADP出线粒体，方向相反","C. 消耗ATP把ADP泵出线粒体","D. 载体蛋白介导交换，ADP进线粒体、ATP出线粒体"],"a":"D","e":"该载体属载体蛋白介导的跨膜运输，将ADP运入线粒体、把ATP运出。","oe":["该转运由载体蛋白完成并具特异性，非通道自由扩散。","交换方向相反，应是ADP进入、ATP运出线粒体。","该载体不直接水解ATP，而是交换ADP与ATP。","该载体属载体蛋白介导的跨膜运输，将ADP运入、ATP运出线粒体。"]},"cards":null,"mem":"线粒体内膜ADP/ATP载体：ADP进、ATP出","big":"assets/img/ch02/big/p053.jpg","summary":"线粒体内膜上的ADP/ATP载体蛋白：交换ADP(进)和ATP(出)，是一种小分子膜蛋白，属于载体蛋白介导的跨膜运输，为细胞供能提供保障","goal":"学完应能理解并说明「ADP/ATP载体蛋白」。"},{"i":8,"sec":"第二节 跨膜运输","title":"2003年诺贝尔化学奖 (p54)","notes":"2003年诺贝尔化学奖授予物质跨膜运输研究——水通道及钾离子通道：Peter Agre因发现水通道获奖，Roderick MacKinnon因解析钾通道结构获奖。","page":54,"level":"掌握","img":"assets/img/ch02/p054.jpg","anim":null,"fig":null,"points":["2003年诺贝尔化学奖授予跨膜运输研究","Peter Agre 发现水通道；Roderick MacKinnon 解析钾通道结构"],"check":{"q":"水通道和钾离子通道的结构研究主要揭示了细胞哪一生理过程？","o":["A. 蛋白质的生物合成","B. 物质跨膜运输","C. DNA的复制与修复","D. 细胞呼吸与氧化磷酸化"],"a":"B","e":"水通道与钾离子通道的研究属于物质跨膜运输领域，阐明了水和K⁺跨膜运输的分子机制。","oe":["错：通道研究与蛋白合成无关，不符合本页所学概念","对：页面明确其属跨膜运输研究，与笔记原文相符","错：与DNA复制修复无关，不符合本页所学概念","错：通道不参与呼吸链，不符合本页所学概念"],"basis":"物质跨膜运输研究——水通道及钾离子通道"},"cards":[{"front":"2003年诺贝尔化学奖授予了哪两位科学家？各自贡献是什么？","back":"Peter Agre——发现水通道；Roderick MacKinnon——解析钾通道结构","mnemonic":"Agre水，MacKinnon钾","type":"例证","useImg":false,"blank":"水通道","blank2":"钾通道结构"}],"mem":"Agre水，MacKinnon钾","big":"assets/img/ch02/big/p054.jpg","summary":"年诺贝尔化学奖授予物质跨膜运输研究——水通道及钾离子通道：Peter Agre因发现水通道获奖，Roderick MacKinnon因解析钾通道结构获奖","goal":"学完应能掌握并运用「2003年诺贝尔化学奖」的核心内容，能解释其机制、比较相关概念。","intuition":"2003 年诺奖授予 Agre（发现水通道）和 MacKinnon（解析钾通道结构），表彰膜运输研究。"},{"i":9,"sec":"第二节 跨膜运输","title":"水通道的发现 (p55-56)","notes":"2003年诺贝尔化学奖——'For the discovery of water channels'(水通道)。实验：将AQP1的mRNA注入非洲爪蟾卵母细胞，在低渗溶液中卵母细胞迅速膨胀并于5分钟内破裂——证明AQP1是水通道。","page":55,"level":"掌握","img":"assets/img/ch02/p055.jpg","anim":"water_channel","fig":null,"points":["将AQP1的mRNA注入非洲爪蟾卵母细胞","低渗溶液中卵母细胞迅速膨胀、5分钟内破裂","证明AQP1是水通道"],"check":{"q":"证明AQP1是水通道的关键实验是（　）","o":["A. 用GFP标记AQP1后观察其在细胞内的定位","B. 将AQP1 mRNA注入卵母细胞后低渗下细胞形态不变","C. 将AQP1 mRNA注入爪蟾卵母细胞，低渗下卵母细胞迅速膨胀破裂","D. 在细菌中敲除AQP1基因后水的转运明显增强"],"a":"C","e":"表达AQP1的卵母细胞在低渗液中迅速吸水膨胀、5分钟内破裂，证明AQP1是水通道。","oe":["GFP标记只能显示定位，不能直接证明其水转运功能。","若形态不变则不能证明AQP1具水通道功能，与实验相反。","表达AQP1的卵母细胞在低渗液中迅速吸水膨胀、5分钟内破裂，证明其为水通道。","敲除后水转运应减弱而非增强，方向错误。"]},"cards":[{"front":"证明AQP1是水通道的关键实验是什么？","back":"将AQP1 mRNA注入非洲爪蟾卵母细胞；低渗溶液中细胞迅速膨胀，5分钟内破裂","mnemonic":"注mRNA，低渗胀破","type":"流程","useImg":true,"blank":"非洲爪蟾卵母细胞","blank2":"低渗溶液"}],"mem":"注mRNA，低渗胀破","big":"assets/img/ch02/big/p055.jpg","summary":"年诺贝尔化学奖——'For the discovery of water channels'(水通道)","goal":"学完应能掌握并运用「水通道的发现」的核心内容，能解释其机制、比较相关概念。","intuition":"水通道的发现像“找到水专用的快车道”：之前以为水只能慢慢渗过膜，发现 AQP 后才明白细胞能快速运水（Agre 因此获诺奖）。"},{"i":10,"sec":"第二节 跨膜运输","title":"水跨膜运动 (p57)","notes":"Water movement across biological membranes occurs through both：①脂双层(简单扩散，较慢)；②水通道蛋白(aquaporin，快速)。水通道大大加速水的跨膜运输。\n\n【本页英文讲解】\n本页讲解水跨生物膜（biological membrane）的运动方式，共有两条途径：一是直接经脂双层（lipid bilayer）以简单扩散（simple diffusion）通过，速度较慢；二是经水通道蛋白（aquaporin）快速通过。水通道蛋白是介导水高效跨膜转运的膜整合蛋白，可极大加速水的运输。此页对应翟中和教材第五章水通道与协助扩散内容，考点在于区分水的两种跨膜方式及水通道蛋白的生理意义。","page":57,"level":"理解","img":"assets/img/ch02/p057.jpg","anim":null,"fig":"水跨膜运动有两条途径：①简单扩散通过脂双层；②经水通道蛋白(AQP)快速通过。图对比两种方式，水通道大大提高了水的通透效率。","points":["水跨膜有两条途径：经脂双层简单扩散(较慢)","经水通道蛋白(aquaporin)快速通过"],"check":{"q":"关于水跨膜运动的途径，下列说法正确的是（　）","o":["A. 水可通过脂双层简单扩散和水通道快速通过","B. 水只能通过脂双层简单扩散","C. 水通道蛋白属于外周蛋白","D. 水通道降低水的跨膜运输速度"],"a":"A","e":"水跨生物膜运动有两条途径：一是经脂双层简单扩散（较慢），二是经水通道蛋白快速通过。","oe":["正确，有脂双层扩散和水通道两条途径","水还可经水通道蛋白快速跨膜通过","水通道蛋白是膜整合蛋白，非外周蛋白","水通道蛋白大大加速水的跨膜运输"]},"cards":null,"mem":"水跨膜两途：脂双层慢扩散、水通道快","big":"assets/img/ch02/big/p057.jpg","terms":[{"t":"脂双层","en":"lipid bilayer","d":"由磷脂等两性分子自装配成的双分子层，是生物膜的基本骨架，水可缓慢直接透过。"},{"t":"水通道蛋白","en":"aquaporin, AQP","d":"介导水快速跨膜运输的通道蛋白；顺渗透压梯度、不耗能。1990年代由Peter Agre发现。"}],"summary":"Water movement across biological membranes occurs through both：①脂双层(简单扩散，较慢)；②水通道蛋白(aquapo","goal":"学完应能理解并说明「水跨膜运动」。"},{"i":11,"sec":"第二节 跨膜运输","title":"水通道四聚体结构 (p58)","notes":"水通道蛋白(aquaporin)的四聚体结构模型：由4个相同亚基组成，每个亚基含6个跨膜α螺旋，中央形成供水分子的通道。","page":58,"level":"理解","img":"assets/img/ch02/p058.jpg","anim":"aquaporin_tetramer","fig":null,"points":["水通道蛋白由4个相同亚基组成四聚体","每个亚基含6个跨膜α螺旋，中央形成水通道"],"check":{"q":"关于水通道蛋白的四聚体结构，下列说法正确的是（　）","o":["A. 由4个不同亚基组成","B. 每个亚基含4个跨膜α螺旋","C. 中央不形成水通道","D. 由4个相同亚基组成，每个含6个跨膜α螺旋"],"a":"D","e":"水通道蛋白由4个相同亚基组成四聚体，每个亚基含6个跨膜α螺旋，中央形成水通道。","oe":["由4个相同亚基组成，并非不同亚基","每个亚基含6个跨膜α螺旋，不是4个","该四聚体结构的中央形成水通道孔","正确，4个相同亚基，每个6个α螺旋"]},"cards":null,"mem":"水通道四聚体：4亚基、各6跨膜α螺旋成孔","big":"assets/img/ch02/big/p058.jpg","summary":"水通道蛋白(aquaporin)的四聚体结构模型：由4个相同亚基组成，每个亚基含6个跨膜α螺旋，中央形成供水分子的通道","goal":"学完应能理解并说明「水通道四聚体结构」。"},{"i":12,"sec":"第二节 跨膜运输","title":"钾通道结构 (p59)","notes":"来自细菌Streptomyces lividans的静息K+通道结构：由4个亚基组成，中央形成离子通道，含选择性滤器。Roderick MacKinnon解析。\n\n【本页英文讲解】\n本页展示来源于细菌——变铅青链霉菌（Streptomyces lividans）的静息钾通道（K+ channel）结构。该通道由4个亚基（subunit）对称排列，中央围成供K+通过的离子通道，并含选择性滤器（selectivity filter），以保证只通透K+。此结构由罗德里克·麦金农（Roderick MacKinnon）解析，他因此获2003年诺贝尔化学奖。考点为通道蛋白的结构与离子选择机制，属教材第五章协助扩散内容。","page":59,"level":"掌握","img":"assets/img/ch02/p059.jpg","anim":null,"fig":"静息钾通道(KcsA)的结构：由四个亚基组成，中央形成选择性孔道。图显示孔道内的选择性滤器，是理解“钾通道只让 K⁺ 通过”的结构基础。","points":["来自变铅青链霉菌的静息K⁺通道","由4个亚基对称排列，中央形成离子通道","含选择性滤器；由MacKinnon解析"],"check":{"q":"关于静息K+通道的结构，叙述正确的是（　）","o":["A. 由4个亚基组成但只允许Na+通过","B. 由4个亚基围成中央孔道并含选择性滤器","C. 由2个α亚基和2个β亚基组成，无选择性滤器","D. 由单条多肽链折叠形成的简单通道"],"a":"B","e":"变铅青链霉菌的静息K+通道由4个亚基对称排列，中央孔道含选择性滤器。","oe":["选择性滤器只允许K+通过而排斥Na+。","变铅青链霉菌K+通道由4个亚基对称排列，中央孔道含选择性滤器。","α2β2是Na+/K+泵的结构，且K+通道含选择性滤器。","该通道由4个亚基组装而成，并非单条多肽链。"]},"cards":[{"front":"静息K+通道由几个亚基组成？关键结构是什么？","back":"4个亚基组成；中央形成离子通道，含选择性滤器","mnemonic":"四亚基围一孔，滤器把关","type":"组成数字","useImg":true,"blank":"选择性滤器","blank2":"离子通道"}],"mem":"四亚基围一孔，滤器把关","big":"assets/img/ch02/big/p059.jpg","terms":[{"t":"选择性滤器","en":"selectivity filter","d":"钾通道孔道最窄处，由主链羰基氧规则排列，只允许脱水后的K⁺通过。"},{"t":"KcsA","en":"KcsA","d":"来自变铅青链霉菌的静息K⁺通道，是首个解析出晶体结构的钾通道（MacKinnon，1998）。"}],"summary":"来自细菌Streptomyces lividans的静息K+通道结构：由4个亚基组成，中央形成离子通道，含选择性滤器","goal":"学完应能掌握并运用「钾通道结构」的核心内容，能解释其机制、比较相关概念。","intuition":"钾通道像“四人合抱的桶”：四个亚基围成中央孔道。通道打开时 K⁺ 顺梯度飞快外流；它的“开与闭”（门控）和“只认 K⁺”（选择性滤器）是两套独立机制，前者管开关，后者管挑货。"},{"i":13,"sec":"第二节 跨膜运输","title":"水通道的选择性 (p60)","notes":"水通道的严格选择性：①通道直径只有0.28nm，无法通过比水分子大的物质；②通道中心最窄处带正电荷(Arg-195, His-180)，排斥阳离子(如H3O+)，只允许水通过。","page":60,"level":"掌握","img":"assets/img/ch02/p060.jpg","anim":null,"fig":"水通道的 0.28nm 选择性：水通道孔道窄，只允许水分子单列通过，而排斥离子和质子。图显示水通道的窄孔道和水的单列流动，说明“水能过、离子不能过”。","points":["通道直径仅0.28nm，比水大的物质不能通过","通道中心最窄处带正电荷(Arg-195、His-180)","排斥阳离子(如H₃O⁺)，只允许水通过"],"check":{"q":"水通道具有严格选择性的原因是（　）","o":["A. 通道直径很大，可容各种小分子","B. 通道最窄处带负电荷，吸引阳离子","C. 通道最窄处带正电荷，排斥阳离子","D. 通道只允许阴离子通过"],"a":"C","e":"水通道直径仅0.28nm，通道中心最窄处带正电荷（Arg-195、His-180），排斥阳离子如H3O+，只允许水通过。","oe":["通道直径仅0.28nm，比水大的物质不能通过","通道最窄处带正电荷而不是负电荷","正确，最窄处带正电，排斥阳离子","正电荷排斥阳离子，只允许水通过"]},"cards":[{"front":"水通道严格选择性的两个机制是什么？","back":"①通道直径仅0.28nm，大分子不能通过；②最窄处带正电荷(Arg-195、His-180)，排斥阳离子如H3O+","mnemonic":"孔小0.28，正电挡阳离子","type":"功能","useImg":true,"blank":"正电荷"}],"mem":"孔小0.28，正电挡阳离子","big":"assets/img/ch02/big/p060.jpg","summary":"水通道的严格选择性：①通道直径只有0.28nm，无法通过比水分子大的物质；②通道中心最窄处带正电荷(Arg-195, His-180)，排斥阳离子(如H3O+)，只允许水通过","goal":"学完应能掌握并运用「水通道的选择性」的核心内容，能解释其机制、比较相关概念。","intuition":"水通道像“只放水、不放离子的细筛”：孔道极窄并带正电荷，水能排成一列通过，而带电离子、质子被挡住。"},{"i":14,"sec":"第二节 跨膜运输","title":"水通道蛋白家族 (p61)","notes":"Aquaporins是大的蛋白家族，存在于细菌、植物、动物。在哺乳动物中分布于肾脏、红细胞等，参与水的重吸收与转运。","page":61,"level":"理解","img":"assets/img/ch02/p061.jpg","anim":null,"fig":"水通道蛋白家族(AQP)：AQP1 在红细胞/肾；AQP2 在肾集合管，受抗利尿激素调节。图给出不同 AQP 的组织分布。水通道参与水的重吸收和分泌。","points":["Aquaporins是存在于细菌、植物、动物的大蛋白家族","在哺乳动物肾脏、红细胞等参与水的重吸收与转运"],"check":{"q":"关于水通道蛋白(Aquaporins)的叙述，正确的是（　）","o":["A. 是广泛存在于细菌、植物和动物中的大蛋白家族","B. 只存在于哺乳动物的红细胞中","C. 属于脂溶性小分子而非蛋白质","D. 是一类只分布于神经系统的离子通道"],"a":"A","e":"Aquaporins是跨物种的大蛋白家族，在哺乳动物肾脏、红细胞等参与水的重吸收与转运。","oe":["Aquaporins为跨物种的大蛋白家族，在肾脏、红细胞等参与水转运。","除红细胞外还分布于肾脏等多种组织，且存在于多个物种。","水通道蛋白本质是蛋白质，不是脂溶性小分子。","它是水通道而非离子通道，分布也不限于神经系统。"]},"cards":null,"mem":"Aquaporin大家族：细菌植物动物，肾/红细胞重吸收","big":"assets/img/ch02/big/p061.jpg","terms":[{"t":"水通道蛋白","en":"aquaporin, AQP","d":"一大蛋白家族，遍布细菌、植物、动物；哺乳动物中分布于肾、红细胞等，参与水的重吸收与分泌。"}],"summary":"Aquaporins是大的蛋白家族，存在于细菌、植物、动物","goal":"学完应能理解并说明「水通道蛋白家族」。"},{"i":15,"sec":"第二节 跨膜运输","title":"哺乳动物离子分布 (p63)","notes":"哺乳动物细胞内 vs 细胞外液的离子分布不同：胞内高K+、低Na+；胞外高Na+、高Cl-、低K+。这种不均一分布是膜电位和兴奋性的基础。","page":63,"level":"掌握","img":"assets/img/ch02/p063.jpg","anim":null,"fig":"膜两侧离子浓度表：胞外 Na⁺、Cl⁻、Ca²⁺ 高；胞内 K⁺ 高、Na⁺ 低。图用浓度对比说明离子梯度的方向，是理解静息电位和主动运输的基础。","points":["胞内高K⁺、低Na⁺","胞外高Na⁺、高Cl⁻、低K⁺","不均一分布是膜电位与兴奋性的基础"],"check":{"q":"哺乳动物细胞内外离子分布的典型特点是（　）","o":["A. 胞内高Na+低K+，胞外高K+低Na+","B. 胞内高K+低Na+，胞外高Na+高Cl-低K+","C. 胞内高Na+高Cl-，胞外高K+低Na+","D. 细胞内外的离子浓度基本相同"],"a":"B","e":"胞内高K+低Na+、胞外高Na+高Cl-低K+，这种不均一分布是膜电位与兴奋性的基础。","oe":["胞内应为高K+低Na+，此选项恰好相反。","胞内高K+低Na+、胞外高Na+高Cl-低K+，是膜电位与兴奋性的基础。","方向颠倒，胞内应为高K+低Na+、胞外高Na+。","内外离子呈不均一分布，浓度并不基本相同。"]},"cards":[{"front":"哺乳动物细胞内、外液的主要离子分布差异是什么？","back":"胞内：高K+、低Na+；胞外：高Na+、高Cl-、低K+","mnemonic":"内钾外钠，膜电位之基","type":"对比","useImg":false,"blank":"高K+","blank2":"高Na+"}],"mem":"内钾外钠，膜电位之基","big":"assets/img/ch02/big/p063.jpg","summary":"哺乳动物细胞内 vs 细胞外液的离子分布不同：胞内高K+、低Na+；胞外高Na+、高Cl-、低K+","goal":"学完应能掌握并运用「哺乳动物离子分布」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞膜两侧像“被摆好的棋盘”：胞内 K⁺ 高、Na⁺ 低，胞外反过来；这一分布由泵和泄漏通道共同维持，是电位和运输的基础。"},{"i":16,"sec":"第二节 跨膜运输","title":"主动运输与离子泵 (p64)","notes":"2)主动运输——需要能量(ATP/光能、离子梯度等)，逆浓度梯度。①离子泵：动物细胞的Na+/K+泵(Na+/K+-ATPase)，Ca2+泵等。\n\n【本页英文讲解】\n本页进入主动运输（active transport）部分，强调其需消耗能量（如ATP、光能、离子梯度等），并逆浓度梯度进行。其中一类为离子泵（ion pump），典型例子是动物细胞质膜上的Na+/K+泵（Na+/K+-ATPase，钠钾ATP酶）以及Ca2+泵（钙泵）。考点为主动运输的供能方式与离子泵举例，对应翟中和教材第五章，注意区分ATP驱动的离子泵与协同运输。","page":64,"level":"掌握","img":"assets/img/ch02/p064.jpg","anim":null,"fig":null,"points":["主动运输逆浓度梯度，需能量(ATP/光能/离子梯度)","离子泵典型例子：Na⁺/K⁺-ATPase、Ca²⁺泵"],"check":{"q":"下列属于离子泵的典型实例是（　）","o":["A. 质膜上的GLUT1与AQP1","B. 动物细胞质膜上的Na+/K+泵与Ca2+泵","C. 钾泄漏通道与电压门控钾通道","D. 简单扩散与协助扩散"],"a":"B","e":"离子泵消耗能量逆浓度梯度转运离子，典型例子是Na+/K+-ATPase和Ca2+泵。","oe":["GLUT1为葡萄糖载体，AQP1为水通道，均非离子泵。","离子泵消耗ATP逆浓度梯度转运离子，如Na+/K+-ATPase和Ca2+泵。","钾通道属通道蛋白，不消耗ATP泵送离子。","简单扩散和协助扩散都是被动运输，不属于离子泵。"]},"cards":[{"front":"主动运输的定义及典型例子是什么？","back":"需能量(ATP/光能/离子梯度)，逆浓度梯度；例：Na+/K+-ATPase、Ca2+泵","mnemonic":"耗能逆流，泵来搬","type":"定义","useImg":false,"blank":"离子梯度","blank2":"逆浓度梯度"}],"mem":"耗能逆流，泵来搬","big":"assets/img/ch02/big/p064.jpg","summary":")主动运输——需要能量(ATP/光能、离子梯度等)，逆浓度梯度","goal":"学完应能掌握并运用「主动运输与离子泵」的核心内容，能解释其机制、比较相关概念。","intuition":"离子泵像“逆流而上的抽水机”：逆浓度梯度搬离子、必须耗 ATP，才能维持细胞内外离子分布的差距。"},{"i":17,"sec":"第二节 跨膜运输","title":"主动运输的3种动力 (p65)","notes":"主动运输的3种动力方式：①ATP驱动泵(如Na⁺/K⁺-ATPase，直接水解ATP供能)；②离子梯度驱动(协同运输)；③光能驱动(如细菌紫膜质)。","page":65,"level":"掌握","img":"assets/img/ch02/p065.jpg","anim":"active_transport_types","fig":"主动运输的三种动力：①ATP 驱动(ATP 泵，如 Na⁺/K⁺-ATPase)；②离子梯度驱动(协同运输)；③光能驱动(细菌视紫红质)。图对比三种能量来源，强调主动运输逆浓度梯度、耗能。","points":["ATP驱动泵，如Na⁺/K⁺-ATPase","离子梯度驱动（协同运输）","光能驱动，如细菌视紫红质"],"check":{"q":"下列哪组均属于主动运输的驱动力？","o":["A. 浓度梯度引起的自由扩散","B. 水势差引起的渗透","C. ATP水解、离子梯度、光能","D. 单纯的脂溶性扩散"],"a":"C","e":"主动运输逆浓度梯度进行，其动力可来自ATP驱动泵、离子梯度驱动的协同运输以及光能驱动。","oe":["错：顺浓度扩散属被动运输，不符合本页所学概念","错：渗透多为被动过程，不符合本页所学概念","对：与笔记所列三种动力一致，与笔记原文相符","错：脂溶性扩散不耗能，属被动，不符合本页所学概念"],"basis":"①ATP驱动泵；②离子梯度驱动；③光能驱动"},"cards":[{"front":"主动运输的3种动力方式是什么？","back":"①ATP驱动泵(Na+/K+-ATPase)；②离子梯度驱动(协同运输)；③光能驱动(细菌视紫红质)","mnemonic":"ATP、梯度、光，三力驱动","type":"流程","useImg":false,"blank":"ATP驱动泵","blank2":"协同运输"}],"mem":"ATP、梯度、光，三力驱动","big":"assets/img/ch02/big/p065.jpg","terms":[{"t":"驱动泵","en":"Na⁺/K⁺-ATPase","d":"即钠钾泵，水解ATP、逆浓度梯度泵出3Na⁺并泵入2K⁺，属原发性主动运输。"}],"summary":"主动运输的3种动力方式：①ATP驱动泵(如Na⁺/K⁺-ATPase，直接水解ATP供能)；②离子梯度驱动(协同运输)；③光能驱动(如细菌紫膜质)","goal":"学完应能掌握并运用「主动运输的3种动力」的核心内容，能解释其机制、比较相关概念。","intuition":"主动运输的“三种动力”：ATP 直接供能（泵）、靠离子梯度供能（协同运输）、靠光能供能（细菌紫膜质）。"},{"i":18,"sec":"第二节 跨膜运输","title":"3种载体蛋白 (p66)","notes":"3种不同的载体蛋白(transporter/carrier)：A被动运输；B/C主动运输。①同向协同运输(symport)——两种物质同方向；②反向协同运输(antiport)——两种物质反方向。","page":66,"level":"掌握","img":"assets/img/ch02/p066.jpg","anim":"carrier_types","fig":null,"points":["载体蛋白可介导被动或主动运输","同向协同运输(symport)：两种物质同方向","反向协同运输(antiport)：两种物质反方向"],"check":{"q":"关于载体蛋白介导的协同运输，叙述正确的是（　）","o":["A. 协同运输均属于顺浓度梯度的被动运输","B. 同向协同运输的两物质方向相反","C. 同向协同运输的过程完全不消耗任何能量","D. 同向协同运输两物质同方向，反向协同运输两物质方向相反"],"a":"D","e":"协同运输分为同向(symport)与反向(antiport)，两种物质分别同向或反向移动。","oe":["协同运输多利用离子梯度，属于主动运输范畴。","同向协同运输的两物质是同一方向，不是相反方向。","同向协同运输依赖离子电化学梯度，会消耗梯度势能。","协同运输分同向与反向两类，两物质分别同方向或相反方向移动。"]},"cards":[{"front":"同向协同运输与反向协同运输有何区别？","back":"同向(symport)：两种物质同方向运输；反向(antiport)：两种物质反方向运输","mnemonic":"同向并肩走，反向背对行","type":"对比","useImg":true,"blank":"同向","blank2":"反向"}],"mem":"同向并肩走，反向背对行","big":"assets/img/ch02/big/p066.jpg","terms":[{"t":"载体蛋白","en":"transporter / carrier","d":"与溶质特异结合、通过构象改变转运溶质的跨膜蛋白。"},{"t":"同向转运","en":"symport","d":"被转运的溶质与驱动离子同方向进入细胞的协同运输。"},{"t":"反向转运","en":"antiport","d":"被转运的溶质与驱动离子方向相反的协同运输。"}],"summary":"种不同的载体蛋白(transporter/carrier)：A被动运输；B/C主动运输","goal":"学完应能掌握并运用「3种载体蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"载体分三种：单向（只搬一种）、同向（两种同方向）、反向（两种反方向），靠构象变化搬货。"},{"i":19,"sec":"第二节 跨膜运输","title":"Na+/K+泵 (p67-68)","notes":"细胞外/细胞内：每水解一个ATP将细胞内的3个Na+泵出细胞外，同时输入2个K+→维持质膜两侧的离子浓度梯度。Na+/K+-ATPase建立Na+胞内低、K+胞内高的浓度梯度。获诺贝尔奖。","page":67,"level":"掌握","img":"assets/img/ch02/p067.jpg","anim":"nak_pump","fig":null,"points":["每水解1个ATP，将胞内3个Na⁺泵出、2个K⁺泵入","建立胞内低Na⁺、高K⁺的浓度梯度","该研究获诺贝尔奖"],"check":{"q":"关于Na+/K+-ATPase，下列说法正确的是（　）","o":["A. 每水解一个ATP泵出2个Na+、输入3个K+","B. 不消耗ATP","C. 使胞内Na+高、K+低","D. 每水解一个ATP泵出3个Na+、输入2个K+"],"a":"D","e":"Na+/K+泵每水解一个ATP，将胞内3个Na+泵出、2个K+泵入，建立胞内低Na+、高K+的浓度梯度。","oe":["应为泵出3个Na+、输入2个K+，比例颠倒","该泵为ATP驱动泵，需要消耗ATP","建立胞内低Na+、高K+的浓度梯度","正确，泵出3个Na+、输入2个K+"]},"cards":[{"front":"Na+/K+泵每水解1个ATP，转运哪些离子、方向和数量？","back":"泵出3个Na+到细胞外；泵入2个K+到细胞内","mnemonic":"三钠出，二钾进，一ATP","type":"组成数字","useImg":true,"blank":"3个Na+","blank2":"2个K+"},{"front":"Na+/K+泵建立的胞内外离子浓度梯度是什么？","back":"胞内Na+低、K+高；胞外Na+高、K+低","mnemonic":"钠外高，钾内高","type":"功能","useImg":false,"blank":"胞内Na+低","blank2":"胞外Na+高"}],"mem":"三钠出，二钾进，一ATP","big":"assets/img/ch02/big/p067.jpg","summary":"细胞外/细胞内：每水解一个ATP将细胞内的3个Na+泵出细胞外，同时输入2个K+→维持质膜两侧的离子浓度梯度","goal":"学完应能掌握并运用「Na+/K+泵」的核心内容，能解释其机制、比较相关概念。","intuition":"把 Na⁺/K⁺ 泵想成一道“旋转闸门”：每消耗 1 个 ATP 就转一圈，把 3 个 Na⁺ 甩到膜外、把 2 个 K⁺ 拉进膜内。转一圈净移出 1 个正电荷，所以它既建立浓度梯度，又帮膜维持内负外正的电位。每次“逆流搬离子”都必须耗能，这正是主动运输的典型。"},{"i":20,"sec":"第二节 跨膜运输","title":"Na+/K+泵结构 (p69)","notes":"Na+/K+-ATPase模型：2个α亚基+2个β亚基。α亚基与Na+结合促进ATP水解→构象变化→将Na+泵出、K+泵入。\n\n【本页英文讲解】\n本页给出Na+/K+-ATPase（钠钾ATP酶）的结构模型：由2个α亚基（subunit）和2个β亚基组成。α亚基为催化亚基，与Na+结合后促进ATP水解，引起自身构象变化，从而将Na+泵出细胞、把K+泵入细胞，维持细胞内高K+、细胞外高Na+。这是教材第五章主动运输的经典考点，每水解1分子ATP，泵出3个Na+、泵入2个K+。","page":69,"level":"掌握","img":"assets/img/ch02/p069.jpg","anim":"nak_pump","fig":null,"points":["由2个α亚基和2个β亚基组成","α亚基为催化亚基，与Na⁺结合促进ATP水解","构象变化将Na⁺泵出、K⁺泵入"],"check":{"q":"关于Na+/K+-ATPase的结构与功能，叙述正确的是（　）","o":["A. 由4个相同亚基组成并含选择性滤器","B. 由2个α亚基和2个β亚基组成，α亚基为催化亚基","C. β亚基结合Na+并催化ATP水解","D. 每水解1分子ATP泵入3个Na+、泵出2个K+"],"a":"B","e":"Na+/K+泵含2个α亚基和2个β亚基，α亚基结合Na+并催化ATP水解，引发构象变化。","oe":["含选择性滤器的是K+通道，Na+/K+泵为α2β2结构。","Na+/K+泵含α2β2，α亚基结合Na+并催化ATP水解引发构象变化。","催化ATP水解的是α亚基，β亚基起辅助作用。","每水解1分子ATP泵出3个Na+、泵入2个K+，方向写反了。"]},"cards":[{"front":"Na+/K+-ATPase由哪些亚基组成？","back":"2个α亚基 + 2个β亚基","mnemonic":"二α二β四聚体","type":"组成数字","useImg":true,"blank":"α亚基","blank2":"β亚基"},{"front":"Na+/K+泵中α亚基的功能是什么？","back":"与Na+结合→促进ATP水解→构象变化→泵出Na+、泵入K+","mnemonic":"α管水解与转运","type":"功能","useImg":true,"blank":"ATP水解","blank2":"构象变化"}],"mem":"二α二β四聚体","big":"assets/img/ch02/big/p069.jpg","summary":"Na+/K+-ATPase模型：2个α亚基+2个β亚基","goal":"学完应能掌握并运用「Na+/K+泵结构」的核心内容，能解释其机制、比较相关概念。","intuition":"Na⁺/K⁺ 泵像“会变形的二人转”：由 2 个 α 亚基（干活、水解 ATP）和 2 个 β 亚基（辅助）组成，构象一变就交替把 Na⁺ 送出、K⁺ 送入。"},{"i":21,"sec":"第二节 跨膜运输","title":"Na+/K+泵的作用 (p70)","notes":"动物细胞Na+/K+泵的作用：①建立细胞膜电位(membrane potential)，特别是在神经和肌肉等可兴奋细胞中，是细胞信号传递的重要基础；②维持渗透平衡；③维持pH稳态；④为协同运输提供驱动力。","page":70,"level":"掌握","img":"assets/img/ch02/p070.jpg","anim":null,"fig":null,"points":["建立细胞膜电位（神经、肌肉等可兴奋细胞）","维持渗透平衡","维持pH稳态","为协同运输提供驱动力"],"check":{"q":"下列属于动物细胞Na⁺/K⁺泵生理作用的是？","o":["A. 直接催化蛋白质的合成","B. 分解葡萄糖产生ATP","C. 作为DNA复制的起始点","D. 建立膜电位、维持渗透平衡与pH稳态"],"a":"D","e":"Na⁺/K⁺泵可建立膜电位、维持渗透平衡和pH稳态，并为协同运输提供驱动力。","oe":["错：蛋白质合成在核糖体进行，不符合本页所学概念","错：葡萄糖分解属糖酵解，不符合本页所学概念","错：与DNA复制无关，不符合本页所学概念","对：均为笔记所列泵的作用，与笔记原文相符"],"basis":"①建立细胞膜电位…②维持渗透平衡；③维持pH稳态"},"cards":[{"front":"动物细胞Na+/K+泵有哪四大作用？","back":"①建立膜电位；②维持渗透平衡；③维持pH稳态；④为协同运输提供驱动力","mnemonic":"电位、渗透、pH、协同","type":"功能","useImg":false,"blank":"膜电位","blank2":"渗透平衡"}],"mem":"电位、渗透、pH、协同","big":"assets/img/ch02/big/p070.jpg","terms":[{"t":"膜电位","en":"membrane potential","d":"因离子分布不均和膜的选择性通透而在膜两侧形成的电位差，静息时内负外正。"}],"summary":"动物细胞Na+/K+泵的作用：①建立细胞膜电位(membrane potential)，特别是在神经和肌肉等可兴奋细胞中，是细胞信号传递的重要基础；②维持渗透平衡；③维持pH稳态；","goal":"学完应能掌握并运用「Na+/K+泵的作用」的核心内容，能解释其机制、比较相关概念。","intuition":"Na⁺/K⁺ 泵的“三份工作”：维持离子梯度（为运输供能）、维持膜电位、维持渗透平衡和细胞体积。"},{"i":22,"sec":"第二节 跨膜运输","title":"神经传导速度 (p71)","notes":"动作电位以约100m/s的速度传递，是神经信号快速传导的基础。\n\n【读图讲解】\n该图以神经元模式图说明神经传导的高速特性。上方标注神经元的胞体(cell body)、树突(dendrites)、轴突(axon，长度从不足1mm到超过1m)与神经末梢(nerve terminal)，蓝色箭头表示冲动沿树突—胞体—轴突传向末梢，并标出“100m/s的速度传递”。右侧巨轴突的乌贼，以及下方神经—肌肉接头（黄色神经末梢释放递质作用于红色肌纤维），是研究轴突与突触传递的经典材料；捕蝇草、含羞草(A)(B)(C)叶片快速闭合则示意生物体的快速反应。要点：轴突长度与传导速度、神经冲动方向性及突触传递。","page":71,"level":"了解","img":"assets/img/ch02/p071.jpg","anim":null,"fig":"神经传导速度受轴突直径和髓鞘影响：轴突越粗、有髓鞘(跳跃式传导)速度越快。图对比无髓鞘与有髓鞘轴突的传导方式。","points":["动作电位沿轴突以约100m/s的速度传递","这是神经信号快速传导的基础"],"check":{"q":"神经信号能够快速传导的基础是（　）","o":["A. 冲动由轴突末梢逆向传回胞体","B. 动作电位沿轴突以约100m/s的速度传递","C. 神经冲动在胞体内以极慢速度扩散","D. 动作电位以约100μm/s的速度传递"],"a":"B","e":"动作电位沿轴突以约100m/s的速度传递，这是神经信号快速传导的基础。","oe":["冲动沿树突—胞体—轴突传向末梢，方向是单向的。","动作电位沿轴突以约100m/s的速度传递，是神经信号快速传导的基础。","神经冲动靠动作电位快速传导，并非在胞内缓慢扩散。","传导速度约为100m/s，而非100μm/s。"]},"cards":null,"mem":"动作电位约100m/s，轴突传导快","big":"assets/img/ch02/big/p071.jpg","summary":"动作电位以约100m/s的速度传递，是神经信号快速传导的基础","goal":"学完应能了解「神经传导速度」，能再认相关名词与实例。"},{"i":23,"sec":"第二节 跨膜运输","title":"静息电位 (p72-75)","notes":"动物细胞静息电位主要来自：①Na+/K+泵产生的K+浓度梯度；②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因。膜电位由接近膜的一薄层(<1nm)离子产生。In resting neurons, K+ leak channels are open, but the more numerous gated channels are closed。","page":72,"level":"掌握","img":"assets/img/ch02/p072.jpg","anim":"resting_potential","fig":null,"points":["来自Na⁺/K⁺泵产生的K⁺浓度梯度","静息状态质膜对K⁺的通透性大于Na⁺，是产生静息电位的主要原因"],"check":{"q":"动物细胞静息电位产生的主要原因是（　）","o":["A. 质膜对Na+通透性大于K+","B. 质膜静息时对K+通透性大于Na+","C. Na+/K+泵直接产生全部膜电位","D. 阴离子跨膜主动运输"],"a":"B","e":"静息电位主要来自Na+/K+泵产生的K+浓度梯度，以及静息状态质膜对K+的通透性大于Na+。","oe":["静息时质膜对K+通透性大于Na+","正确，静息时对K+通透性大于Na+","膜电位源于离子梯度与通透性差异","静息电位主要由钾离子外流所形成"]},"cards":[{"front":"动物细胞静息电位产生的主要原因是什么？","back":"静息时质膜对K+通透性大于Na+；K+外流形成静息电位","mnemonic":"钾漏钠难，外流成电位","type":"流程","useImg":true,"blank":"K+外流","blank2":"静息电位"},{"front":"静息电位由膜上多厚的离子层产生？","back":"接近膜的一薄层，厚度<1nm","mnemonic":"薄薄一层，不到一纳米","type":"定位","useImg":false,"blank":"<1nm"}],"mem":"钾漏钠难，外流成电位","big":"assets/img/ch02/big/p072.jpg","summary":"动物细胞静息电位主要来自：①Na+/K+泵产生的K+浓度梯度；②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因","goal":"学完应能掌握并运用「静息电位」的核心内容，能解释其机制、比较相关概念。","intuition":"静息电位像“K⁺ 的跷跷板”：静息时膜对 K⁺ 通透性大，K⁺ 顺梯度外流、把膜内留成负电；同时 Na⁺/K⁺ 泵守住浓度梯度。内负外正由此而来。","derive":"【Nernst 方程估算静息电位】E_K = (RT/zF)·ln([K⁺]外/[K⁺]内) ≈ 61.5·log10([K⁺]外/[K⁺]内) mV (37℃)。\n例：[K⁺]外≈5 mmol/L、[K⁺]内≈140 mmol/L → E_K ≈ 61.5·log10(5/140) ≈ −89 mV，接近实测静息电位(约 −70 mV)，说明静息电位主要由 K⁺ 通透性决定。","experiment":"【方法·膜片钳】用微电极吸附一小片膜形成高阻封接，可直接记录单个离子通道的开闭与电流，验证静息电位主要由 K⁺ 通透性决定。"},{"i":24,"sec":"第二节 跨膜运输","title":"钾泄漏通道 (p75-76)","notes":"离子通道如何工作?——选择性滤器。静息神经元中K⁺泄漏通道开放，而数量更多的门控通道处于关闭状态；K⁺泄漏通道维持静息电位。","page":76,"level":"掌握","img":"assets/img/ch02/p076.jpg","anim":null,"fig":"静息 K⁺ 通道(泄漏通道)在静息时持续开放，是形成静息电位的关键。图显示 K⁺ 经泄漏通道外流，膜内变负。","points":["静息神经元中K⁺泄漏通道开放","数量更多的门控通道关闭","K⁺外流，形成静息电位"],"check":{"q":"静息电位的形成主要与下列哪项有关（　）","o":["A. 静息时Na+/K+泵完全停止工作","B. Cl-通道开放使Cl-大量外流","C. 静息时K+泄漏通道开放使K+外流","D. 大量门控通道开放使Na+内流"],"a":"C","e":"静息神经元中K+泄漏通道开放、门控通道关闭，K+外流形成静息电位。","oe":["静息时Na+/K+泵仍在工作以维持离子梯度。","静息电位的形成主要取决于K+外流而非Cl-外流。","静息神经元K+泄漏通道开放、门控通道关闭，K+外流形成静息电位。","静息时门控通道关闭，Na+内流主要发生在动作电位。"]},"cards":[{"front":"静息神经元中哪类通道开放、哪类关闭？","back":"K+泄漏通道开放；数量更多的门控通道关闭","mnemonic":"漏开闸关","type":"对比","useImg":true,"blank":"K+泄漏通道","blank2":"门控通道"},{"front":"K+泄漏通道开放导致什么结果？","back":"K+外流，形成静息电位","mnemonic":"钾出成静息","type":"功能","useImg":false,"blank":"K+外流","blank2":"静息电位"}],"mem":"漏开闸关","big":"assets/img/ch02/big/p076.jpg","summary":"离子通道如何工作?——选择性滤器","goal":"学完应能掌握并运用「钾泄漏通道」的核心内容，能解释其机制、比较相关概念。","intuition":"静息时膜上“敞着”的 K⁺ 泄漏通道像“常开的窗”：K⁺ 顺梯度外流，是静息电位的主要来源。"},{"i":25,"sec":"第二节 跨膜运输","title":"K+通道的选择性滤器 (p77-79)","notes":"细菌静息K+通道结构。所有K+通道蛋白都有选择性滤器。K+特异性的分子基础：去水化(dehydration)K+需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿→只有K+能通过，Na+因不能补偿去水化能量而被排斥。","page":78,"level":"掌握","img":"assets/img/ch02/p078.jpg","anim":"k_channel_selectivity","fig":null,"points":["所有K⁺通道蛋白都有选择性滤器","K⁺去水化所需能量恰好由K⁺与滤器羰基氧结合所补偿","Na⁺不能补偿去水化能量而被排斥"],"check":{"q":"K⁺通道只让K⁺通过而不能通过Na⁺，其分子基础是？","o":["A. K⁺去水化的能量恰好由与滤器羰基氧结合补偿","B. Na⁺半径大于K⁺因而被阻挡","C. 滤器对K⁺带正电有静电吸引","D. K⁺通道的孔径远大于Na⁺"],"a":"A","e":"K⁺去水化需要能量，该能量恰好由K⁺与滤器羰基氧结合所补偿；Na⁺不能补偿去水化能量而被排斥。","oe":["对：笔记点明该能量补偿机制，与笔记原文相符","错：Na⁺半径实际小于K⁺，不符合本页所学概念","错：K⁺与Na⁺均带正电，不符合本页所学概念","错：孔径大小并非选择性的关键，不符合本页所学概念"],"basis":"去水化K⁺需要能量…由K⁺与滤器羰基氧的结合所补偿"},"cards":[{"front":"所有K+通道蛋白共有的关键结构是什么？","back":"选择性滤器","mnemonic":"钾通道都有滤器","type":"组成数字","useImg":true,"blank":"选择性滤器"},{"front":"K+通道选择K+、排斥Na+的分子基础是什么？","back":"K+去水化耗能恰由与滤器羰基氧结合补偿；Na+不能补偿而被排斥","mnemonic":"钾脱水有补偿，钠脱水白费力","type":"流程","useImg":true,"blank":"去水化","blank2":"羰基氧"}],"mem":"钾通道都有滤器","big":"assets/img/ch02/big/p078.jpg","terms":[{"t":"去水化","en":"dehydration","d":"离子进入选择性滤器前脱去水化层的过程；K⁺去水化耗能恰由与滤器羰基氧结合补偿，Na⁺不能补偿而被排斥。"}],"summary":"细菌静息K+通道结构","goal":"学完应能掌握并运用「K+通道的选择性滤器」的核心内容，能解释其机制、比较相关概念。","intuition":"K⁺ 通道挑离子的诀窍是“以置换换脱水”：离子要过窄孔，必须先脱掉水化层（耗能）。滤器孔壁羰基氧的排列刚好模拟水分子，K⁺ 脱水耗的能量正好由与羰基氧结合补回，进出“不亏不赚”；Na⁺ 水化更牢，脱水花费补不回来，就被挡住。所以通道不是靠“筛孔大小”，而是靠“能量算账”选择离子。"},{"i":26,"sec":"第二节 跨膜运输","title":"动作电位 (p80-81)","notes":"动作电位(action potential)：当细胞收到刺激信号时，膜电位发生变化——去极化或超极化，称动作电位。记录轴突膜电位随时间的变化可揭示动作电位的幅度和时程。","page":80,"level":"掌握","img":"assets/img/ch02/p080.jpg","anim":"action_potential","fig":null,"points":["细胞受到刺激时膜电位发生变化（去极化或超极化），称动作电位","记录轴突膜电位随时间变化可得其幅度和时程"],"check":{"q":"关于动作电位的叙述，正确的是（　）","o":["A. 记录轴突膜电位可测得动作电位的电阻值","B. 细胞受刺激时膜电位发生去极化或超极化","C. 动作电位只能由化学突触直接产生","D. 动作电位是膜电位保持恒定不变的状态"],"a":"B","e":"细胞收到刺激信号后膜电位发生变化即去极化或超极化，称动作电位，可记录其幅度与时程。","oe":["记录膜电位随时间变化可得幅度和时程，而非电阻值。","细胞受刺激后膜电位发生去极化或超极化，即动作电位，可记录其幅度与时程。","动作电位由膜电位变化产生，并不限于化学突触。","动作电位表现为膜电位的动态变化，并非恒定不变。"]},"cards":[{"front":"什么是动作电位？","back":"细胞受刺激时膜电位发生去极化或超极化的变化","mnemonic":"刺激一来，电位翻转","type":"定义","useImg":true,"blank":"膜电位","blank2":"去极化"},{"front":"如何揭示动作电位的幅度和时程？","back":"记录轴突膜电位随时间的变化","mnemonic":"记电位—时间曲线","type":"流程","useImg":false,"blank":"膜电位","blank2":"轴突膜电位"}],"mem":"刺激一来，电位翻转","big":"assets/img/ch02/big/p080.jpg","summary":"动作电位(action potential)：当细胞收到刺激信号时，膜电位发生变化——去极化或超极化，称动作电位","goal":"学完应能掌握并运用「动作电位」的核心内容，能解释其机制、比较相关概念。","intuition":"动作电位像“一按就连锁的警报”：刺激使 Na⁺ 通道闪开、Na⁺ 涌入去极化，又触发更多 Na⁺ 通道打开（正反馈），形成陡峭上升相；随后 K⁺ 外流复极化。全或无、可远距离传播。"},{"i":27,"sec":"第二节 跨膜运输","title":"协同运输 (p82)","notes":"协同运输(cotransport)：一种主动运输方式，由Na+-K+泵(动物)、H+泵(植物)与载体蛋白协同作用。直接动力——膜两侧离子的电化学梯度。","page":82,"level":"掌握","img":"assets/img/ch02/p082.jpg","anim":"cotransport","fig":null,"points":["协同运输是主动运输方式","由Na⁺-K⁺泵（动物）或H⁺泵（植物）与载体蛋白协同作用","直接动力是膜两侧离子的电化学梯度"],"check":{"q":"关于协同运输，下列说法正确的是（　）","o":["A. 属于被动运输","B. 与Na+/K+泵无关","C. 直接消耗ATP转运分子","D. 直接动力是膜两侧离子的电化学梯度"],"a":"D","e":"协同运输是主动运输，由Na+-K+泵（动物）或H+泵（植物）与载体蛋白协同，直接动力为膜两侧离子的电化学梯度。","oe":["协同运输属于主动运输，不是被动运输","协同运输依赖Na+-K+泵建立的梯度","直接动力为离子梯度，并非直接水解ATP","正确，直接动力是离子电化学梯度"]},"cards":[{"front":"什么是协同运输？","back":"一种主动运输，由Na+-K+泵(动物)或H+泵(植物)与载体蛋白协同完成","mnemonic":"泵加载体，协同转运","type":"定义","useImg":true,"blank":"主动运输","blank2":"载体蛋白"},{"front":"协同运输的直接动力是什么？","back":"膜两侧离子的电化学梯度","mnemonic":"电化学梯度驱动","type":"功能","useImg":false,"blank":"电化学梯度","blank2":"离子"}],"mem":"泵加载体，协同转运","big":"assets/img/ch02/big/p082.jpg","summary":"协同运输(cotransport)：一种主动运输方式，由Na+-K+泵(动物)、H+泵(植物)与载体蛋白协同作用","goal":"学完应能掌握并运用「协同运输」的核心内容，能解释其机制、比较相关概念。","intuition":"协同运输是“搭便车”：一种离子（常是 Na⁺）顺着它的电化学梯度“下坡”，用这股劲把另一种溶质“拽上坡”。两种同向走叫同向转运，反向走叫反向转运。它本身不直接水解 ATP，属继发性主动运输。","derive":"【能量换算】协同运输不直接水解 ATP，而是借 Na⁺ 顺电化学梯度释放的自由能，驱动另一种溶质逆浓度梯度转运；该 Na⁺ 梯度最终由 Na⁺/K⁺ 泵水解 ATP 维持，故协同运输属继发性主动运输。"},{"i":28,"sec":"第二节 跨膜运输","title":"大坝类比 (p83)","notes":"南非Blyde河大坝——类比离子梯度储能：大坝蓄水形成势能，可驱动做功；离子梯度同样储存势能，驱动协同运输。","page":83,"level":"了解","img":"assets/img/ch02/p083.jpg","anim":null,"fig":null,"points":["大坝蓄水形成势能可驱动做功","类比离子梯度储存势能、驱动协同运输"],"check":{"q":"用南非Blyde河大坝所作的类比，主要说明（　）","o":["A. 水分子经水通道顺浓度梯度自由扩散","B. 大坝可防止动物细胞吸水膨胀破裂","C. 胆固醇对膜流动性的缓冲调节作用","D. 离子梯度储存势能并可驱动协同运输"],"a":"D","e":"大坝蓄水形成势能可驱动做功，类比离子梯度同样储存势能、驱动协同运输。","oe":["该类比针对离子梯度，而非水通道的水转运。","该类比说明离子梯度储能，与细胞渗透平衡无关。","该类比与胆固醇调节膜流动性无关。","大坝蓄水储势能可做功，类比离子梯度储能驱动协同运输。"]},"cards":null,"mem":"大坝蓄水类比离子梯度储能，驱动协同运输","big":"assets/img/ch02/big/p083.jpg","summary":"南非Blyde河大坝——类比离子梯度储能：大坝蓄水形成势能，可驱动做功；离子梯度同样储存势能，驱动协同运输","goal":"学完应能了解「大坝类比」，能再认相关名词与实例。"},{"i":29,"sec":"第二节 跨膜运输","title":"葡萄糖-Na+同向转运 (p84)","notes":"葡萄糖-Na+同向转运蛋白利用Na+电化学梯度驱动葡萄糖的摄入，如小肠上皮细胞吸收肠腔葡萄糖；植物细胞也利用H+梯度。","page":84,"level":"掌握","img":"assets/img/ch02/p084.jpg","anim":"sglt","fig":"葡萄糖-Na⁺ 同向转运(SGLT)：Na⁺ 顺浓度梯度内流，同时把葡萄糖逆浓度梯度带入细胞。图显示 SGLT 的协同转运机制，属继发性主动运输。","points":["利用Na⁺电化学梯度驱动葡萄糖摄入","例：小肠上皮细胞吸收肠腔葡萄糖","植物细胞利用H⁺梯度"],"check":{"q":"小肠上皮细胞吸收肠腔葡萄糖所依靠的机制是（　）","o":["A. 葡萄糖-Na+反向转运，直接水解ATP供能","B. 葡萄糖顺浓度梯度简单扩散进入细胞","C. GLUT1协助扩散将葡萄糖运入肠腔","D. 葡萄糖-Na+同向转运蛋白，利用Na+电化学梯度"],"a":"D","e":"葡萄糖-Na+同向转运蛋白利用Na+电化学梯度驱动葡萄糖的摄入。","oe":["该转运为同向协同运输，且不直接水解ATP。","葡萄糖为极性分子，需转运蛋白而非简单扩散。","GLUT1协助扩散用于进入细胞，方向并非运入肠腔。","葡萄糖-Na+同向转运蛋白利用Na+电化学梯度驱动葡萄糖摄入。"]},"cards":[{"front":"葡萄糖-Na+同向转运蛋白利用什么能量驱动葡萄糖摄入？","back":"利用Na+电化学梯度驱动；植物细胞则利用H+梯度","mnemonic":"钠顺流，糖逆上","type":"功能","useImg":true,"blank":"Na+电化学梯度","blank2":"H+梯度"}],"mem":"钠顺流，糖逆上","big":"assets/img/ch02/big/p084.jpg","terms":[{"t":"SGLT","en":"sodium-glucose linked transporter","d":"钠-葡萄糖同向转运体，借Na⁺顺电化学梯度驱动葡萄糖逆浓度转入细胞，属继发性主动运输。"}],"summary":"葡萄糖-Na+同向转运蛋白利用Na+电化学梯度驱动葡萄糖的摄入，如小肠上皮细胞吸收肠腔葡萄糖；植物细胞也利用H+梯度","goal":"学完应能掌握并运用「葡萄糖-Na+同向转运」的核心内容，能解释其机制、比较相关概念。","intuition":"小肠吸收葡萄糖像“借水力发电”：Na⁺ 顺梯度涌入细胞时，顺带把葡萄糖一起“拖”进来（SGLT 同向转运）。细胞再用 Na⁺/K⁺ 泵把 Na⁺ 排出去、维持梯度——所以葡萄糖的逆梯度吸收，最终仍由 ATP 买单。"},{"i":30,"sec":"第二节 跨膜运输","title":"小肠上皮细胞吸收葡萄糖 (p85-87)","notes":"小肠上皮细胞吸收葡萄糖示意图：①载体1(SGLT)——面向肠腔的顶端表面，由Na+驱动的葡萄糖同向主动运输，使细胞内有高浓度葡萄糖；②载体蛋白2(Glut2)——基底面，被动的协助扩散将葡萄糖运入血液。两步实现葡萄糖从肠腔到血液的逆浓度吸收。","page":85,"level":"掌握","img":"assets/img/ch02/p085.jpg","anim":"intestinal_glucose","fig":null,"points":["顶端面SGLT由Na⁺驱动进行同向主动运输，使胞内葡萄糖浓度高","基底面Glut2经协助扩散将葡萄糖运入血液","两步实现葡萄糖从肠腔到血液的逆浓度吸收"],"check":{"q":"小肠上皮细胞吸收葡萄糖时，下列说法正确的是（　）","o":["A. 顶端SGLT通过被动扩散吸收葡萄糖","B. 基底面Glut2通过协助扩散将葡萄糖运入血液","C. 顶端SGLT不依赖Na+梯度","D. Glut2是主动运输载体"],"a":"B","e":"肠腔侧载体SGLT由Na+驱动进行同向主动运输，使胞内葡萄糖浓度高；基底面Glut2经协助扩散将葡萄糖运入血液。","oe":["SGLT为Na+驱动的同向主动运输","正确，Glut2经协助扩散运入血液","SGLT依赖Na+建立的梯度驱动","Glut2为被动的协助扩散载体"]},"cards":[{"front":"小肠上皮细胞吸收葡萄糖的两个关键转运蛋白分别是什么？","back":"顶端面SGLT：Na+驱动的葡萄糖同向主动运输；基底面Glut2：协助扩散入血","mnemonic":"顶SGLT进，底Glut2出","type":"流程","useImg":true,"blank":"SGLT","blank2":"Glut2"},{"front":"小肠上皮细胞如何实现葡萄糖从肠腔到血液的逆浓度吸收？","back":"两步：SGLT用Na+梯度把葡萄糖主动运入细胞；Glut2被动协助扩散运出到血液","mnemonic":"先主动进，再被动出","type":"流程","useImg":true,"blank":"SGLT","blank2":"Glut2"}],"mem":"顶SGLT进，底Glut2出","big":"assets/img/ch02/big/p085.jpg","summary":"小肠上皮细胞吸收葡萄糖示意图：①载体1(SGLT)——面向肠腔的顶端表面，由Na+驱动的葡萄糖同向主动运输，使细胞内有高浓度葡萄糖；②载体蛋白2(Glut2)——基底面，被动的协助","goal":"学完应能掌握并运用「小肠上皮细胞吸收葡萄糖」的核心内容，能解释其机制、比较相关概念。","intuition":"小肠吸收葡萄糖像“两道闸门接力”：先在腔侧用 Na⁺ 梯度把葡萄糖拽进细胞（SGLT 同向转运），再从基底侧用 GLUT 顺梯度放它进血。Na⁺ 由 K⁺ 泵不断排出、维持梯度。"},{"i":31,"sec":"第二节 跨膜运输","title":"Na+/K+泵维持渗透平衡 (p88-89)","notes":"动物细胞Na+/K+泵作用——维持渗透平衡：动物细胞将Na+泵出细胞外，胞外高浓度Na+(还有Cl-)，帮助细胞维持膜内外渗透压的平衡。Na+/K+-ATPase及其他离子泵必须持续工作；若停止，细胞会吸水膨胀破裂。","page":88,"level":"掌握","img":"assets/img/ch02/p088.jpg","anim":"nak_osmotic","fig":"Na⁺/K⁺ 泵维持细胞的渗透平衡：泵出 Na⁺ 多于泵入 K⁺，使细胞内渗透压略低，防止细胞吸水涨破。图说明泵的“渗透调节”作用。","points":["动物细胞将Na⁺泵出，胞外Na⁺(及Cl⁻)浓度高","帮助维持膜内外渗透压平衡","泵停止则细胞吸水膨胀甚至破裂"],"check":{"q":"若动物细胞Na+/K+泵持续停止工作，最可能的后果是（　）","o":["A. 胞内pH值立即升高","B. 细胞因失水而明显皱缩","C. 细胞吸水膨胀甚至破裂","D. 膜电位消失但细胞体积保持不变"],"a":"C","e":"Na+/K+泵维持渗透平衡，停止后胞外Na+减少，细胞会吸水膨胀甚至破裂。","oe":["泵停止主要影响渗透平衡，不会使pH立即升高。","泵停止使胞内离子增多、细胞吸水，而非失水皱缩。","Na+/K+泵维持渗透平衡，持续停止后细胞会吸水膨胀甚至破裂。","细胞会吸水膨胀，体积难以保持不变。"]},"cards":[{"front":"Na+/K+泵如何维持动物细胞的渗透平衡？","back":"将Na+泵出细胞外，胞外高Na+（及Cl-）维持膜内外渗透压平衡","mnemonic":"钠在外，水不进来","type":"功能","useImg":true,"blank":"渗透压平衡","blank2":"Na+泵"},{"front":"若Na+/K+-ATPase停止工作，动物细胞会怎样？","back":"细胞吸水膨胀破裂；因离子泵须持续工作维持渗透平衡","mnemonic":"泵停水入，细胞爆","type":"例证","useImg":false,"blank":"离子泵","blank2":"渗透平衡"}],"mem":"钠在外，水不进来","big":"assets/img/ch02/big/p088.jpg","summary":"动物细胞Na+/K+泵作用——维持渗透平衡：动物细胞将Na+泵出细胞外，胞外高浓度Na+(还有Cl-)，帮助细胞维持膜内外渗透压的平衡","goal":"学完应能掌握并运用「Na+/K+泵维持渗透平衡」的核心内容，能解释其机制、比较相关概念。","intuition":"Na⁺/K⁺ 泵像细胞的“排水泵”：它不断把 Na⁺ 泵出，抵消细胞内大分子吸引水分子的渗透拉力，防止细胞吸水涨破（动物细胞没有细胞壁挡着）。它既维持离子梯度，也维持细胞体积。","derive":"【Na⁺/K⁺ 泵与渗透】每水解 1 分子 ATP 泵出 3 Na⁺、摄入 2 K⁺，净移出 1 个正电荷。\n意义：既建立并维持 Na⁺ 胞内低、K⁺ 胞内高的浓度梯度，又抵消胞内大分子的渗透拉力，维持细胞体积。"},{"i":32,"sec":"第二节 跨膜运输","title":"调节pH稳态 (p90)","notes":"Na+/K+泵调节细胞质基质的pH稳态：细胞内葡萄糖无氧代谢产生乳酸，有氧代谢产生CO2(溶于水形成H2CO3，解离产生H+)。Na+HCO3-/Cl-交换等机制维持胞内pH稳定。","page":90,"level":"掌握","img":"assets/img/ch02/p090.jpg","anim":null,"fig":"Na⁺/H⁺ 交换器(NHE)等转运蛋白调节细胞内 pH：把 H⁺ 泵出、Na⁺ 带入，维持胞质 pH 稳定。图显示 pH 稳态的转运机制。","points":["无氧代谢产生乳酸、有氧代谢产生CO₂(生成H⁺)","Na⁺/HCO₃⁻与Cl⁻交换等机制维持胞内pH稳定"],"check":{"q":"细胞无氧代谢产生乳酸时，维持胞内pH稳态的机制之一是（　）","o":["A. Na+/HCO3-与Cl-交换等机制","B. 胆固醇插入膜中缓冲流动性","C. 静息K+泄漏通道开放使K+外流","D. 大坝式离子梯度储存势能"],"a":"A","e":"细胞通过Na+/HCO3-与Cl-交换等机制维持胞内pH稳定，以应对乳酸和CO2产生的H+。","oe":["细胞通过Na+/HCO3-与Cl-交换等机制排出H+，维持胞内pH稳定。","胆固醇调节膜流动性，与pH稳态无关。","K+泄漏通道与膜电位有关，不直接调节胞内pH。","离子梯度储能与pH缓冲机制没有直接关系。"]},"cards":[{"front":"Na+/K+泵如何帮助调节细胞质基质的pH稳态？","back":"通过Na+HCO3-/Cl-交换等机制维持胞内pH稳定；代谢产生乳酸、CO2/H2CO3解离出H+","mnemonic":"泵钠带碱，中和酸","type":"功能","useImg":false,"blank":"Na+HCO3-/Cl-交换","blank2":"胞内pH稳定"}],"mem":"泵钠带碱，中和酸","big":"assets/img/ch02/big/p090.jpg","terms":[{"t":"NHE","en":"Na⁺/H⁺ exchanger","d":"Na⁺/H⁺交换器，把H⁺泵出胞外、Na⁺带入胞内，参与胞内pH稳态的维持。"}],"summary":"Na+/K+泵调节细胞质基质的pH稳态：细胞内葡萄糖无氧代谢产生乳酸，有氧代谢产生CO2(溶于水形成H2CO3，解离产生H+)","goal":"学完应能掌握并运用「调节pH稳态」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞代谢会不断产生 H⁺（乳酸、CO₂），像“越待越酸的屋子”；靠 NHE、Cl⁻/HCO₃⁻ 交换等把 H⁺ 排出去，维持胞内 pH。"},{"i":33,"sec":"第二节 跨膜运输","title":"动植物细胞的比较 (p91-92)","notes":"动物细胞和植物细胞的比较：植物细胞、细菌、真菌细胞的质膜上没有动物细胞的Na+/K+泵，取而代之的是H+泵，通过泵出H+建立质子梯度。动植物细胞载体蛋白介导物质转运的机制有异同。","page":91,"level":"掌握","img":"assets/img/ch02/p091.jpg","anim":null,"fig":"动物细胞与植物细胞的比较：植物细胞有细胞壁、大液泡、叶绿体；动物细胞有中心体等。图对比两者的细胞器组成，膜系统基本相似。","points":["植物、细菌、真菌细胞的质膜上没有Na⁺/K⁺泵","代之以H⁺泵，通过泵出H⁺建立质子梯度"],"check":{"q":"植物细胞、细菌和真菌细胞质膜上代替Na+/K+泵的是（　）","o":["A. GLUT家族载体，通过协助扩散运输葡萄糖","B. Ca2+泵，通过泵出Ca2+建立钙梯度","C. 水通道蛋白AQP1，通过转运水维持平衡","D. H+泵，通过泵出H+建立质子梯度"],"a":"D","e":"植物、细菌和真菌细胞的质膜上没有Na+/K+泵，代之以H+泵，通过泵出H+建立质子梯度。","oe":["GLUT为载体蛋白，不能建立质子梯度。","Ca2+泵转运钙离子，不能代替Na+/K+泵建立质子梯度。","AQP1是水通道，不承担离子泵的功能。","植物、细菌和真菌质膜上以H+泵泵出H+建立质子梯度，而非Na+/K+泵。"]},"cards":[{"front":"植物、细菌、真菌细胞质膜上用什么泵替代动物细胞的Na+/K+泵？","back":"H+泵；通过泵出H+建立质子梯度","mnemonic":"动物钠钾，植物氢","type":"对比","useImg":true,"blank":"H+泵","blank2":"质子梯度"},{"front":"动物细胞与植物细胞在质膜离子泵上的主要区别是什么？","back":"动物细胞有Na+/K+泵；植物、细菌、真菌细胞用H+泵建立质子梯度","mnemonic":"动物钠钾，植物氢","type":"对比","useImg":true,"blank":"Na+/K+泵","blank2":"H+泵"}],"mem":"动物钠钾，植物氢","big":"assets/img/ch02/big/p091.jpg","summary":"动物细胞和植物细胞的比较：植物细胞、细菌、真菌细胞的质膜上没有动物细胞的Na+/K+泵，取而代之的是H+泵，通过泵出H+建立质子梯度","goal":"学完应能掌握并运用「动植物细胞的比较」的核心内容，能解释其机制、比较相关概念。","intuition":"动物细胞像“没穿墙的软帐篷”，靠泵和离子维持体积；植物细胞有细胞壁像“有外框”，主要靠壁压支撑形态。"}],"mcq":[{"id":"ch02_mcq_14","mod":"模块二：跨膜运输","modI":1,"q":"水通道蛋白(aquaporin)的发现对应哪年的诺贝尔化学奖？","o":["A. 2003年","B. 1997年","C. 2012年","D. 2006年"],"a":"A","e":"2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。","kp":"ch02_s1_8","oe":["2003年诺贝尔化学奖授予发现水通道的Agre，与钾通道的MacKinnon共享，正确。","1997年化学奖授予ATP合酶与Na+/K+-ATPase相关研究，与水通道无关。","2012年化学奖授予G蛋白偶联受体的研究，与水通道发现无关。","2006年化学奖授予真核转录机制研究，与水通道发现无关。"]},{"id":"ch02_mcq_15","mod":"模块二：跨膜运输","modI":1,"q":"Na+/K+-ATPase每水解1个ATP转运的离子数是？","o":["A. 泵出2Na+,泵入3K+","B. 泵出3Na+,泵入2K+","C. 泵出3Na+,泵入3K+","D. 泵出2Na+,泵入2K+"],"a":"B","e":"每水解1个ATP，将3个Na+泵出细胞、2个K+泵入细胞，维持膜两侧离子梯度。","kp":"ch02_s1_19","oe":["Na+/K+-ATPase泵出3个Na+、泵入2个K+，该选项数量与方向均反。","每水解1个ATP，泵出3个Na+、泵入2个K+，正确。","该泵转运3个Na+出、2个K+入，并非3Na+对3K+。","该泵每水解1个ATP转运3Na+与2K+，不是2Na+对2K+。"]},{"id":"ch02_mcq_16","mod":"模块二：跨膜运输","modI":1,"q":"动物细胞静息电位产生的主要原因是？","o":["A. 静息时质膜对K+通透性大于Na+","B. 静息时质膜对Na+通透性大于K+","C. 钙泵活动","D. 水通道开放"],"a":"A","e":"静息电位主要来自Na+/K+泵产生的K+浓度梯度，以及静息时质膜对K+通透性大于Na+。","kp":"ch02_s1_23","oe":["静息时质膜对K+通透性大于Na+，K+外流形成静息电位，正确。","静息时膜对Na+通透性远小于K+，该选项恰好说反。","钙泵主要维持胞内低钙，不是产生静息电位的主要原因。","水通道只转运水，不产生跨膜电位，与静息电位无关。"]},{"id":"ch02_mcq_17","mod":"模块二：跨膜运输","modI":1,"q":"K+通道选择性的分子基础是？","o":["A. 通道大小","B. 去水化能量与滤器羰基氧结合能相平衡","C. 膜电位","D. 通道正电荷"],"a":"B","e":"K+去水化所需能量恰好由K+与选择性滤器羰基氧结合释放的能量补偿→只有K+能通过，Na+被排斥。","kp":"ch02_s1_25","oe":["仅凭通道大小不能解释更小的Na+反而不能通过，故不是选择性基础。","K+去水化耗能与滤器羰基氧结合能相平衡，故仅K+能通过，正确。","膜电位只决定通道的开闭门控，不决定离子选择性。","K+通道选择性依赖滤器羰基氧，正电荷主要见于水通道的排阳离子机制。"]},{"id":"ch02_mcq_18","mod":"模块二：跨膜运输","modI":1,"q":"水通道的选择性由什么决定？","o":["A. 直径0.28nm+中心正电荷(Arg/His)","B. 只有疏水作用","C. 膜电位","D. 通道长度"],"a":"A","e":"水通道直径仅0.28nm，无法通过比水大的分子；通道中心最窄处带正电荷(Arg-195、His-180)排斥阳离子，只允许水通过。","kp":"ch02_s1_13","oe":["水通道直径约0.28nm且中心带正电荷(Arg/His)，只允许水通过，正确。","水通道的选择性不只靠疏水作用，还依赖孔径与中心正电荷。","膜电位影响通道门控，不决定水通道的选择性。","通道长度与水通道的选择性无关，选择性取决于孔径和电荷。"]},{"id":"ch02_mcq_19","mod":"模块二：跨膜运输","modI":1,"q":"主动运输的特点不包括？","o":["A. 逆浓度梯度","B. 需要能量","C. 需载体蛋白","D. 顺浓度梯度不耗能"],"a":"D","e":"主动运输逆浓度梯度、需能量(ATP/光能/离子梯度)、需载体蛋白。顺浓度梯度不耗能是被动运输。","kp":"ch02_s1_17","oe":["主动运输逆浓度梯度进行，这是其基本特点之一。","主动运输需要消耗能量(ATP、光能或离子梯度)，属其特点。","主动运输需要载体蛋白协助，属其特点。","顺浓度梯度且不耗能是被动运输的特征，不属于主动运输，故为答案。"]},{"id":"ch02_mcq_20","mod":"模块二：跨膜运输","modI":1,"q":"小肠上皮细胞吸收葡萄糖的过程是？","o":["A. 简单扩散","B. 顶端SGLT(Na+同向主动运输)+基底Glut2(协助扩散)","C. 仅主动运输","D. 仅胞吞"],"a":"B","e":"顶端面SGLT利用Na+梯度主动转运葡萄糖入胞；基底面Glut2被动协助扩散入血。两步完成逆浓度吸收。","kp":"ch02_s1_30","oe":["葡萄糖为极性分子，不能靠简单扩散通过小肠上皮质膜。","顶端SGLT借Na+梯度主动转运、基底Glut2经协助扩散入血，正确。","吸收由主动运输与协助扩散两步共同完成，并非仅主动运输。","小肠吸收葡萄糖不通过胞吞，而是经载体蛋白转运。"]},{"id":"ch02_mcq_21","mod":"模块二：跨膜运输","modI":1,"q":"协同运输(symport)是指？","o":["A. 两种物质反向转运","B. 两种物质同向转运","C. 仅一种物质","D. 需光能"],"a":"B","e":"同向协同运输(symport)两种物质同方向；反向协同运输(antiport)方向相反。如葡萄糖-Na+同向转运。","kp":"ch02_s1_27","oe":["两种物质反向转运属于反向协同运输(antiport)，不是symport。","同向协同运输指两种物质同方向转运，正确。","协同运输涉及两种物质，不是仅一种物质转运。","协同运输的能量可来自离子梯度，通常不需光能。"]},{"id":"ch02_mcq_22","mod":"模块二：跨膜运输","modI":1,"q":"植物细胞质膜上代替Na+/K+泵的离子泵是？","o":["A. Ca2+泵","B. H+泵","C. Cl-泵","D. 水通道"],"a":"B","e":"植物细胞、细菌、真菌质膜上没有Na+/K+泵，取而代之的是H+泵，泵出H+建立质子梯度。","kp":"ch02_s1_21","oe":["Ca2+泵在植物细胞存在，但并非代替Na+/K+泵的离子泵。","植物细胞质膜以H+泵泵出H+建立质子梯度，代替Na+/K+泵，正确。","Cl-泵不是植物质膜上代替Na+/K+泵的离子泵。","水通道只转运水，不能代替离子泵建立电化学梯度。"]},{"id":"ch02_mcq_23","mod":"模块二：跨膜运输","modI":1,"q":"脂筏(lipid raft)的主要组成是？","o":["A. 甘油磷脂为主","B. 胆固醇、鞘磷脂富集区","C. 仅蛋白质","D. 仅糖脂"],"a":"B","e":"脂筏是膜上胆固醇、鞘磷脂等富集的相对独立微区域，承载特定膜蛋白，参与信号传递。","kp":"ch02_s1_2","oe":["脂筏富含鞘磷脂和胆固醇，而非以甘油磷脂为主。","脂筏是胆固醇与鞘磷脂富集的微区域，并承载特定膜蛋白，正确。","脂筏除蛋白外还含大量脂质，并非仅由蛋白质组成。","脂筏不只有糖脂，还富含胆固醇和鞘磷脂。"]},{"id":"ch02_mcq_24","mod":"模块二：跨膜运输","modI":1,"q":"膜脂形成脂双层的原因是？","o":["A. 两性分子在水中的自装配","B. 共价键连接","C. 酶催化","D. 外力作用"],"a":"A","e":"膜脂为两性分子(亲水头+疏水尾)，在水中自动、自我装配形成连续不破裂的脂双层。","kp":"ch02_s1_2","oe":["膜脂为两性分子，在水中可自装配成连续脂双层，正确。","膜脂形成脂双层靠疏水作用等非共价作用，而非共价键连接。","脂双层是膜脂自发的自装配过程，不需要酶催化。","脂双层形成是自发过程，不依赖外力作用。"]},{"id":"ch02_mcq_25","mod":"模块二：跨膜运输","modI":1,"q":"脂质体(liposome)的应用不包括？","o":["A. 生物膜研究模型","B. 药物靶向递送","C. 膜蛋白研究","D. 直接作为能量分子"],"a":"D","e":"脂质体用于膜研究、膜蛋白研究、药物载体/靶向递送，不是能量分子。","kp":"ch02_s1_10","oe":["脂质体可作研究生物膜结构与功能的模型，属其应用。","脂质体可包裹药物用于靶向递送，属其应用。","脂质体可用于膜蛋白的体外研究，属其应用。","脂质体是膜结构模型与药物载体，不能直接作为能量分子，故为答案。"]}],"judge":[{"id":"ch02_judge_7","modI":1,"q":"通道蛋白转运物质时需要与被转运分子结合，并发生构象变化。","a":"错","e":"通道蛋白形成亲水通道，不需与底物结合；发生构象变化转运的是载体蛋白。","kp":"ch02_s1_5","oe":["若以为通道蛋白也需结合底物并变构则判对，混淆了通道与载体。","通道蛋白形成亲水通道，不与底物结合；变构转运的是载体蛋白。"]},{"id":"ch02_judge_8","modI":1,"q":"Na+/K+-ATPase每水解1个ATP，泵出3个Na+、泵入2个K+。","a":"对","e":"每水解1个ATP，泵出3Na+、泵入2K+，维持膜两侧离子梯度。","kp":"ch02_s1_19","oe":["Na+/K+-ATPase每水解1个ATP，泵出3个Na+、泵入2个K+。","误把泵出泵入离子数或比例记反，如3K+出2Na+入，故判错。"]},{"id":"ch02_judge_9","modI":1,"q":"动物细胞静息电位主要来自Na+/K+泵产生的K+浓度梯度及静息时质膜对K+通透性大于Na+。","a":"对","e":"静息时K+泄漏通道开放，质膜对K+通透性大于Na+，K+外流形成静息电位。","kp":"ch02_s1_23","oe":["静息时K+泄漏通道开放，膜对K+通透性大于Na+，K+外流形成静息电位。","误以为静息电位主要由Na+内流形成，或其离子基础记错，故判错。"]},{"id":"ch02_judge_10","modI":1,"q":"水通道蛋白(aquaporin)的发现获得2003年诺贝尔化学奖。","a":"对","e":"2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。","kp":"ch02_s1_8","oe":["2003年诺贝尔化学奖授予Agre(水通道)和MacKinnon(钾通道)。","误记为生理学或医学奖或年份记错，故判错。"]}],"fill":[{"id":"ch02_fill_7","modI":1,"q":"Na+/K+-ATPase每水解1个ATP,泵出________个Na+,泵入________个K+。","a":"3,2","kp":"ch02_s1_19","oe":["钠钾泵每水解1个ATP泵出3个Na+到细胞外。","同时泵入2个K+到细胞内，维持细胞内高钾低钠。"]},{"id":"ch02_fill_8","modI":1,"q":"动物细胞静息电位主要来自________产生的K+浓度梯度及静息时质膜对________通透性大于Na+。","a":"Na+/K+泵,K+","kp":"ch02_s1_23","oe":["静息电位主要来自钠钾泵形成的K+浓度梯度，细胞内K+浓度高。","静息时质膜对K+的通透性大于Na+，K+外流形成静息电位。"]},{"id":"ch02_fill_9","modI":1,"q":"水通道蛋白(aquaporin)由________个相同亚基组成四聚体,其发现获________年诺贝尔化学奖。","a":"4,2003","kp":"ch02_s1_11","oe":["水通道蛋白由4个相同亚基组成四聚体，每亚基含一个水通道。","水通道蛋白的发现获2003年诺贝尔化学奖。"]},{"id":"ch02_fill_10","modI":1,"q":"小肠上皮细胞顶端面由________(SGLT)利用Na+梯度主动吸收葡萄糖,基底面由________(Glut2)协助扩散入血。","a":"葡萄糖-Na+同向转运蛋白,葡萄糖载体2","kp":"ch02_s1_30","oe":["小肠上皮细胞顶端面由葡萄糖-Na+同向转运蛋白利用Na+梯度主动吸收葡萄糖。","基底面由葡萄糖载体2(Glut2)以协助扩散方式将葡萄糖转运入血。"]},{"id":"ch02_fill_11","modI":1,"q":"通道蛋白的三种门控方式是________、________和________。","a":"膜电压门控,配体门控,应力门控","kp":"ch02_s1_5","oe":["膜电位变化引起通道构象改变而开放，如电压门控钠、钾通道。","配体结合通道后引起通道开放，如乙酰胆碱受体阳离子通道。","机械力或膜张力改变使通道开放，如耳蜗毛细胞机械敏感通道。"]}],"short":[{"id":"ch02_short_4","modI":1,"q":"简述Na+/K+-ATPase的结构、机制及生理作用。","a":"结构：2个α亚基+2个β亚基。α亚基具ATP酶活性、与Na+结合。\n\n机制：每水解1个ATP，将细胞内3个Na+泵出细胞外，同时输入2个K+。α亚基与Na+结合促进ATP水解→磷酸化→构象变化→Na+泵出、K+泵入。\n\n生理作用：\n①建立并维持膜两侧离子浓度梯度(胞内高K+、低Na+)；\n②建立细胞膜电位(membrane potential)，特别是神经和肌肉等可兴奋细胞，是信号传递的基础；\n③维持渗透平衡——泵出Na+，胞外高Na+、Cl-帮助维持膜内外渗透压平衡；\n④维持细胞质基质pH稳态；\n⑤为协同运输提供驱动力(如葡萄糖-Na+同向转运)。\n\n【诺贝尔奖】Na+/K+-ATPase研究获诺贝尔奖。若泵停止工作，细胞吸水膨胀破裂。","kp":"ch02_s1_20"},{"id":"ch02_short_5","modI":1,"q":"比较被动运输与主动运输,并举例说明。","a":"被动运输 vs 主动运输：\n\n【被动运输】\n• 顺浓度梯度，不消耗能量；\n• ①简单扩散：不需载体，如O2、CO2、N2、激素等疏水小分子；\n• ②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT进入细胞、离子经通道蛋白；\n• 通道蛋白只参与被动运输，转运速率最快(电压/配体/应力门控)。\n\n【主动运输】\n• 逆浓度梯度，需消耗能量(ATP/光能/离子梯度)，需载体蛋白；\n• 三种动力方式：ATP驱动泵(Na+/K+-ATPase、Ca2+泵)、离子梯度驱动(协同运输)、光能驱动；\n• 同向协同运输(symport)如葡萄糖-Na+同向转运；反向协同运输(antiport)。\n\n【例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运(继发性主动运输)，基底Glut2协助扩散入血。\n\n【比较】被动运输不需能量、顺梯度；主动运输需能量、逆梯度。","kp":"ch02_s1_16"},{"id":"ch02_short_6","modI":1,"q":"简述静息电位的产生机制及K+通道的选择性原理。","a":"【静息电位的产生】\n①Na+/K+泵产生K+浓度梯度(胞内高K+)；\n②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因；\n③K+经K+泄漏通道外流，使膜外带正电、膜内带负电，形成膜电位；\n④膜电位由接近膜的一薄层(<1nm)离子产生。\n静息神经元中K+泄漏通道开放，而数量更多的门控通道关闭。\n\n【K+通道的选择性原理】\n①所有K+通道都有选择性滤器；\n②K+去水化(dehydration)需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿；\n③Na+离子半径小、去水化能量高，不能与滤器结合补偿，故被排斥；\n④结果：K+通道只允许K+通过。\n\n【动作电位】细胞受刺激时膜电位去极化或超极化，形成动作电位，是神经信号传导的基础。","kp":"ch02_s1_25"}],"calc":[{"id":"ch02_calc_2","modI":1,"q":"论述跨膜运输的主要方式及其机制。","a":"跨膜运输分为被动运输和主动运输两大类,机制各异","steps":"【被动运输】(顺浓度梯度，不耗能)\n①简单扩散：疏水小分子(O2/CO2/激素)直接穿过脂双层；\n②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT、水经AQP、离子经通道。\n• 通道蛋白：形成亲水通道，不与底物结合，速率最快，电压/配体/应力门控；\n• 载体蛋白：构象变化转运，如GLUT1、ADP/ATP载体。\n\n【主动运输】(逆浓度梯度，耗能，需载体)\n①ATP驱动泵：Na+/K+-ATPase(3Na+出/2K+入)、Ca2+泵、H+泵(植物)；\n②离子梯度驱动(协同运输)：同向(symport,如葡萄糖-Na+)、反向(antiport)；\n③光能驱动：细菌视紫红质。\n\n【实例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运；基底Glut2协助扩散。\n\n【意义】\n①被动运输实现顺梯度的快速交换；\n②主动运输维持离子梯度、膜电位、渗透平衡、pH稳态，是细胞生存的基础。","kp":"ch02_s1_1"}],"term":[{"id":"ch02_term_10","modI":1,"term":"被动运输(Passive Transport)","def":"①顺浓度梯度、不消耗能量的跨膜运输（定义）。②类型：简单扩散(不需载体，如O2/CO2)、协助扩散(需载体/通道蛋白，如葡萄糖经GLUT)（类型）。③特点：顺浓度梯度、不耗能（特点）。","kps":"踩分点:①定义(1分)②类型(2分)③特点(1分)","kp":"ch02_s1_1"},{"id":"ch02_term_11","modI":1,"term":"主动运输(Active Transport)","def":"①逆浓度梯度、需消耗能量、需载体蛋白的跨膜运输（定义）。②三种动力：ATP驱动泵、离子梯度驱动(协同运输)、光能驱动（动力）。③举例：Na+/K+-ATPase、Ca2+泵、葡萄糖-Na+同向转运（举例）。④意义：维持离子梯度、膜电位、渗透平衡、pH稳态（意义）。","kps":"踩分点:①定义(1分)②三种动力(1分)③举例(1分)④意义(1分)","kp":"ch02_s1_17"},{"id":"ch02_term_12","modI":1,"term":"Na+/K+-ATPase(Na+/K+泵)","def":"①动物细胞质膜上逆浓度梯度泵出Na+、泵入K+的离子泵（定义）。②结构：2α+2β亚基（结构）。③机制：每水解1个ATP，泵出3Na+、泵入2K+（机制）。④作用：建立膜电位、维持渗透平衡和pH稳态、为协同运输供能（作用）。","kps":"踩分点:①定义(1分)②结构(1分)③机制(1分)④作用(1分)","kp":"ch02_s1_20"},{"id":"ch02_term_13","modI":1,"term":"水通道蛋白(Aquaporin)","def":"①介导水快速跨膜运输的通道蛋白（定义）。②结构：4个相同亚基组成四聚体，每亚基6个跨膜α螺旋（结构）。③选择性：通道直径0.28nm，中心带正电荷(Arg/His)排斥阳离子（选择性）。④意义：发现获2003年诺贝尔化学奖(Peter Agre)（意义）。","kps":"踩分点:①定义(1分)②结构(1分)③选择性(1分)④诺贝尔奖(1分)","kp":"ch02_s1_14"},{"id":"ch02_term_14","modI":1,"term":"协同运输(Cotransport)","def":"①由离子泵建立的离子梯度驱动、经载体蛋白逆浓度转运物质的主动运输（定义）。②类型：同向协同运输(symport，如葡萄糖-Na+)、反向协同运输(antiport)（类型）。③动力：膜两侧离子的电化学梯度（动力）。④举例：小肠上皮细胞顶端SGLT吸收葡萄糖（举例）。","kps":"踩分点:①定义(1分)②类型(1分)③动力(1分)④举例(1分)","kp":"ch02_s1_27"},{"id":"ch02_term_15","modI":1,"term":"膜电位(Membrane Potential)","def":"①细胞膜两侧的电位差，由膜两侧离子分布不均产生（定义）。②产生：Na+/K+泵建立K+浓度梯度，静息时质膜对K+通透性大于Na+→K+外流（机制）。③意义：可兴奋细胞(神经/肌肉)信号传递的基础；动作电位是膜电位去极化/超极化的结果（意义）。","kps":"踩分点:①定义(1分)②产生机制(2分)③意义(1分)","kp":"ch02_s1_21"}]}],"mcq":[{"id":"ch02_mcq_1","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"生物膜流动镶嵌模型的提出者和年份是？","o":["A. Singer & Nicolson,1972","B. Watson & Crick,1953","C. Robertson,1964","D. Singer,1988"],"a":"A","e":"1972年Singer和Nicolson提出流动镶嵌模型：磷脂双分子层为基本骨架，蛋白质镶嵌其中，膜具流动性。","kp":"ch02_s0_2","oe":["正确。1972年Singer和Nicolson提出流动镶嵌模型，故正确。","错。Watson和Crick于1953年提出DNA双螺旋结构，与膜模型无关。","错。Robertson提出的是单位膜模型，不是流动镶嵌模型。","错。Singer提出流动镶嵌模型的年份是1972年，而非1988年。"]},{"id":"ch02_mcq_2","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"占整个膜脂50%以上的膜脂是？","o":["A. 胆固醇","B. 甘油磷脂","C. 鞘脂","D. 糖脂"],"a":"B","e":"甘油磷脂为膜脂基本成分，占整个膜脂50%以上。包括磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇。","kp":"ch02_s0_7","oe":["错。胆固醇属固醇类，含量远低于甘油磷脂，不是含量最高的膜脂。","正确。甘油磷脂占整个膜脂50%以上，是膜脂的基本成分，故正确。","错。鞘脂含量少于甘油磷脂，不是占膜脂50%以上的成分。","错。糖脂含量也低于甘油磷脂，不是含量最高的膜脂。"]},{"id":"ch02_mcq_3","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"关于胆固醇在膜中的作用,错误的是？","o":["A. 自身不能形成脂双层","B. 调节膜的流动性","C. 是脂筏基本结构成分","D. 是膜脂含量最高的成分"],"a":"D","e":"胆固醇自身不能形成脂双层，只能插入磷脂之间；调节流动性、增加稳定性；是脂筏成分。含量最高的膜脂是甘油磷脂。","kp":"ch02_s0_9","oe":["正确。胆固醇自身不能形成脂双层，只能插入磷脂分子之间。","正确。胆固醇能调节膜的流动性，叙述正确。","正确。胆固醇是脂筏的基本结构成分，叙述正确。","错误。膜脂中含量最高的是甘油磷脂而非胆固醇，故选D。"]},{"id":"ch02_mcq_4","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"膜脂运动的基本方式是？","o":["A. 翻转运动","B. 侧向运动","C. 尾部摆动","D. 自旋"],"a":"B","e":"同一侧的侧向运动是膜脂运动的基本方式。翻转运动(flip-flop)较慢，需酶协助。","kp":"ch02_s0_12","oe":["错。翻转运动速度很慢且需酶协助，不是膜脂运动的基本方式。","正确。同一侧磷脂分子间的侧向运动是膜脂运动的基本方式，故正确。","错。尾部摆动只是脂肪酸尾的一种运动形式，不是基本方式。","错。自旋是膜脂的一种运动形式，但基本方式是侧向运动。"]},{"id":"ch02_mcq_5","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"膜脂和膜蛋白在膜上的分布特点是？","o":["A. 完全对称","B. 不对称分布","C. 随机分布","D. 只在胞外侧"],"a":"B","e":"膜脂和膜蛋白在生物膜上均呈不对称分布；糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。","kp":"ch02_s0_11","oe":["错。膜脂和膜蛋白在膜上的分布并不完全对称。","正确。膜脂和膜蛋白在生物膜上均呈不对称分布，故正确。","错。膜成分的分布有规律地不对称，而非随机分布。","错。除胞外侧外，胞质面也有膜蛋白分布，并非只在胞外侧。"]},{"id":"ch02_mcq_6","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"膜内在蛋白(integral protein)的跨膜方式是？","o":["A. 仅α-螺旋","B. α-螺旋或β-折叠","C. 仅β-折叠","D. 无规则"],"a":"B","e":"内在跨膜整合蛋白以α-螺旋或β-折叠方式跨膜；细菌外膜孔蛋白以β-折叠跨膜。","kp":"ch02_s0_21","oe":["错。膜内在蛋白的跨膜方式不限于α-螺旋。","正确。内在整合蛋白以α-螺旋或β-折叠方式跨膜，故正确。","错。并非只有β-折叠，多数跨膜蛋白以α-螺旋跨膜。","错。跨膜区有规则的二级结构，并非无规则。"]},{"id":"ch02_mcq_7","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"人红细胞膜骨架蛋白中的血影蛋白属于？","o":["A. 内在蛋白","B. 外周蛋白","C. 脂锚定蛋白","D. 通道蛋白"],"a":"B","e":"血影蛋白、肌动蛋白以非共价键结合在膜内侧，属于外周膜蛋白，构成膜骨架。","kp":"ch02_s0_23","oe":["错。血影蛋白以非共价键结合于膜内侧，属外周蛋白而非内在蛋白。","正确。血影蛋白以非共价键结合膜内侧，属外周蛋白并构成膜骨架，故正确。","错。血影蛋白不与膜脂共价连接，不属于脂锚定蛋白。","错。血影蛋白是膜骨架蛋白，不是通道蛋白。"]},{"id":"ch02_mcq_8","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"需要用特定酶才能从膜上释放的膜蛋白是？","o":["A. 外周蛋白","B. 脂锚定蛋白","C. 内在蛋白","D. 跨膜蛋白"],"a":"B","e":"脂锚定蛋白与膜脂共价连接，改变pH或离子强度不能去除，需特定酶(如磷脂酶)才能释放。","kp":"ch02_s0_24","oe":["错。外周蛋白改变pH或离子强度即可去除，不需要特定酶。","正确。脂锚定蛋白与膜脂共价连接，需特定酶如磷脂酶才能释放，故正确。","错。内在蛋白通常需去垢剂溶解，而不是用特定酶释放。","错。跨膜蛋白属内在蛋白，其释放主要靠去垢剂而非特定酶。"]},{"id":"ch02_mcq_9","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"影响膜流动性最主要的因素是？","o":["A. pH","B. 温度","C. 离子强度","D. 膜蛋白种类"],"a":"B","e":"温度是影响膜流动性最主要的因素。温度降低到相变温度时膜脂由液晶态转变为凝胶态。","kp":"ch02_s0_30","oe":["pH改变膜脂与膜蛋白的带电状态，但不是决定流动性的最主要因素。","温度是影响膜流动性最主要的因素，降至相变温度时膜脂由液晶态转为凝胶态。","离子强度主要影响膜表面电荷与静电作用，对膜流动性影响并非最主要。","膜蛋白种类影响膜的功能，而膜流动性主要由脂质分子的性质决定。"]},{"id":"ch02_mcq_10","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"下列关于膜流动性的说法正确的是？","o":["A. 脂肪酸链越长流动性越高","B. 不饱和脂肪酸越多流动性越高","C. 胆固醇总是增加流动性","D. 饱和脂肪酸越多流动性越高"],"a":"B","e":"短链脂肪酸、不饱和脂肪酸(双键多)使流动性高；长链、饱和脂肪酸降低流动性；胆固醇双向调节。","kp":"ch02_s0_28","oe":["脂肪酸链越长，疏水相互作用越强，膜流动性越低，故该说法错误。","不饱和脂肪酸含双键、尾部弯曲，使膜脂排列疏松，流动性升高，正确。","胆固醇具双向调节作用：高温降低流动性、低温阻止凝固，并非总是增加。","饱和脂肪酸链排列紧密，越多则膜流动性越低，故该说法错误。"]},{"id":"ch02_mcq_11","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"研究膜分子扩散速率的经典技术是？","o":["A. FRAP","B. PCR","C. SDS-PAGE","D. 电镜"],"a":"A","e":"荧光漂白恢复技术(FRAP)：标记→激光漂白→观察荧光恢复→测定扩散速率。","kp":"ch02_s0_29","oe":["FRAP荧光漂白恢复技术可标记并漂白膜分子，观察荧光恢复以测扩散速率，正确。","PCR是体外扩增DNA的技术，与膜分子扩散速率研究无关。","SDS-PAGE是分离蛋白质的电泳技术，不能测定膜分子扩散速率。","电镜用于观察膜的超微结构，无法直接测定膜分子的扩散速率。"]},{"id":"ch02_mcq_12","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"人工脂双层对下列哪种物质通透性最低？","o":["A. O2","B. H2O","C. 葡萄糖","D. Na+等离子"],"a":"D","e":"离子几乎不能通过人工脂双层，需通道/载体蛋白。通透性：疏水分子>小极性分子>大极性分子>离子。","kp":"ch02_s1_2","oe":["O2为疏水小分子，可自由溶于脂双层并扩散，通透性高。","H2O为小极性分子，可缓慢通过脂双层，通透性并非最低。","葡萄糖为大极性分子，通透性较低但仍可测出，不是最低。","Na+等为带电离子，几乎不能通过人工脂双层，通透性最低，正确。"]},{"id":"ch02_mcq_13","mod":"模块一：生物膜结构模型与组成","modI":0,"q":"通道蛋白的特点是？","o":["A. 需与运输分子结合","B. 只参与被动运输,转运速率最快","C. 逆浓度梯度运输","D. 需消耗ATP"],"a":"B","e":"通道蛋白形成亲水通道，不需与底物结合，只参与被动运输，转运速率最快；有电压/配体/应力三种门控。","kp":"ch02_s1_5","oe":["通道蛋白形成亲水通道，转运时无需与被转运分子结合，故该说法错误。","通道蛋白只介导被动运输且转运速率最快，符合其特点，正确。","通道蛋白只能顺电化学梯度转运，不能逆浓度梯度运输。","通道蛋白介导被动运输，不需要消耗ATP。"]},{"id":"ch02_mcq_14","mod":"模块二：跨膜运输","modI":1,"q":"水通道蛋白(aquaporin)的发现对应哪年的诺贝尔化学奖？","o":["A. 2003年","B. 1997年","C. 2012年","D. 2006年"],"a":"A","e":"2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。","kp":"ch02_s1_8","oe":["2003年诺贝尔化学奖授予发现水通道的Agre，与钾通道的MacKinnon共享，正确。","1997年化学奖授予ATP合酶与Na+/K+-ATPase相关研究，与水通道无关。","2012年化学奖授予G蛋白偶联受体的研究，与水通道发现无关。","2006年化学奖授予真核转录机制研究，与水通道发现无关。"]},{"id":"ch02_mcq_15","mod":"模块二：跨膜运输","modI":1,"q":"Na+/K+-ATPase每水解1个ATP转运的离子数是？","o":["A. 泵出2Na+,泵入3K+","B. 泵出3Na+,泵入2K+","C. 泵出3Na+,泵入3K+","D. 泵出2Na+,泵入2K+"],"a":"B","e":"每水解1个ATP，将3个Na+泵出细胞、2个K+泵入细胞，维持膜两侧离子梯度。","kp":"ch02_s1_19","oe":["Na+/K+-ATPase泵出3个Na+、泵入2个K+，该选项数量与方向均反。","每水解1个ATP，泵出3个Na+、泵入2个K+，正确。","该泵转运3个Na+出、2个K+入，并非3Na+对3K+。","该泵每水解1个ATP转运3Na+与2K+，不是2Na+对2K+。"]},{"id":"ch02_mcq_16","mod":"模块二：跨膜运输","modI":1,"q":"动物细胞静息电位产生的主要原因是？","o":["A. 静息时质膜对K+通透性大于Na+","B. 静息时质膜对Na+通透性大于K+","C. 钙泵活动","D. 水通道开放"],"a":"A","e":"静息电位主要来自Na+/K+泵产生的K+浓度梯度，以及静息时质膜对K+通透性大于Na+。","kp":"ch02_s1_23","oe":["静息时质膜对K+通透性大于Na+，K+外流形成静息电位，正确。","静息时膜对Na+通透性远小于K+，该选项恰好说反。","钙泵主要维持胞内低钙，不是产生静息电位的主要原因。","水通道只转运水，不产生跨膜电位，与静息电位无关。"]},{"id":"ch02_mcq_17","mod":"模块二：跨膜运输","modI":1,"q":"K+通道选择性的分子基础是？","o":["A. 通道大小","B. 去水化能量与滤器羰基氧结合能相平衡","C. 膜电位","D. 通道正电荷"],"a":"B","e":"K+去水化所需能量恰好由K+与选择性滤器羰基氧结合释放的能量补偿→只有K+能通过，Na+被排斥。","kp":"ch02_s1_25","oe":["仅凭通道大小不能解释更小的Na+反而不能通过，故不是选择性基础。","K+去水化耗能与滤器羰基氧结合能相平衡，故仅K+能通过，正确。","膜电位只决定通道的开闭门控，不决定离子选择性。","K+通道选择性依赖滤器羰基氧，正电荷主要见于水通道的排阳离子机制。"]},{"id":"ch02_mcq_18","mod":"模块二：跨膜运输","modI":1,"q":"水通道的选择性由什么决定？","o":["A. 直径0.28nm+中心正电荷(Arg/His)","B. 只有疏水作用","C. 膜电位","D. 通道长度"],"a":"A","e":"水通道直径仅0.28nm，无法通过比水大的分子；通道中心最窄处带正电荷(Arg-195、His-180)排斥阳离子，只允许水通过。","kp":"ch02_s1_13","oe":["水通道直径约0.28nm且中心带正电荷(Arg/His)，只允许水通过，正确。","水通道的选择性不只靠疏水作用，还依赖孔径与中心正电荷。","膜电位影响通道门控，不决定水通道的选择性。","通道长度与水通道的选择性无关，选择性取决于孔径和电荷。"]},{"id":"ch02_mcq_19","mod":"模块二：跨膜运输","modI":1,"q":"主动运输的特点不包括？","o":["A. 逆浓度梯度","B. 需要能量","C. 需载体蛋白","D. 顺浓度梯度不耗能"],"a":"D","e":"主动运输逆浓度梯度、需能量(ATP/光能/离子梯度)、需载体蛋白。顺浓度梯度不耗能是被动运输。","kp":"ch02_s1_16","oe":["主动运输逆浓度梯度进行，这是其基本特点之一。","主动运输需要消耗能量(ATP、光能或离子梯度)，属其特点。","主动运输需要载体蛋白协助，属其特点。","顺浓度梯度且不耗能是被动运输的特征，不属于主动运输，故为答案。"]},{"id":"ch02_mcq_20","mod":"模块二：跨膜运输","modI":1,"q":"小肠上皮细胞吸收葡萄糖的过程是？","o":["A. 简单扩散","B. 顶端SGLT(Na+同向主动运输)+基底Glut2(协助扩散)","C. 仅主动运输","D. 仅胞吞"],"a":"B","e":"顶端面SGLT利用Na+梯度主动转运葡萄糖入胞；基底面Glut2被动协助扩散入血。两步完成逆浓度吸收。","kp":"ch02_s1_30","oe":["葡萄糖为极性分子，不能靠简单扩散通过小肠上皮质膜。","顶端SGLT借Na+梯度主动转运、基底Glut2经协助扩散入血，正确。","吸收由主动运输与协助扩散两步共同完成，并非仅主动运输。","小肠吸收葡萄糖不通过胞吞，而是经载体蛋白转运。"]},{"id":"ch02_mcq_21","mod":"模块二：跨膜运输","modI":1,"q":"协同运输(symport)是指？","o":["A. 两种物质反向转运","B. 两种物质同向转运","C. 仅一种物质","D. 需光能"],"a":"B","e":"同向协同运输(symport)两种物质同方向；反向协同运输(antiport)方向相反。如葡萄糖-Na+同向转运。","kp":"ch02_s1_27","oe":["两种物质反向转运属于反向协同运输(antiport)，不是symport。","同向协同运输指两种物质同方向转运，正确。","协同运输涉及两种物质，不是仅一种物质转运。","协同运输的能量可来自离子梯度，通常不需光能。"]},{"id":"ch02_mcq_22","mod":"模块二：跨膜运输","modI":1,"q":"植物细胞质膜上代替Na+/K+泵的离子泵是？","o":["A. Ca2+泵","B. H+泵","C. Cl-泵","D. 水通道"],"a":"B","e":"植物细胞、细菌、真菌质膜上没有Na+/K+泵，取而代之的是H+泵，泵出H+建立质子梯度。","kp":"ch02_s1_33","oe":["Ca2+泵在植物细胞存在，但并非代替Na+/K+泵的离子泵。","植物细胞质膜以H+泵泵出H+建立质子梯度，代替Na+/K+泵，正确。","Cl-泵不是植物质膜上代替Na+/K+泵的离子泵。","水通道只转运水，不能代替离子泵建立电化学梯度。"]},{"id":"ch02_mcq_23","mod":"模块二：跨膜运输","modI":1,"q":"脂筏(lipid raft)的主要组成是？","o":["A. 甘油磷脂为主","B. 胆固醇、鞘磷脂富集区","C. 仅蛋白质","D. 仅糖脂"],"a":"B","e":"脂筏是膜上胆固醇、鞘磷脂等富集的相对独立微区域，承载特定膜蛋白，参与信号传递。","kp":"ch02_s0_4","oe":["脂筏富含鞘磷脂和胆固醇，而非以甘油磷脂为主。","脂筏是胆固醇与鞘磷脂富集的微区域，并承载特定膜蛋白，正确。","脂筏除蛋白外还含大量脂质，并非仅由蛋白质组成。","脂筏不只有糖脂，还富含胆固醇和鞘磷脂。"]},{"id":"ch02_mcq_24","mod":"模块二：跨膜运输","modI":1,"q":"膜脂形成脂双层的原因是？","o":["A. 两性分子在水中的自装配","B. 共价键连接","C. 酶催化","D. 外力作用"],"a":"A","e":"膜脂为两性分子(亲水头+疏水尾)，在水中自动、自我装配形成连续不破裂的脂双层。","kp":"ch02_s0_15","oe":["膜脂为两性分子，在水中可自装配成连续脂双层，正确。","膜脂形成脂双层靠疏水作用等非共价作用，而非共价键连接。","脂双层是膜脂自发的自装配过程，不需要酶催化。","脂双层形成是自发过程，不依赖外力作用。"]},{"id":"ch02_mcq_25","mod":"模块二：跨膜运输","modI":1,"q":"脂质体(liposome)的应用不包括？","o":["A. 生物膜研究模型","B. 药物靶向递送","C. 膜蛋白研究","D. 直接作为能量分子"],"a":"D","e":"脂质体用于膜研究、膜蛋白研究、药物载体/靶向递送，不是能量分子。","kp":"ch02_s0_17","oe":["脂质体可作研究生物膜结构与功能的模型，属其应用。","脂质体可包裹药物用于靶向递送，属其应用。","脂质体可用于膜蛋白的体外研究，属其应用。","脂质体是膜结构模型与药物载体，不能直接作为能量分子，故为答案。"]}],"judge":[{"id":"ch02_judge_1","modI":0,"q":"流动镶嵌模型由Singer和Nicolson于1972年提出。","a":"对","e":"1972年Singer和Nicolson提出流动镶嵌模型，是膜结构研究的里程碑。","kp":"ch02_s0_2","oe":["1972年Singer和Nicolson提出流动镶嵌模型，是膜结构研究的里程碑。","误记为1972年由其他学者提出，或年代记错，故判错。"]},{"id":"ch02_judge_2","modI":0,"q":"甘油磷脂是膜脂中含量最高的成分，占膜脂50%以上。","a":"对","e":"甘油磷脂为膜脂基本成分，占整个膜脂50%以上。","kp":"ch02_s0_7","oe":["甘油磷脂是膜脂基本成分，占整个膜脂50%以上，含量最高。","误把胆固醇或糖脂当成含量最高成分，故判错。"]},{"id":"ch02_judge_3","modI":0,"q":"胆固醇自身能形成脂双层，是构成膜骨架的主要成分。","a":"错","e":"胆固醇自身不能形成脂双层，只能插入磷脂分子之间，起调节流动性等作用。","kp":"ch02_s0_9","oe":["若以为胆固醇能独立形成脂双层则判对，混淆了它与磷脂的作用。","胆固醇自身不能形成脂双层，只能插入磷脂分子间调节流动性，非膜骨架。"]},{"id":"ch02_judge_4","modI":0,"q":"膜脂和膜蛋白在膜上呈不对称分布，糖脂的糖基位于细胞外侧。","a":"对","e":"膜脂、膜蛋白均呈不对称分布；糖蛋白和糖脂的糖基位于质膜外侧(非胞质面)。","kp":"ch02_s0_11","oe":["膜脂与膜蛋白均不对称分布，糖脂糖基位于质膜外侧非胞质面。","误以为糖基位于胞质面或膜分布对称，故判错。"]},{"id":"ch02_judge_5","modI":0,"q":"温度降低到相变温度以下时，膜脂由液晶态转变为凝胶态，流动性降低。","a":"对","e":"温度是影响膜流动性最主要的因素；降至相变温度以下膜脂由液晶态变凝胶态。","kp":"ch02_s0_30","oe":["温度降至相变温度以下，膜脂由液晶态转为凝胶态，流动性降低。","误以为降温使流动性升高，或相变方向记反，故判错。"]},{"id":"ch02_judge_6","modI":0,"q":"不饱和脂肪酸含量越高，膜流动性越低。","a":"错","e":"不饱和脂肪酸含双键、分子弯曲、排列疏松，含量越高流动性越高。","kp":"ch02_s0_34","oe":["若以为不饱和脂肪酸多则流动性低则判对，实则相反。","不饱和脂肪酸含双键、分子弯曲、排列疏松，含量越高流动性越高。"]},{"id":"ch02_judge_7","modI":1,"q":"通道蛋白转运物质时需要与被转运分子结合，并发生构象变化。","a":"错","e":"通道蛋白形成亲水通道，不需与底物结合；发生构象变化转运的是载体蛋白。","kp":"ch02_s1_5","oe":["若以为通道蛋白也需结合底物并变构则判对，混淆了通道与载体。","通道蛋白形成亲水通道，不与底物结合；变构转运的是载体蛋白。"]},{"id":"ch02_judge_8","modI":1,"q":"Na+/K+-ATPase每水解1个ATP，泵出3个Na+、泵入2个K+。","a":"对","e":"每水解1个ATP，泵出3Na+、泵入2K+，维持膜两侧离子梯度。","kp":"ch02_s1_19","oe":["Na+/K+-ATPase每水解1个ATP，泵出3个Na+、泵入2个K+。","误把泵出泵入离子数或比例记反，如3K+出2Na+入，故判错。"]},{"id":"ch02_judge_9","modI":1,"q":"动物细胞静息电位主要来自Na+/K+泵产生的K+浓度梯度及静息时质膜对K+通透性大于Na+。","a":"对","e":"静息时K+泄漏通道开放，质膜对K+通透性大于Na+，K+外流形成静息电位。","kp":"ch02_s1_23","oe":["静息时K+泄漏通道开放，膜对K+通透性大于Na+，K+外流形成静息电位。","误以为静息电位主要由Na+内流形成，或其离子基础记错，故判错。"]},{"id":"ch02_judge_10","modI":1,"q":"水通道蛋白(aquaporin)的发现获得2003年诺贝尔化学奖。","a":"对","e":"2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。","kp":"ch02_s1_8","oe":["2003年诺贝尔化学奖授予Agre(水通道)和MacKinnon(钾通道)。","误记为生理学或医学奖或年份记错，故判错。"]}],"fill":[{"id":"ch02_fill_1","modI":0,"q":"生物膜流动镶嵌模型由________和________于________年提出。","a":"Singer,Nicolson,1972","kp":"ch02_s0_2","oe":["1972年Singer提出流动镶嵌模型，强调膜脂双层的流动性。","Nicolson与Singer共同提出流动镶嵌模型，阐明膜蛋白镶嵌分布。","该模型于1972年提出，取代了此前的三明治模型。"]},{"id":"ch02_fill_2","modI":0,"q":"膜脂三大类是________、________和________,都是________分子。","a":"甘油磷脂,鞘脂,胆固醇,两性","kp":"ch02_s0_6","oe":["甘油磷脂是膜脂主要成分，以甘油为骨架连接两条脂肪酸链。","鞘脂以鞘氨醇为骨架，是膜脂的另一大类。","胆固醇插入磷脂之间，调节膜的流动性和稳定性。","三类膜脂均含亲水头和疏水尾，属两性分子。"]},{"id":"ch02_fill_3","modI":0,"q":"占膜脂50%以上的是________；不能自身形成脂双层、只能插入磷脂之间的是________。","a":"甘油磷脂,胆固醇","kp":"ch02_s0_7","oe":["甘油磷脂占膜脂50%以上，是构成脂双层的主要成分。","胆固醇不能自身形成脂双层，只能插入磷脂分子之间起调节作用。"]},{"id":"ch02_fill_4","modI":0,"q":"膜脂运动的基本方式是________；双层分子间的________运动较慢。","a":"侧向运动,翻转(flip-flop)","kp":"ch02_s0_12","oe":["膜脂分子在同一层内进行侧向运动，是最基本的运动方式。","脂分子从一层翻转到另一层的翻转运动很慢，需酶协助。"]},{"id":"ch02_fill_5","modI":0,"q":"膜内在蛋白以________或________方式跨膜；外周蛋白以________键结合在膜上。","a":"α-螺旋,β-折叠,非共价","kp":"ch02_s0_21","oe":["膜内在蛋白多以α-螺旋跨膜，疏水氨基酸侧链与膜脂疏水区结合。","部分跨膜蛋白以β-折叠桶形式跨膜，可形成通道结构。","外周蛋白以非共价键(离子键、氢键)结合在膜表面或内在蛋白上。"]},{"id":"ch02_fill_6","modI":0,"q":"影响膜流动性最主要的因素是________；不饱和脂肪酸越多,流动性越________。","a":"温度,高","kp":"ch02_s0_30","oe":["温度是影响膜流动性最主要的因素，适当升温使流动性增大。","不饱和脂肪酸越多，脂肪酸链排列越松散，膜流动性越高。"]},{"id":"ch02_fill_7","modI":1,"q":"Na+/K+-ATPase每水解1个ATP,泵出________个Na+,泵入________个K+。","a":"3,2","kp":"ch02_s1_19","oe":["钠钾泵每水解1个ATP泵出3个Na+到细胞外。","同时泵入2个K+到细胞内，维持细胞内高钾低钠。"]},{"id":"ch02_fill_8","modI":1,"q":"动物细胞静息电位主要来自________产生的K+浓度梯度及静息时质膜对________通透性大于Na+。","a":"Na+/K+泵,K+","kp":"ch02_s1_23","oe":["静息电位主要来自钠钾泵形成的K+浓度梯度，细胞内K+浓度高。","静息时质膜对K+的通透性大于Na+，K+外流形成静息电位。"]},{"id":"ch02_fill_9","modI":1,"q":"水通道蛋白(aquaporin)由________个相同亚基组成四聚体,其发现获________年诺贝尔化学奖。","a":"4,2003","kp":"ch02_s1_11","oe":["水通道蛋白由4个相同亚基组成四聚体，每亚基含一个水通道。","水通道蛋白的发现获2003年诺贝尔化学奖。"]},{"id":"ch02_fill_10","modI":1,"q":"小肠上皮细胞顶端面由________(SGLT)利用Na+梯度主动吸收葡萄糖,基底面由________(Glut2)协助扩散入血。","a":"葡萄糖-Na+同向转运蛋白,葡萄糖载体2","kp":"ch02_s1_30","oe":["小肠上皮细胞顶端面由葡萄糖-Na+同向转运蛋白利用Na+梯度主动吸收葡萄糖。","基底面由葡萄糖载体2(Glut2)以协助扩散方式将葡萄糖转运入血。"]},{"id":"ch02_fill_11","modI":1,"q":"通道蛋白的三种门控方式是________、________和________。","a":"膜电压门控,配体门控,应力门控","kp":"ch02_s1_5","oe":["膜电位变化引起通道构象改变而开放，如电压门控钠、钾通道。","配体结合通道后引起通道开放，如乙酰胆碱受体阳离子通道。","机械力或膜张力改变使通道开放，如耳蜗毛细胞机械敏感通道。"]},{"id":"ch02_fill_12","modI":0,"q":"脂筏是膜上________、________等富集的微区域,1988年提出________模型。","a":"胆固醇,鞘磷脂,脂筏(Lipid raft)","kp":"ch02_s0_4","oe":["脂筏富含胆固醇，使膜局部有序、增厚并降低流动性。","鞘磷脂长饱和酰链与胆固醇紧密堆积，形成有序筏状微区。","1988年Simons提出脂筏模型，指膜上富含胆固醇和鞘磷脂的微区。"]}],"short":[{"id":"ch02_short_1","modI":0,"q":"简述生物膜流动镶嵌模型的主要内容。","a":"流动镶嵌模型(1972, Singer & Nicolson)主要内容：\n\n①磷脂双分子层是生物膜的基本结构组分——磷脂具有极性头部(亲水)和非极性尾部(疏水)，在水溶液中自动装配成脂双层；\n②膜蛋白以不同方式镶嵌于脂双层：内在蛋白(跨膜)、外周蛋白(非共价结合)、脂锚定蛋白(共价连接)；\n③膜脂和膜蛋白具有流动性——膜脂可侧向运动、翻转、摆动、自旋；膜蛋白可侧向扩散；\n④膜脂和膜蛋白分布具有不对称性——糖脂/糖蛋白的糖基位于质膜外侧；\n⑤脂类与蛋白质的流动性和不对称性是它们相互作用及与其他生物大分子相互作用的基础；\n⑥这种相互作用又一定程度上限制了膜蛋白和膜脂的流动性。\n\n【发展】此后提出脂筏模型(1988)：膜上胆固醇、鞘磷脂富集形成相对独立的微区域。\n【意义】解释了膜的许多性质：物质运输、信号转导、细胞融合等。","kp":"ch02_s0_2","kps":"磷脂双分子层为骨架;膜蛋白镶嵌(内在/外周/脂锚定);膜脂膜蛋白流动;不对称(糖基在外侧);流动与不对称相互制约"},{"id":"ch02_short_2","modI":0,"q":"简述膜脂的种类、特性及其对膜流动性的影响。","a":"膜脂分三大类：\n①甘油磷脂(占膜脂50%以上)：磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇；\n②鞘脂：鞘氨醇衍生物，分鞘磷脂、鞘糖脂，主要在高尔基体合成；\n③胆固醇：4环碳氢化合物，自身不能形成脂双层，插入磷脂之间。\n都是两性分子(亲水头+疏水尾)。\n\n膜脂特性：\n①不对称性——磷脂、糖脂分布完全不对称，糖脂位于胞外侧，胆固醇均等分布；\n②流动性——侧向运动(基本)、翻转、尾部摆动、自旋。\n\n影响膜流动性的因素：\n①温度(最主要)——温度高流动性大，降至相变温度以下变凝胶态；\n②脂肪酸链长度——短链流动性高；\n③不饱和程度——不饱和度高(双键多)流动性高；\n④胆固醇——双向调节(相变温度以上降低流动性、以下防止凝固)。","kp":"ch02_s0_32","kps":"三类:甘油磷脂、鞘脂、胆固醇;两性分子;不对称;流动;影响因素:温度、链长、不饱和度、胆固醇双向调节"},{"id":"ch02_short_3","modI":0,"q":"简述膜蛋白的类型及分离方法。","a":"膜蛋白类型(按与膜结合方式)：\n\n①膜内在蛋白/跨膜蛋白(intrinsic/integral)：以α-螺旋或β-折叠跨膜，如跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白。\n②外周膜蛋白(peripheral)：以非共价键结合在膜脂极性头部或内在蛋白上，如红细胞膜骨架的血影蛋白、肌动蛋白。\n③脂锚定蛋白：与膜脂特定脂类共价连接，虽位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放，如小G蛋白。\n\n分离方法：\n①外周蛋白——高盐、改变pH或离子强度可洗脱；\n②内在蛋白——需去垢剂(离子型如SDS，非离子型如Triton X-100)溶解；\n③脂锚定蛋白——需特定酶释放。\n\n去垢剂：离子型(SDS)破坏非共价键、可能变性；非离子型(Triton X-100)温和、保持活性。","kp":"ch02_s0_25","kps":"内在/跨膜(α螺旋)、外周(非共价)、脂锚定(共价);分离:外周高盐/变pH,内在去垢剂,脂锚定酶解"},{"id":"ch02_short_4","modI":1,"q":"简述Na+/K+-ATPase的结构、机制及生理作用。","a":"结构：2个α亚基+2个β亚基。α亚基具ATP酶活性、与Na+结合。\n\n机制：每水解1个ATP，将细胞内3个Na+泵出细胞外，同时输入2个K+。α亚基与Na+结合促进ATP水解→磷酸化→构象变化→Na+泵出、K+泵入。\n\n生理作用：\n①建立并维持膜两侧离子浓度梯度(胞内高K+、低Na+)；\n②建立细胞膜电位(membrane potential)，特别是神经和肌肉等可兴奋细胞，是信号传递的基础；\n③维持渗透平衡——泵出Na+，胞外高Na+、Cl-帮助维持膜内外渗透压平衡；\n④维持细胞质基质pH稳态；\n⑤为协同运输提供驱动力(如葡萄糖-Na+同向转运)。\n\n【诺贝尔奖】Na+/K+-ATPase研究获诺贝尔奖。若泵停止工作，细胞吸水膨胀破裂。","kp":"ch02_s1_20","kps":"结构2α+2β,α有ATP酶;1ATP泵出3Na+入2K+;作用:离子梯度、膜电位、渗透平衡、pH稳态、协同运输驱动"},{"id":"ch02_short_5","modI":1,"q":"比较被动运输与主动运输,并举例说明。","a":"被动运输 vs 主动运输：\n\n【被动运输】\n• 顺浓度梯度，不消耗能量；\n• ①简单扩散：不需载体，如O2、CO2、N2、激素等疏水小分子；\n• ②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT进入细胞、离子经通道蛋白；\n• 通道蛋白只参与被动运输，转运速率最快(电压/配体/应力门控)。\n\n【主动运输】\n• 逆浓度梯度，需消耗能量(ATP/光能/离子梯度)，需载体蛋白；\n• 三种动力方式：ATP驱动泵(Na+/K+-ATPase、Ca2+泵)、离子梯度驱动(协同运输)、光能驱动；\n• 同向协同运输(symport)如葡萄糖-Na+同向转运；反向协同运输(antiport)。\n\n【例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运(继发性主动运输)，基底Glut2协助扩散入血。\n\n【比较】被动运输不需能量、顺梯度；主动运输需能量、逆梯度。","kp":"ch02_s1_16","kps":"被动顺浓度不耗能:简单扩散(O2/CO2)、协助扩散(GLUT/通道);主动逆浓度耗能需载体:泵、协同运输(同向/反向)"},{"id":"ch02_short_6","modI":1,"q":"简述静息电位的产生机制及K+通道的选择性原理。","a":"【静息电位的产生】\n①Na+/K+泵产生K+浓度梯度(胞内高K+)；\n②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因；\n③K+经K+泄漏通道外流，使膜外带正电、膜内带负电，形成膜电位；\n④膜电位由接近膜的一薄层(<1nm)离子产生。\n静息神经元中K+泄漏通道开放，而数量更多的门控通道关闭。\n\n【K+通道的选择性原理】\n①所有K+通道都有选择性滤器；\n②K+去水化(dehydration)需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿；\n③Na+离子半径小、去水化能量高，不能与滤器结合补偿，故被排斥；\n④结果：K+通道只允许K+通过。\n\n【动作电位】细胞受刺激时膜电位去极化或超极化，形成动作电位，是神经信号传导的基础。","kp":"ch02_s1_25","kps":"静息:钠钾泵造K+梯度,膜对K+通透大,K+泄漏外流致外正内负;选择性:滤器、K+去水化能由羰基氧结合补偿,Na+被排斥"},{"id":"ch02_short_x1","modI":1,"q":"比较简单扩散、协助扩散和主动运输在是否需载体、是否耗能、运输方向三方面的异同。","a":"①简单扩散：不需载体，不耗能，顺浓度梯度（高→低），如O2、CO2、疏水小分子直接穿过脂双层。②协助扩散：需载体或通道蛋白，不耗能，顺浓度梯度，如葡萄糖经GLUT、水经水通道、离子经通道。③主动运输：需载体蛋白，耗能（ATP、离子梯度或光能），逆浓度梯度（低→高），如Na+/K+泵、小肠上皮SGLT。三者共同点：都是跨膜运输；协助扩散与主动运输都需膜蛋白。","kps":"简单扩散:无载体不耗能顺梯度;协助扩散:有蛋白不耗能顺梯度;主动运输:有载体耗能逆梯度;共同:跨膜/膜蛋白","type":"比较型","kp":"ch02_s1_1"}],"calc":[{"id":"ch02_calc_1","modI":0,"q":"论述生物膜的不对称性及其生物学意义。","a":"膜脂和膜蛋白的不对称分布是生物膜的基本特征,具有重要功能意义","steps":"【不对称性的表现】\n①膜脂：磷脂、糖脂分布完全不对称——糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布在两侧；同一种膜脂两侧比例不同。\n②膜蛋白：分布不对称——如肠上皮细胞顶端面与基底面的转运蛋白不同(protein A、B)。\n③糖类：糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。\n\n【生物学意义】\n①决定细胞极性——上皮细胞顶端与基底面功能不同(吸收vs转运)；\n②细胞识别与免疫——糖基位于外侧，血型抗原(A/B/AB/O)由膜糖脂/糖蛋白决定；\n③信号转导——受体、G蛋白等不对称分布，保证信号方向性；\n④物质运输——载体/通道蛋白定向分布，实现跨细胞转运(如小肠吸收葡萄糖)；\n⑤细胞融合、分裂、运动的基础。\n\n【结论】不对称性与流动性共同构成生物膜的两大特征，是膜功能多样性的分子基础。","kp":"ch02_s0_11","kps":"表现:糖脂糖蛋白糖基在外、胆固醇均分、膜蛋白不对称;意义:细胞极性、识别与血型、信号方向、定向运输、融合分裂运动基础"},{"id":"ch02_calc_2","modI":1,"q":"论述跨膜运输的主要方式及其机制。","a":"跨膜运输分为被动运输和主动运输两大类,机制各异","steps":"【被动运输】(顺浓度梯度，不耗能)\n①简单扩散：疏水小分子(O2/CO2/激素)直接穿过脂双层；\n②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT、水经AQP、离子经通道。\n• 通道蛋白：形成亲水通道，不与底物结合，速率最快，电压/配体/应力门控；\n• 载体蛋白：构象变化转运，如GLUT1、ADP/ATP载体。\n\n【主动运输】(逆浓度梯度，耗能，需载体)\n①ATP驱动泵：Na+/K+-ATPase(3Na+出/2K+入)、Ca2+泵、H+泵(植物)；\n②离子梯度驱动(协同运输)：同向(symport,如葡萄糖-Na+)、反向(antiport)；\n③光能驱动：细菌视紫红质。\n\n【实例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运；基底Glut2协助扩散。\n\n【意义】\n①被动运输实现顺梯度的快速交换；\n②主动运输维持离子梯度、膜电位、渗透平衡、pH稳态，是细胞生存的基础。","kp":"ch02_s1_1","kps":"被动:简单扩散、协助扩散(通道/载体);主动:ATP泵(Na+/K+3出2进)、离子梯度协同(同向/反向)、光能;实例:小肠SGLT+Glut2;意义:梯度/电位/渗透/pH"},{"id":"ch02_calc_3","modI":0,"q":"论述膜流动性及其影响因素和生物学意义。","a":"膜流动性是生物膜的基本特征,由多种因素调节,是生命活动的必要条件","steps":"【流动性的表现】\n膜脂：侧向运动(基本)、翻转运动(慢)、尾部摆动、绕轴自旋；膜蛋白：侧向扩散。\n\n【影响因素】\n①温度(最主要)：温度高流动性大；降至相变温度以下，膜脂由液晶态→凝胶态；\n②脂肪酸链长度：短链含量高→流动性高；\n③不饱和程度：不饱和脂肪酸(双键多)使分子弯曲、排列疏松→流动性高；饱和脂肪酸排列紧密→流动性低；\n④胆固醇：双向调节——相变温度以上减弱脂肪酸链运动、降低流动性；以下阻止紧密排列、防止凝固；\n⑤膜蛋白与骨架的限制。\n\n【研究方法】FRAP(荧光漂白恢复)测定扩散速率。\n\n【生物学意义】\n①物质运输：膜融合、胞吞胞吐；\n②信号转导：受体聚集、脂筏动态；\n③细胞运动、分裂、融合；\n④膜蛋白功能发挥。\n\n【结论】膜流动性使细胞能进行各种生命活动，是细胞生存的必要条件。","kp":"ch02_s0_30","kps":"表现:侧向/翻转/摆动/自旋、蛋白侧向扩散;因素:温度、链长、不饱和、胆固醇双向、蛋白骨架;FRAP;意义:运输/信号/运动分裂融合"},{"id":"ch02_calc_x2","modI":1,"q":"以小肠上皮细胞吸收葡萄糖为例，说明协同运输的分子机制及其与Na+/K+泵的偶联关系。","a":"①小肠上皮细胞顶端面存在Na+驱动的葡萄糖同向转运体（SGLT），将Na+顺浓度梯度内流所释放的能量用于将葡萄糖逆浓度梯度转入细胞，属协同运输（同向运输）。②细胞内Na+浓度必须维持低水平，才能保持Na+内流的驱动力；这由基底侧面的Na+/K+泵（Na+/K+-ATPase）水解ATP、将3个Na+泵出、2个K+泵入实现。③葡萄糖在细胞内积累后，经基底面的Glut2顺浓度梯度协助扩散进入血液。④因此，SGLT的继发性主动运输与Na+/K+泵的初级主动运输偶联：泵消耗ATP建立Na+梯度，SGLT利用该梯度转运葡萄糖。","kps":"顶端SGLT同向转运;Na+顺梯度驱动葡萄糖逆梯度;基底Na+/K+泵维持Na+低浓度(耗ATP);Glut2出细胞;偶联:泵建梯度→载体利用梯度","type":"机制型","kp":"ch02_s1_30"},{"id":"ch02_calc_x3","modI":0,"q":"设计实验判断某种膜蛋白属于整合蛋白还是外周膜蛋白，并说明相应的提取方法。","a":"思路：依据两类膜蛋白与膜结合方式不同，采用不同强度的提取条件并检测。①用高盐溶液或碱性溶液（如0.1mol/L Na2CO3）处理膜：外周膜蛋白依靠非共价键附着于膜表面，可被高盐/碱洗脱下来；整合膜蛋白嵌入脂双层，不被洗脱。②用去垢剂（如SDS、Triton X-100）处理膜：整合膜蛋白可被去垢剂溶解提取。③检测：离心分离后对沉淀与上清进行SDS-PAGE或免疫印迹，用该蛋白特异抗体检测。预期：若该蛋白可被高盐/碱洗脱、不需去垢剂，则为外周膜蛋白；若只在去垢剂处理后才被提取，则为整合膜蛋白。","kps":"高盐/碱洗脱→外周蛋白;去垢剂→整合蛋白;离心分离;SDS-PAGE/免疫印迹检测;预期判定","type":"实验设计型","kp":"ch02_s0_25"}],"term":[{"id":"ch02_term_1","modI":0,"term":"流动镶嵌模型(Fluid Mosaic Model)","def":"①1972年Singer和Nicolson提出的生物膜结构模型（定义）。②内容：磷脂双分子层为基本骨架；膜蛋白以不同方式镶嵌其中；膜脂和膜蛋白具流动性；分布具不对称性（内容）。③意义：解释膜的多种性质(运输、信号、融合)，是膜生物学的里程碑（意义）。","kps":"踩分点:①提出者年份(1分)②内容(2分)③意义(1分)","kp":"ch02_s0_2"},{"id":"ch02_term_2","modI":0,"term":"脂筏(Lipid Raft)","def":"①膜上胆固醇、鞘磷脂等富集形成的相对独立的微区域(1988提出)（定义）。②特点：异质性、高度动态、分子排列较紧密（特点）。③组成：含250多种蛋白；非离子去垢剂(如Triton X-100)可分离（组成）。④功能：参与细胞信息传递、物质运输等（功能）。","kps":"踩分点:①定义(1分)②特点(1分)③组成(1分)④功能(1分)","kp":"ch02_s0_4"},{"id":"ch02_term_3","modI":0,"term":"膜脂的不对称性（Membrane lipid asymmetry）","def":"①同一种膜脂在脂双层两侧分布比例不同、呈不对称分布的现象（定义）。②表现：磷脂、糖脂分布完全不对称，糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布（表现）。③意义：决定细胞极性、细胞识别(血型抗原)、信号转导方向性（意义）。","kps":"踩分点:①定义(1分)②表现(2分)③意义(1分)","kp":"ch02_s0_11"},{"id":"ch02_term_4","modI":0,"term":"膜流动性(Membrane Fluidity)","def":"①膜脂和膜蛋白在膜内运动的能力（定义）。②膜脂运动方式：侧向运动(基本)、翻转、尾部摆动、自旋（方式）。③影响因素：温度(最主要)、脂肪酸链长度、不饱和程度、胆固醇（因素）。④意义：是细胞进行物质运输、信号转导、融合、分裂等生命活动的必要条件（意义）。","kps":"踩分点:①定义(1分)②运动方式(1分)③影响因素(1分)④意义(1分)","kp":"ch02_s0_13"},{"id":"ch02_term_5","modI":0,"term":"膜内在蛋白(Integral Protein)","def":"①与膜脂疏水区紧密结合、需去垢剂才能溶解的膜蛋白（定义）。②跨膜方式：α-螺旋或β-折叠（方式）。③举例：跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白（举例）。④分离：需离子型/非离子型去垢剂溶解（分离）。","kps":"踩分点:①定义(1分)②跨膜方式(1分)③举例(1分)④分离(1分)","kp":"ch02_s0_21"},{"id":"ch02_term_6","modI":0,"term":"外周膜蛋白(Peripheral Protein)","def":"①以非共价键结合在膜脂极性头部或内在蛋白上的膜蛋白（定义）。②特点：不插入脂双层疏水区（特点）。③举例：红细胞膜骨架的血影蛋白、肌动蛋白（举例）。④分离：高盐、改变pH或离子强度可洗脱（分离）。","kps":"踩分点:①定义(1分)②特点(1分)③举例(1分)④分离(1分)","kp":"ch02_s0_23"},{"id":"ch02_term_7","modI":0,"term":"脂锚定蛋白（Lipid-anchored protein）","def":"①与膜脂特定脂类以共价键连接于膜上的膜蛋白（定义）。②特点：位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放（特点）。③举例：小G蛋白(Ras等)（举例）。","kps":"踩分点:①定义(1分)②特点(2分)③举例(1分)","kp":"ch02_s0_24"},{"id":"ch02_term_8","modI":0,"term":"脂质体(Liposome)","def":"①人工把纯磷脂/磷脂酰胆碱加入水中自我装配形成的封闭球形小泡，直径25nm-1mm（定义）。②结构：脂双层包围水相（结构）。③应用：生物膜研究模型、膜蛋白研究、药物靶向递送载体（应用）。","kps":"踩分点:①定义(1分)②结构(1分)③应用(2分)","kp":"ch02_s0_16"},{"id":"ch02_term_9","modI":0,"term":"去垢剂(Detergent)","def":"①能溶解膜蛋白的两亲性物质（定义）。②分类：离子型(如SDS)——破坏非共价键、可能变性；非离子型(如Triton X-100)——温和、保持活性（分类）。③用途：溶解膜内在蛋白、分离纯化膜蛋白（用途）。","kps":"踩分点:①定义(1分)②分类(2分)③用途(1分)","kp":"ch02_s0_20"},{"id":"ch02_term_10","modI":1,"term":"被动运输(Passive Transport)","def":"①顺浓度梯度、不消耗能量的跨膜运输（定义）。②类型：简单扩散(不需载体，如O2/CO2)、协助扩散(需载体/通道蛋白，如葡萄糖经GLUT)（类型）。③特点：顺浓度梯度、不耗能（特点）。","kps":"踩分点:①定义(1分)②类型(2分)③特点(1分)","kp":"ch02_s1_1"},{"id":"ch02_term_11","modI":1,"term":"主动运输(Active Transport)","def":"①逆浓度梯度、需消耗能量、需载体蛋白的跨膜运输（定义）。②三种动力：ATP驱动泵、离子梯度驱动(协同运输)、光能驱动（动力）。③举例：Na+/K+-ATPase、Ca2+泵、葡萄糖-Na+同向转运（举例）。④意义：维持离子梯度、膜电位、渗透平衡、pH稳态（意义）。","kps":"踩分点:①定义(1分)②三种动力(1分)③举例(1分)④意义(1分)","kp":"ch02_s1_17"},{"id":"ch02_term_12","modI":1,"term":"Na+/K+-ATPase(Na+/K+泵)","def":"①动物细胞质膜上逆浓度梯度泵出Na+、泵入K+的离子泵（定义）。②结构：2α+2β亚基（结构）。③机制：每水解1个ATP，泵出3Na+、泵入2K+（机制）。④作用：建立膜电位、维持渗透平衡和pH稳态、为协同运输供能（作用）。","kps":"踩分点:①定义(1分)②结构(1分)③机制(1分)④作用(1分)","kp":"ch02_s1_20"},{"id":"ch02_term_13","modI":1,"term":"水通道蛋白(Aquaporin)","def":"①介导水快速跨膜运输的通道蛋白（定义）。②结构：4个相同亚基组成四聚体，每亚基6个跨膜α螺旋（结构）。③选择性：通道直径0.28nm，中心带正电荷(Arg/His)排斥阳离子（选择性）。④意义：发现获2003年诺贝尔化学奖(Peter Agre)（意义）。","kps":"踩分点:①定义(1分)②结构(1分)③选择性(1分)④诺贝尔奖(1分)","kp":"ch02_s1_14"},{"id":"ch02_term_14","modI":1,"term":"协同运输(Cotransport)","def":"①由离子泵建立的离子梯度驱动、经载体蛋白逆浓度转运物质的主动运输（定义）。②类型：同向协同运输(symport，如葡萄糖-Na+)、反向协同运输(antiport)（类型）。③动力：膜两侧离子的电化学梯度（动力）。④举例：小肠上皮细胞顶端SGLT吸收葡萄糖（举例）。","kps":"踩分点:①定义(1分)②类型(1分)③动力(1分)④举例(1分)","kp":"ch02_s1_27"},{"id":"ch02_term_15","modI":1,"term":"膜电位(Membrane Potential)","def":"①细胞膜两侧的电位差，由膜两侧离子分布不均产生（定义）。②产生：Na+/K+泵建立K+浓度梯度，静息时质膜对K+通透性大于Na+→K+外流（机制）。③意义：可兴奋细胞(神经/肌肉)信号传递的基础；动作电位是膜电位去极化/超极化的结果（意义）。","kps":"踩分点:①定义(1分)②产生机制(2分)③意义(1分)","kp":"ch02_s1_21"}],"preview":{"main":"本章围绕细胞质膜的结构与功能展开，先讲膜的化学组成（膜脂、膜蛋白）和流动镶嵌模型、脂筏模型等结构理论，再讲膜如何通过被动运输、主动运输和协同运输实现物质跨膜转运。它是理解细胞与外界物质交换、信号传递、能量代谢以及神经电活动（静息电位、动作电位）的基础。","questions":["流动镶嵌模型和脂筏模型分别如何描述膜的结构？脂筏与普通膜区域有什么不同？","膜脂有哪三种主要类型？它们的两性分子特性如何自发形成脂双层？膜脂的不对称性和运动性体现在哪些方面？","膜蛋白有哪几类（内在跨膜整合蛋白、外周膜蛋白、脂锚定蛋白）？去垢剂在膜蛋白研究中起什么作用？","被动运输与主动运输有何区别？通道蛋白和载体蛋白在协助扩散中分别如何工作？","Na+/K+泵的结构和工作机制是什么？它如何维持静息电位并驱动葡萄糖的协同运输？","K+通道的选择性滤器如何实现对K+的选择性通透？水通道又是如何选择水分子的？"]},"appcards":[{"front":"简述生物膜流动镶嵌模型的主要内容。","back":"流动镶嵌模型(1972, Singer & Nicolson)主要内容：\n\n①磷脂双分子层是生物膜的基本结构组分——磷脂具有极性头部(亲水)和非极性尾部(疏水)，在水溶液中自动装配成脂双层；\n②膜蛋白以不同方式镶嵌于脂双层：内在蛋白(跨膜)、外周蛋白(非共价结合)、脂锚定蛋白(共价连接)；\n③膜脂和膜蛋白具有流动性——膜脂可侧向运动、翻转、摆动、自旋；膜蛋白可侧向扩散；\n④膜脂和膜蛋白分布具有不对称性——糖脂/糖蛋白的糖基位于质膜外侧；\n⑤脂类与蛋白质的流动性和不对称性是它们相互作用及与其他生物大分子相互作用的基础；\n⑥这种相互作用又一定程度上限制了膜蛋白和膜脂的流动性。\n\n【发展】此后提出脂筏模型(1988)：膜上胆固醇、鞘磷脂富集形成相对独立的微区域。\n【意义】解释了膜的许多性质：物质运输、信号转导、细胞融合等。","points":"","mod":0,"modName":"模块一：生物膜结构模型与组成","level":"掌握","src":"题库"},{"front":"简述膜脂的种类、特性及其对膜流动性的影响。","back":"膜脂分三大类：\n①甘油磷脂(占膜脂50%以上)：磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇；\n②鞘脂：鞘氨醇衍生物，分鞘磷脂、鞘糖脂，主要在高尔基体合成；\n③胆固醇：4环碳氢化合物，自身不能形成脂双层，插入磷脂之间。\n都是两性分子(亲水头+疏水尾)。\n\n膜脂特性：\n①不对称性——磷脂、糖脂分布完全不对称，糖脂位于胞外侧，胆固醇均等分布；\n②流动性——侧向运动(基本)、翻转、尾部摆动、自旋。\n\n影响膜流动性的因素：\n①温度(最主要)——温度高流动性大，降至相变温度以下变凝胶态；\n②脂肪酸链长度——短链流动性高；\n③不饱和程度——不饱和度高(双键多)流动性高；\n④胆固醇——双向调节(相变温度以上降低流动性、以下防止凝固)。","points":"","mod":0,"modName":"模块一：生物膜结构模型与组成","level":"掌握","src":"题库"},{"front":"简述膜蛋白的类型及分离方法。","back":"膜蛋白类型(按与膜结合方式)：\n\n①膜内在蛋白/跨膜蛋白(intrinsic/integral)：以α-螺旋或β-折叠跨膜，如跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白。\n②外周膜蛋白(peripheral)：以非共价键结合在膜脂极性头部或内在蛋白上，如红细胞膜骨架的血影蛋白、肌动蛋白。\n③脂锚定蛋白：与膜脂特定脂类共价连接，虽位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放，如小G蛋白。\n\n分离方法：\n①外周蛋白——高盐、改变pH或离子强度可洗脱；\n②内在蛋白——需去垢剂(离子型如SDS，非离子型如Triton X-100)溶解；\n③脂锚定蛋白——需特定酶释放。\n\n去垢剂：离子型(SDS)破坏非共价键、可能变性；非离子型(Triton X-100)温和、保持活性。","points":"","mod":0,"modName":"模块一：生物膜结构模型与组成","level":"掌握","src":"题库"},{"front":"简述Na+/K+-ATPase的结构、机制及生理作用。","back":"结构：2个α亚基+2个β亚基。α亚基具ATP酶活性、与Na+结合。\n\n机制：每水解1个ATP，将细胞内3个Na+泵出细胞外，同时输入2个K+。α亚基与Na+结合促进ATP水解→磷酸化→构象变化→Na+泵出、K+泵入。\n\n生理作用：\n①建立并维持膜两侧离子浓度梯度(胞内高K+、低Na+)；\n②建立细胞膜电位(membrane potential)，特别是神经和肌肉等可兴奋细胞，是信号传递的基础；\n③维持渗透平衡——泵出Na+，胞外高Na+、Cl-帮助维持膜内外渗透压平衡；\n④维持细胞质基质pH稳态；\n⑤为协同运输提供驱动力(如葡萄糖-Na+同向转运)。\n\n【诺贝尔奖】Na+/K+-ATPase研究获诺贝尔奖。若泵停止工作，细胞吸水膨胀破裂。","points":"","mod":1,"modName":"模块二：跨膜运输","level":"掌握","src":"题库"},{"front":"比较被动运输与主动运输,并举例说明。","back":"被动运输 vs 主动运输：\n\n【被动运输】\n• 顺浓度梯度，不消耗能量；\n• ①简单扩散：不需载体，如O2、CO2、N2、激素等疏水小分子；\n• ②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT进入细胞、离子经通道蛋白；\n• 通道蛋白只参与被动运输，转运速率最快(电压/配体/应力门控)。\n\n【主动运输】\n• 逆浓度梯度，需消耗能量(ATP/光能/离子梯度)，需载体蛋白；\n• 三种动力方式：ATP驱动泵(Na+/K+-ATPase、Ca2+泵)、离子梯度驱动(协同运输)、光能驱动；\n• 同向协同运输(symport)如葡萄糖-Na+同向转运；反向协同运输(antiport)。\n\n【例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运(继发性主动运输)，基底Glut2协助扩散入血。\n\n【比较】被动运输不需能量、顺梯度；主动运输需能量、逆梯度。","points":"","mod":1,"modName":"模块二：跨膜运输","level":"掌握","src":"题库"},{"front":"简述静息电位的产生机制及K+通道的选择性原理。","back":"【静息电位的产生】\n①Na+/K+泵产生K+浓度梯度(胞内高K+)；\n②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因；\n③K+经K+泄漏通道外流，使膜外带正电、膜内带负电，形成膜电位；\n④膜电位由接近膜的一薄层(<1nm)离子产生。\n静息神经元中K+泄漏通道开放，而数量更多的门控通道关闭。\n\n【K+通道的选择性原理】\n①所有K+通道都有选择性滤器；\n②K+去水化(dehydration)需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿；\n③Na+离子半径小、去水化能量高，不能与滤器结合补偿，故被排斥；\n④结果：K+通道只允许K+通过。\n\n【动作电位】细胞受刺激时膜电位去极化或超极化，形成动作电位，是神经信号传导的基础。","points":"","mod":1,"modName":"模块二：跨膜运输","level":"掌握","src":"题库"},{"front":"论述生物膜的不对称性及其生物学意义。","back":"【不对称性的表现】\n①膜脂：磷脂、糖脂分布完全不对称——糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布在两侧；同一种膜脂两侧比例不同。\n②膜蛋白：分布不对称——如肠上皮细胞顶端面与基底面的转运蛋白不同(protein A、B)。\n③糖类：糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。\n\n【生物学意义】\n①决定细胞极性——上皮细胞顶端与基底面功能不同(吸收vs转运)；\n②细胞识别与免疫——糖基位于外侧，血型抗原(A/B/AB/O)由膜糖脂/糖蛋白决定；\n③信号转导——受体、G蛋白等不对称分布，保证信号方向性；\n④物质运输——载体/通道蛋白定向分布，实现跨细胞转运(如小肠吸收葡萄糖)；\n⑤细胞融合、分裂、运动的基础。\n\n【结论】不对称性与流动性共同构成生物膜的两大特征，是膜功能多样性的分子基础。","points":"","mod":0,"modName":"模块一：生物膜结构模型与组成","level":"掌握","src":"题库"},{"front":"论述跨膜运输的主要方式及其机制。","back":"【被动运输】(顺浓度梯度，不耗能)\n①简单扩散：疏水小分子(O2/CO2/激素)直接穿过脂双层；\n②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT、水经AQP、离子经通道。\n• 通道蛋白：形成亲水通道，不与底物结合，速率最快，电压/配体/应力门控；\n• 载体蛋白：构象变化转运，如GLUT1、ADP/ATP载体。\n\n【主动运输】(逆浓度梯度，耗能，需载体)\n①ATP驱动泵：Na+/K+-ATPase(3Na+出/2K+入)、Ca2+泵、H+泵(植物)；\n②离子梯度驱动(协同运输)：同向(symport,如葡萄糖-Na+)、反向(antiport)；\n③光能驱动：细菌视紫红质。\n\n【实例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运；基底Glut2协助扩散。\n\n【意义】\n①被动运输实现顺梯度的快速交换；\n②主动运输维持离子梯度、膜电位、渗透平衡、pH稳态，是细胞生存的基础。","points":"","mod":1,"modName":"模块二：跨膜运输","level":"掌握","src":"题库"},{"front":"论述膜流动性及其影响因素和生物学意义。","back":"【流动性的表现】\n膜脂：侧向运动(基本)、翻转运动(慢)、尾部摆动、绕轴自旋；膜蛋白：侧向扩散。\n\n【影响因素】\n①温度(最主要)：温度高流动性大；降至相变温度以下，膜脂由液晶态→凝胶态；\n②脂肪酸链长度：短链含量高→流动性高；\n③不饱和程度：不饱和脂肪酸(双键多)使分子弯曲、排列疏松→流动性高；饱和脂肪酸排列紧密→流动性低；\n④胆固醇：双向调节——相变温度以上减弱脂肪酸链运动、降低流动性；以下阻止紧密排列、防止凝固；\n⑤膜蛋白与骨架的限制。\n\n【研究方法】FRAP(荧光漂白恢复)测定扩散速率。\n\n【生物学意义】\n①物质运输：膜融合、胞吞胞吐；\n②信号转导：受体聚集、脂筏动态；\n③细胞运动、分裂、融合；\n④膜蛋白功能发挥。\n\n【结论】膜流动性使细胞能进行各种生命活动，是细胞生存的必要条件。","points":"","mod":0,"modName":"模块一：生物膜结构模型与组成","level":"掌握","src":"题库"},{"front":"细胞质膜与细胞内膜系统在进化上的意义有何不同？","back":"质膜形成是非细胞生命(病毒)与细胞生物的重要分界点；细胞内膜系统的发展是细胞生物由低等到高等发展的反映；生物膜=质膜+细胞内膜系统。","points":"质膜分界点；内膜系统进化标志；生物膜组成","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说质膜是细胞与外界环境的边界与交流界面？","back":"质膜作为屏障和半透膜维护细胞内微环境相对稳定；同时介导细胞与外界进行物质、能量、信息交换；因此既是边界又是交流界面。","points":"屏障半透膜；微环境稳定；物质能量信息交换","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"流动镶嵌模型与脂筏模型有何异同？","back":"相同：都认为磷脂双分子层为基本结构，蛋白与脂类相互作用；不同：流动镶嵌强调脂和蛋白流动性与不对称性；脂筏模型强调胆固醇、鞘磷脂富集形成相对独立功能区域，承载特定膜蛋白。","points":"磷脂双分子层；流动性不对称性；脂筏富集区；功能膜蛋白","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么膜脂都是两性分子？这一性质有何意义？","back":"膜脂同时具有亲水头部和疏水尾部；在水溶液中可自发装配成脂双层；疏水尾埋在内侧、头部朝向水；这是形成脂双层和生物膜的基础。","points":"亲水头；疏水尾；自装配；脂双层基础","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较甘油磷脂与鞘磷脂在结构和合成部位上的异同。","back":"相同：均为两性分子，具极性头部和非极性尾部，参与膜脂双层；不同：甘油磷脂以甘油为骨架，占膜脂50%以上；鞘磷脂以鞘氨醇为骨架，主要在高尔基体合成。","points":"两性分子；甘油骨架；鞘氨醇骨架；高尔基体合成","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"胆固醇为什么不能自身形成脂双层？它在膜中如何存在？","back":"胆固醇含4个闭环碳氢化合物，亲水头部仅一个羟基；自身不能形成脂双层；只能插入磷脂分子之间参与生物膜形成；并调节流动性、增加稳定性。","points":"一个羟基；不能成双层；插入磷脂间；调节流动性","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"膜脂的不对称性表现在哪些方面？有何意义？","back":"磷脂、糖脂分布完全不对称，糖脂位于细胞外侧；胆固醇几乎均等分布两侧；糖蛋白和糖脂糖基均位于质膜外侧；意义：保证膜两侧功能差异，参与识别、信号转导等。","points":"糖脂外侧；胆固醇均等；糖基外侧；功能差异","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"膜脂的流动性通过哪些运动方式实现？","back":"同一侧侧向运动为基本方式；双层分子间翻转运动较慢；尾部摆动；绕轴心自旋；这些运动赋予膜流动性，使膜能变形、融合、分裂。","points":"侧向运动；翻转运动；尾部摆动；自旋；膜可塑性","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么膜脂在水溶液中能自动形成连续不破裂的脂双层？","back":"膜脂为两性分子，疏水尾部不带电荷、无极性、不能与水形成氢键；暴露水中能量上不利；因此自发把尾部埋在内侧、头部朝向水；形成连续不破裂结构。","points":"两性分子；疏水尾不利暴露；自发装配；连续结构","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"脂质体在膜研究中有何作用？如何形成？","back":"将纯磷脂/磷脂酰胆碱加入水中可自我装配形成封闭球形小泡，直径25nm-1mm；电镜可显示脂双层结构；是研究膜的良好模型。","points":"纯磷脂加水；封闭小泡；脂双层；膜研究模型","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"膜脂的功能有哪些？是否参与生化生理功能？","back":"构成膜的基本骨架；为膜蛋白执行功能提供场所；蛋白通过疏水端与膜脂作用镶嵌于膜上；一般情况下膜脂本身不参与生化生理功能，但有些如PI参与信号转导。","points":"基本骨架；蛋白功能场所；一般不参与；PI信号转导","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"膜内在蛋白、外周膜蛋白和脂锚定蛋白在结合方式上有何异同？","back":"膜内在蛋白以α-螺旋或β-折叠跨膜；外周膜蛋白以非共价键结合在膜脂极性头部或内在蛋白上；脂锚定蛋白与特定脂类共价连接，需特定酶才能释放。","points":"跨膜；非共价结合；共价脂连接；释放方式不同","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说生物膜的特定功能主要由蛋白质决定？","back":"膜蛋白种类和数量决定膜功能复杂性；功能越复杂的膜，膜蛋白种类越多；膜蛋白作为受体、通道、载体、酶等执行特定功能；膜脂主要构成骨架。","points":"蛋白决定功能；复杂膜蛋白多；受体通道载体酶；脂为骨架","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"离子型去垢剂与非离子型去垢剂在溶解膜蛋白时有何不同？","back":"离子型如SDS高浓度可破坏蛋白质离子键和氢键等非共价键，甚至改变亲水部分构象；非离子型如Triton X-100较温和，可溶解膜蛋白并保持活性；Triton X-100可用于分离脂筏。","points":"SDS破坏非共价键；Triton温和保活；分离脂筏","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"限制膜蛋白侧向运动的因素有哪些？举例说明。","back":"胞内骨架成分限制；细胞外基质分子限制；其他扩散屏障如紧密连接；膜蛋白与其他膜蛋白或脂筏结合；例如红细胞膜骨架蛋白限制膜蛋白运动。","points":"胞内骨架；胞外基质；紧密连接；蛋白/脂筏结合","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"FRAP技术如何研究膜的流动性？","back":"用荧光标记膜蛋白或膜脂；激光漂白局部区域；观察荧光恢复速度；测定膜分子扩散速率；是研究膜流动性的经典方法。","points":"荧光标记；激光漂白；荧光恢复；扩散速率","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"温度如何影响膜流动性？什么是相变温度？","back":"温度是最主要影响因素；37℃以上膜脂相对流动的液态；温度降低到某一点时，膜脂由液晶态转变为凝胶态，该点即相变温度Tm；温度越高流动性越大。","points":"温度主要因素；液晶态；凝胶态；相变温度","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"脂肪酸链长度和不饱和度如何影响膜流动性？","back":"短链脂肪酸含量丰富，膜流动性高；不饱和度高即双键多，脂肪酸链弯曲、排列疏松，流动性高；饱和脂肪酸无双键，排列紧密，室温下固态。","points":"短链流动性高；不饱和度高流动性高；饱和排列紧密","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"胆固醇为什么被称为膜流动性的缓冲器？","back":"相变温度以上，胆固醇使磷脂脂肪酸链运动性减弱，降低流动性；相变温度以下，阻止脂肪酸链紧密排列，防止膜凝固；因此随温度不同双向调节。","points":"高温降低流动性；低温防止凝固；双向调节","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"人工脂双层对不同分子的通透性有何规律？","back":"疏水分子如O2、CO2、N2、激素易通过；小的不带电极性分子如水、尿素、甘油较易通过；大的不带电极性分子如葡萄糖难通过；离子最难通过。","points":"疏水易过；小极性较易；大极性难；离子最难","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"简单扩散与协助扩散有何异同？","back":"相同：均为被动运输，顺浓度梯度，不耗能；不同：简单扩散不需载体，如O2、CO2；协助扩散需载体或通道蛋白，如GLUT转运葡萄糖。","points":"被动顺梯度；不耗能；简单无载体；协助需载体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"通道蛋白与载体蛋白在运输机制上有何不同？","back":"通道蛋白在膜上形成跨膜亲水通道，离子通过时不需与运输分子结合，只参与被动运输，转运速率最快；载体蛋白通过构象变化运输，可参与被动或主动运输。","points":"通道形成亲水孔；不结合底物；被动运输；载体构象变化","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"水通道AQP1的发现实验如何证明其功能？","back":"将AQP1的mRNA注入非洲爪蟾卵母细胞；在低渗溶液中卵母细胞迅速膨胀并于5分钟内破裂；对照细胞不破裂；证明AQP1是水通道。","points":"AQP1 mRNA；爪蟾卵母细胞；低渗膨胀破裂；证明水通道","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"水通道为什么只允许水通过而不允许离子通过？","back":"通道直径只有0.28nm，无法通过比水分子大的物质；通道中心最窄处带正电荷，如Arg-195、His-180，排斥阳离子如H3O+；因此只允许水通过。","points":"直径0.28nm；最窄处正电荷；排斥阳离子；只过水","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"Na+/K+泵每水解一个ATP如何转运离子？其结构基础是什么？","back":"每水解一个ATP将细胞内3个Na+泵出，同时输入2个K+；Na+/K+-ATPase由2个α亚基和2个β亚基组成；α亚基与Na+结合促进ATP水解，构象变化将Na+泵出、K+泵入。","points":"3Na+出；2K+入；α2β2；构象变化","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若动物细胞Na+/K+泵被抑制，细胞会发生什么？为什么？","back":"胞内Na+升高、K+降低；膜电位难以维持；渗透平衡破坏，细胞吸水膨胀甚至破裂；pH稳态和协同运输驱动力也受影响；因为Na+/K+泵持续工作维持离子梯度和渗透平衡。","points":"离子梯度破坏；膜电位丧失；吸水膨胀破裂；渗透平衡","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"小肠上皮细胞如何实现葡萄糖从肠腔到血液的逆浓度吸收？","back":"顶端表面SGLT由Na+驱动进行葡萄糖同向主动运输，使细胞内葡萄糖浓度升高；基底面GLUT2通过协助扩散将葡萄糖运入血液；两步实现逆浓度吸收。","points":"SGLT顶端；Na+驱动同向运输；GLUT2基底面；协助扩散入血","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"动物细胞与植物细胞在主动运输离子泵上有何异同？","back":"相同：均通过离子泵建立电化学梯度，驱动协同运输；不同：动物细胞质膜主要是Na+/K+泵，泵出Na+、泵入K+；植物、细菌、真菌质膜上主要是H+泵，泵出H+建立质子梯度。","points":"均建梯度；动物Na+/K+泵；植物H+泵；驱动协同运输","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}],"jyq":[{"id":"jyq_ch02_1","kind":"fill","q":"维持蛋白质结构稳定的两种共价键是,非共价键是。","a":"肽键和二硫键；离子键、氢键、疏水作用力、范德华力。","src":"河北师范大学，2001年","kp":null,"e":"维持蛋白质结构的键分共价键与非共价键两类：肽键、二硫键为共价键，离子键、氢键、疏水作用力和范德华力为非共价键。","oe":["肽键和二硫键：肽键连接氨基酸残基构成一级结构，二硫键共价交联稳定空间结构，二者均为共价键。","离子键、氢键、疏水作用力、范德华力：均为非共价键，协同维持蛋白质的空间构象（高级结构）。"]},{"id":"jyq_ch02_2","kind":"short","q":"怎样理解“病毒是非细胞形态的生命体”，请比较病毒与细胞的区别并讨论其相互的关系。","a":"容细胞虽然是地球上主要的生命形式，但并非是唯一的生命形式；病毒也是生命体，但它不具细胞结构，是比细胞更小的生命体。病毒是19世纪末通过对疾病的研究发现的。病毒没有细胞结构，不能在体外独立生活，只能在活细胞中进行增殖。病毒的增殖可分为5个基本过程：①吸附；②侵人；③复制；④成熟；5释放。病毒与细胞的区别：①病毒很小，结构及其简单；②遗传载体的多样性；③彻底的寄生性；④病毒是以复制和装配的方式进行增殖。病毒虽然是非细胞形态的生命体，但它们必须在细胞内才能表现基本的生命特征（繁殖与遗传）。①病毒是专性寄生，生存离不开细胞；②病毒的复制必须在细胞内进行；③在进化上，病毒是细胞的进化产物。因此，病毒可能是细胞在特定条件下“扔出”的一个“病毒基因组”，或者是具有复制与转录能力的mRNA。这些游离的基因组，只有回到它们原来的细胞内环境中才能进行复制与转录。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_3","kind":"mcq","q":"制备单克隆抗体是通过下列（）技术构建的。","o":["A. 细胞融合","B. 核移植","C. 病毒转化","D. 基因转移"],"a":"A","src":"南开大学，2009年","kp":null,"e":"单克隆抗体通过B淋巴细胞与骨髓瘤细胞融合成杂交瘤细胞制备，既能分泌特异性抗体又能无限增殖。","oe":["正确：细胞融合构建杂交瘤，兼具分泌抗体和无限增殖的能力。","核移植用于克隆动物，不是制备单克隆抗体的技术。","病毒转化用于导入基因或使细胞永生化，非单抗制备途径。","基因转移用于导入外源基因，不用于常规单抗制备。"]},{"id":"jyq_ch02_4","kind":"short","q":"试述单克隆抗体的应用。","a":"单克隆抗体是高度特异性针对单一抗原决定簇的均质抗体。基于单克隆抗体的高度特异性，它在生物医学研究及临床医学的应用中显示了其重要的意义和价值。①单克隆抗体在临床诊断中的应用：单克隆抗体的最广泛的应用在于体内外诊断试剂的制造。目前利用单克隆抗体制成的免疫诊断试剂已成功地应用于传染病及肿瘤的诊断上；也应用于类风湿因子及其他自身免疫性疾病，如激素、维生素、免疫球蛋白异常的临床诊断。用同位素标记的单克隆抗体作定位显像是包括肿瘤、心血管疾病等体内诊断的有效手段之一，使用特异性单抗对肿瘤进行鉴定、诊断和定位，是临床提高诊断正确率和设计治疗方案中的重要辅助手段。②单克隆抗体在治疗中的应用：特异性单克隆抗体和肿瘤细胞表面相应抗原的结合，可能诱发抗体依赖性细胞毒而杀死肿瘤细胞；因此，抗肿瘤单克隆抗体也是肿瘤治疗的有效手段之一。单克隆抗体与药物、核素和毒素蛋白结合的分子才称为免疫毒素，其已被广泛应用于抗肿瘤、抗感染、抗多种病变的治疗研究。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch02_5","kind":"short","q":"脂膜的不对称性表现为；膜蛋白分布的不对称性表现为细胞膜蛋白的流动性可通过细胞融合和实验进行证实。","a":"同一种膜脂分子在膜的脂双层中呈不均匀分布；有的镶嵌在膜表面，有的嵌人或横跨脂双分子层；荧光抗体免疫标记。","src":"湖北大学，2007年","kp":null},{"id":"jyq_ch02_6","kind":"judge","q":"温度对膜脂的运动无明显的影响，因为各种膜脂成分的相变温度大体相同。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["温度确能影响膜脂运动，但错以为各膜脂相变温度相同，故有此说。","各种膜脂的相变温度差异较大，温度对膜脂运动影响明显，故原说法错误。"]},{"id":"jyq_ch02_7","kind":"judge","q":"脂肪酸链靠近极性头部的部分摆动较小，尾部摆动较大。","a":"对","src":"南京师范大学，2009年","kp":null,"oe":["磷脂脂肪酸链近极性头部处运动受限，越向尾部自由度越大，摆动越强。","若认为尾部处于疏水核心摆动小而判对则错，实际尾部摆动最大。"]},{"id":"jyq_ch02_8","kind":"fill","q":"甘油不会引起红细胞膜的破碎是由于其分子的特性，不会导致细胞改变。","a":"对称性；渗透压。","src":"南京师范大学，2009年","kp":null,"e":"甘油为小分子中性物质，可缓慢透过红细胞膜，因而不在膜两侧形成高的渗透压差，红细胞不发生渗透性改变和破裂。","oe":["对称性：甘油分子小、结构对称且可透过细胞膜，进入细胞后不引起膜张力剧变，故不使红细胞膜破碎。","渗透压：因甘油能进入细胞，膜内外不形成显著渗透压差，红细胞不发生渗透性肿胀破裂，故填渗透压。"]},{"id":"jyq_ch02_9","kind":"short","q":"膜蛋白与酶的动力学曲线相同，其最显著的差别是","a":"催化作用。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch02_10","kind":"short","q":"膜脂主要运动方式包括和","a":"旋转异构；左右摆动；旋转运动；侧向扩散；倒翻运动。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch02_11","kind":"fill","q":"电化学质子梯度是指膜两侧pH梯度和梯度之和。","a":"质子。","src":"中山大学，2009年","kp":null,"e":"电化学质子梯度由膜两侧的pH梯度（H+浓度差）和质子（电荷）梯度两部分组成，也称质子动势。","oe":["质子：电化学质子梯度＝pH梯度（H+浓度差）＋质子（跨膜电位/电荷）梯度，故另一项填质子。"]},{"id":"jyq_ch02_12","kind":"mcq","q":"下列所列磷脂中，哪一种在哺乳动物的质膜中含量最少（尽管其在信号转导中具有重要作用）（），请说明可能参与的信号转导途径。","o":["A. 磷脂酰胆碱","B. 磷脂酰乙醇胺","C. 磷脂酰肌醇","D. 磷脂酰丝氨酸"],"a":"C","src":"中山大学，2009年","kp":null,"e":"磷脂酰肌醇在质膜中含量最少，却可磷酸化为PIP2，经磷脂酶C水解生成IP3和DAG参与信号转导。","oe":["磷脂酰胆碱（卵磷脂）是质膜中含量最丰富的磷脂之一。","磷脂酰乙醇胺（脑磷脂）在质膜中含量较高，并非最少。","正确：磷脂酰肌醇含量最少，经PIP2→IP3/DAG途径参与信号转导。","磷脂酰丝氨酸主要分布于膜内叶，含量高于磷脂酰肌醇。"]},{"id":"jyq_ch02_13","kind":"short","q":"动物进人冬眠状态过程中，其组织中细胞膜脂的不饱和度是升高还是降低？对细胞有何意义？","a":"动物以中止生活活动的状态去越冬，称为冬眠。通常是指恒温动物季节性的非活动状态，但广义地也适用于陆生变温动物（节肢动物、陆生贝类、两栖类、爬虫类等）的越冬。为了准备冬眠，动物在体内合成大量脂肪，或者把食物贮藏在巢穴内。组织脂肪的不饱和度增高，熔点下降。体温缓慢下降，形成仅比外界温度高0.5～2.0℃的状态。心搏数、呼吸数、代谢量仅成正常状态的几十分之一。血糖也下降，血清中的Mg+增加。冬眠动物与非冬眠动物相比，以及冬眠期与非冬眠期相比，其组织的抗寒性强，特别是细胞膜的机能可在极低的温度下保持正常。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch02_14","kind":"short","q":"细胞膜的流动性如何用实验证明？请列举两种方法证明细胞膜的流动性，并说明其原理。","a":"①成帽与成斑现象：②光脱色恢复技术。","src":"华中农业大学，2009年","kp":null},{"id":"jyq_ch02_15","kind":"short","q":"从不同的环境分离到两种细菌：一种是从平均温度为40℃的温泉中中分离的，另一种是从平均温度为4℃的冷水湖中分离的。①请推测两种细菌的细胞质膜中，哪一种具有较多的不饱和脂肪酸？②哪一种细菌质膜中的脂肪酸链较长？③在27℃哪一种细菌质膜的流动性高？","a":"①从冷水湖中分离的细菌的细胞质膜具有较多的不饱和脂肪酸。②来自温泉细胞的质膜中含有较多长链脂肪酸。③在27℃，来自冷水湖细菌的膜具有较大的流动性。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch02_16","kind":"mcq","q":"将下列各项按照它们扩散通过膜双层的能力大小排序，并给出依据。","o":["A. Ca²+","B. CO2","C. 乙醇","D. 葡萄糖E.RNAF.H2O"],"a":"B","src":"中山大学，2009年","kp":null,"e":"分子扩散过脂双层的能力取决于脂溶性和分子大小，顺序为CO2>乙醇>H2O>葡萄糖>Ca2+>RNA，CO2最强。","oe":["错误：Ca2+带电荷且水合，几乎不能自由扩散过膜，能力很低。","正确：CO2是小分子非极性气体，脂溶性好，扩散过膜能力最强。","错误：乙醇脂溶性好但分子较大，过膜能力次于CO2。","错误：其中RNA为大分子完全不能过膜，葡萄糖需载体，H2O居中，均弱于CO2。"]},{"id":"jyq_ch02_17","kind":"short","q":"将一个蛙卵和一个红细胞放在纯水中，红细胞很快膨胀破裂，虽然蛙卵比红细胞大100万倍，却维持完整。请给予解释。（提示：有两种可能的原因）","a":"从生物适应的角度出发，红细胞正常存在于血浆中，而蛙卵直接产在水中。血浆的渗透压比水大，因而可以推断红细胞的渗透压比蛙卵的渗透压大。将二者放入纯水之中，红细胞会膨胀破裂而蛙卵不会。生物会采取很多方式来保护卵，其中一种就是在卵的外周包裹上一层物质防止异物的进人和入侵。蛙卵表面就可能存在一层厚厚的细胞外基质，有效减少了水的渗透进人。甚至，蛙卵可能存在一些机制主动排出多余的水分来保持其渗透压。这种设想是第二种可能的解释。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch02_18","kind":"short","q":"为什么膜蛋白能够稳定存在于磷脂双分子层中？","a":"依赖于膜蛋白质结构特征及与膜脂的相互作用两方面：结构上的特征：①有20个左右疏水性氨基酸残基组成α螺旋跨膜。②α螺旋一侧具有疏水性氨基酸残基，内侧是极性氨基酸残基，形成特异性的跨膜结构。③由10~12个疏水性氨基酸残基组成B折叠跨膜。作用力：①跨膜结构域与膜脂分子的疏水作用。②跨膜结构域两端的携带正电荷的氨基酸残基与膜磷脂极性头部，或带负电荷的氨基酸残基通过Ca+、Mg+与带负电荷的膜磷脂极性头部相互作用。③脂类修饰蛋白，依赖脂类插入膜中。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch02_19","kind":"short","q":"何谓膜内在蛋白？","a":"它以什么方式与脂双层膜相结合？容根据膜蛋白分离的难易及其与脂分子的结合方式，膜蛋白可分为膜周边蛋白（外在膜蛋白）和膜内在蛋白（整合膜蛋白）。膜内在蛋白又称为整合蛋白。为两性分子，疏水部分位于脂双层内部，亲水部分位于脂双层外部。由于存在疏水结构域，整合蛋百与膜的结合非常紧密，只有用去垢剂才能从膜上洗涤下来。多数为跨膜蛋白，也有些插人脂双层中，它与膜脂结合的主要方式有：①膜蛋白的跨膜结构域与脂双层分子的疏水核心的相互作用；②跨膜结构域两端携带正电荷的氨基酸如精氨酸、赖氨酸等与磷分子带负电的极性头形成离子键，或带负电的氨基酸残基通过Ca²、Mg+等阳离子与带负电的磷脂极性头相互作用。③某些膜蛋白在细胞质基质一侧的半胱氨酸残基上共价结合脂肪酸分子，插人脂双层分子，进一步加强膜蛋白与脂双层的结合力，还有少数蛋白与糖脂共价结合。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_20","kind":"short","q":"生物膜的基本特征是什么？","a":"这些特征与它的生理功能有什么联系？答人类对生物膜的认知比其他细胞器要晚得多，先后提出了各种生物膜模型。目前认为生物膜结构具有以下特征。①具有极性的头部和非极性尾部的脂分子在水相中具有自发形成封闭的膜系统的性质，以水性非极性尾部相对，极性头部朝向水相的磷脂双分子层是组成生物膜的基本结构成分，尚未发现在生物膜结构中组织作用的蛋白，这一结构特点，为细胞和细胞器的生理活动提供了一个相对稳定的环境，在细胞与外界，细胞器与细胞器之间有了一个界面。②蛋白分子以不同的方式镶嵌在双层分子中或结合在其表面，蛋白的类型，蛋白分布的不对称及其与分子的协同作用赋予生物膜具有的特性与功能。有利于选择的物质运输，提供细胞识别位点，为多种酶提供了结合位点，同时参与形成具有不同功能的细胞表面特征结构。③可看成是蛋白质在双层分子中的二维溶液。然而膜蛋白质与膜脂之间，膜蛋白与膜蛋白之间及其膜两侧其他生物大分子的复杂的相互作用。在不同转变上限制了膜蛋白和膜脂的流动性。这一特点保证了膜内外物质，能量与信息的传递。生物膜具有两个显著的特征，即膜的不对称性和膜的流动性。生物膜结构的不对称，保证了膜功能的方向，使膜两侧其有不同功能。有的功能只发生在膜外，有的则在内层，这些生物膜发挥作用所必不可少的。如调节细胞内外Na、K*浓度的Na*-K+ATP酶，其运转时所需的DTP是细胞内产生的，该酶的DTP结合点正是处于膜的内侧面，许多激素受体易接受细胞外信号的结构，则处于细胞外侧。膜的流动性与物质转运，能量转化，细胞识别免疫，药物对细胞的作用密切相关，可以说，一切膜的基本活动均在细胞膜的流动状态下进行。若细胞膜固化，黏度增大，膜内的活动将终止，最后导致细胞死亡。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_21","kind":"mcq","q":"亲和蛋白进人细胞核的方式是","o":["A. 被动扩散","B. 协助扩散","C. 主动运输","D. 胞吞-胞吐作用"],"a":"D","src":"湖北大学，2007年","kp":null,"e":"亲核蛋白依靠核定位信号与核输入受体，经核孔复合体进行门控运输进入细胞核；本题按所给答案选D。","oe":["错误：核孔只允许小分子自由扩散，亲核蛋白不能被动扩散入核。","错误：核输入不经膜载体，不属于协助扩散。","错误：核输入虽耗能，但属核孔门控运输，不是膜上载体的主动运输。","正确（所给答案）：亲核蛋白经核孔复合体的选择性转运进入细胞核。"]},{"id":"jyq_ch02_22","kind":"judge","q":"协同运输是直接消耗ATP的主动运输。","a":"错","src":"华中师范大学，2008年","kp":null,"e":"协同运输（如Na+-葡萄糖同向转运）不直接水解ATP，而是借助离子电化学梯度驱使物质逆浓度运输，属继发性主动运输，故原说法错误。","oe":["选“对”：错误。协同运输本身不直接消耗ATP，ATP由维持离子梯度的离子泵间接消耗。","选“错”：正确。协同运输属于继发性主动运输，间接消耗ATP而非直接消耗，故原说法错误。"]},{"id":"jyq_ch02_23","kind":"judge","q":"转运蛋白既可以进行主动运输，也可以进行被动运输；而通道蛋白进行的都是被动运输。","a":"对","src":"中山大学，2009年","kp":null,"e":"转运（载体）蛋白既可介导被动的易化扩散，也可介导主动运输；通道蛋白只进行顺电化学梯度的被动运输，说法正确。","oe":["选“对”：正确。载体蛋白可进行被动或主动运输，通道蛋白只介导被动运输，故说法成立。","选“错”：错误。通道蛋白运输不耗能、顺电化学梯度，属于被动运输，否认之则不成立。"]},{"id":"jyq_ch02_24","kind":"judge","q":"钙调蛋白调节细胞内Ca²+浓度。","a":"错","src":"上海交通大学，2007年","kp":null,"e":"钙调蛋白（CaM）是Ca2+的受体/钙传感器，与Ca2+结合后调节靶酶活性、传递Ca2+信号；细胞内Ca2+浓度主要由钙泵和交换器调控，故说法错误。","oe":["选“对”：错误。钙调蛋白是Ca2+信号的受体，调节下游靶蛋白，并不负责维持细胞内Ca2+浓度。","选“错”：正确。细胞内Ca2+浓度由钙泵、Na+-Ca2+交换器等调控，钙调蛋白是Ca2+信号的下游传递者，故说法错误。"]},{"id":"jyq_ch02_25","kind":"judge","q":"人体内02和C02进人细胞膜是通过简单扩散。","a":"对","src":"南京师范大学，2008年","kp":null,"e":"O2和CO2是小分子非极性气体，可顺浓度梯度经简单扩散自由穿过脂双层，既不需载体也不耗能，说法正确。","oe":["选“对”：正确。O2、CO2通过简单扩散（自由扩散）进出细胞，符合气体分子的膜通透特性。","选“错”：错误。O2、CO2不需载体且不耗能，属简单扩散，否认之则不符合事实。"]},{"id":"jyq_ch02_26","kind":"mcq","q":"小肠上皮吸收葡萄糖以及各种氨基酸时，通过（)达到逆浓度梯度运输。","o":["A. 与Na*相伴运输","B. 与K+相伴运输","C. 与Ca²+相伴运输","D. 载体蛋白利用ATP能量"],"a":"A","src":"华中农业大学，2009年","kp":null,"e":"小肠上皮吸收葡萄糖和氨基酸是逆浓度梯度的继发性主动运输，动力来自Na+顺浓度梯度进入细胞。","oe":["正确：葡萄糖、氨基酸与Na+同向转运，借Na+电化学梯度供能逆浓度吸收。","错误：K+梯度主要用于维持膜电位，不直接驱动糖和氨基酸吸收。","错误：Ca2+与小肠吸收葡萄糖、氨基酸的过程无直接偶联。","错误：该转运不直接水解ATP，而是间接消耗钠泵建立的Na+梯度。"]},{"id":"jyq_ch02_27","kind":"short","q":"比较载体蛋白与通道蛋白的特点。","a":"答载体蛋白是膜上的一种蛋白质，调节着离子主动吸收的一种成分，相当于结合在细胞质膜上的酶，有特异性结合位点，可同特异性底物结合，一种特异性载体只转运一种类型的分子或离子；转运过程具有类似酶与底物作用的饱和动力曲线。在膜的一侧与离子特异性地结合，形成不稳定载体一离子复合物，然后在膜的另一侧把离子释放出来，而载体又回到原来一侧。细胞膜上一定的蛋白质，可以使一定的离子通过。载体蛋白是多回旋折叠的跨膜蛋白质，它与被传递的分子特异结合使其越过质膜。载体蛋白需要同被运输的离子和分子结合，然后通过自身的构型变化或移动完成物质运输的膜蛋白。载体蛋白促进扩散时同样具有高度的特异性，其上有结合点，只能与某一种物质进行暂时性、可逆的结合和分离。而且，一个特定的载体只运输一种类型的化学物质，甚至一种分子或离子。载体蛋白既参与被动的物质运输，也参与主动的物质运输。由载体蛋白进行的被动物质运输，不需要ATP提供能量。载体蛋白对物质的转运过程具有类似于酶与底物作用的动力学曲线、可被类似物竞争性抑制、具有竞争性抑制等酶的特性。但与酶不同的是：载体蛋百不对转运分子作任何共价修饰。通道蛋白：通道蛋白是一类横跨质膜，能使适宜大小的分子及带电荷的分子通过简单的自由扩散运动，从质膜的一侧转运到另一侧。通道蛋白可以是单体蛋白，也可以是多亚基组成的蛋白，它们都是通过疏水的氨基酸链进行重排，形成水性通道。通道蛋白本身并不直接与小的带电荷的分子相互作用，这些小的带电荷的分子可以自由地扩散，通过由脂双层中膜蛋白带电荷的亲水区所形成的水性通道。通道蛋白的运输作用具有选择性，所以在细胞膜中有各种不同的通道蛋白。通道蛋白参与的只是被动运输，在运输过程中并不与被运输的分子结合，也不会移动，并且是从高浓度向低浓度运输，所以运输时不消耗能量。容见表5-3。表5-3四类ATP驱动的离子和小分子运输泵的比较类型运输物质结构与功能特点存在的部位H\"泵：存在于植物、真菌和细菌的质膜；H*,Na*,通常有大小两个亚基，大亚基被磷酸化，P型Na*/K：动物细胞的质膜；H+/K*泵：K*,Ca²+小亚基调节运输。哺乳动物胃细胞表层质膜；Ca泵：所有真核生物的质膜；肌细胞的肌质网膜。有多个跨膜亚基，建立H的电化学梯细菌的质膜、线粒体内膜、叶绿体的类囊F型只是H度，合成ATP。体膜。（续表5-3）类型运输物质结构与功能特点存在的部位①植物、酵母和其他真菌的液泡膜；②动多个跨膜亚基，亚基的细胞质部分可将物细胞的溶酶体和内体的膜；③某些分V型只是H*ATP水解，并利用释放的能量将H运输泌酸性物质的动物细胞质膜（如破骨细到囊泡中，使之成为酸性环境。胞和肾管状细胞）。两个膜结构域形成水性通道，两个细胞①细菌质膜（运输氨基酸、糖和肽）；②哺离子和各种质ATP结合结构域与ATP水解及物质乳动物内质网膜（运输与MHC蛋白相关ABC型小分子运输相偶联。不同结构域可以位于同一的抗原肽）；③哺乳动物细胞质膜（运输个亚基，也可位于不同的亚基。小分子、磷脂、小的类脂分子）","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_28","kind":"short","q":"比较动物细胞、植物细胞和原生动物细胞应付低渗膨胀的机制有何不同。","a":"细胞内低浓度溶质，如Na*/K*-ATPase、Ca²+-ATPase等；植物细胞有细胞壁，避免膨胀和破裂，从而耐受较大的跨膜渗差异；同时植物细胞的质膜中没有Na*/K-ATPase，代之的是H-ATPase来建立植物细胞的电化学梯度来应付低渗膨胀。原生动物通过收缩胞定时排出进人细胞过量的水而避免膨胀。对大多数细胞而言，Na+/K*-ATPase对维持渗透平衡起重要作用。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_29","kind":"short","q":"你对细胞质基质的结构组成及其在细胞生命活动中作用作何理解。","a":"答细胞质基质在真核细胞的细胞质中，除去可分辨的细胞器和内含物以外，较为均质、半透明的液状物质，它是细胞的重要结构成分，约占细胞质体积的一半。其主要成分一类是中间代谢相关酶类：①小分子和各种离子，如水、K、Cl、Na、Mg+、Ca²+等；②中分子类，脂类、糖类、氨基酸、核苷酸类等；③大分子类，蛋白质、脂蛋白、RNA、多糖等。二类是细胞质骨架：微丝、微管、中间纤维。细胞质基质在细胞生命活动中的作用：①完成各种中间代谢过程；②完成蛋白质的分选与运输；③细胞质骨架可作为细胞质基质结构体系的组织者，为基质中其他成分或细胞器提供锚定位点；4维持细胞形态、细胞运动、胞内物质运输及能量传递等；5蛋白质的修饰和选择性的降解；6提供离子环境、提供底物、物质运输通路、细胞分化等。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_30","kind":"short","q":"为什么说细胞内膜系统是一个结构与功能密切联系的动态性整体？","a":"容细胞的生物膜系统：细胞膜、细胞核膜以及内质网、高尔基体、线粒体等由膜围绕而成的细胞器，在结构、功能上都是紧密联系的统一整体，它们形成的结构体系叫做细胞的生物膜系统，根据其在细胞中的中，在结构、功能或发生上相关的，由膜围绕而成的细胞器或细胞结构，如核膜、内质网、高尔基体、线粒体、叶绿体、溶酶体等。各种生物膜在结构上的联系：真核细胞中，内质网外连细胞膜，内连核膜，中间还与许多细胞器膜相连，其内质网腔还与内外两层核膜之间的腔相通，从而使细胞结构之间相互联系，成为一个统一整体；此外，高尔基体膜，内质网膜，细胞膜，还是可以相互转化的。由此可见，细胞内的生物膜在结构上具有一定的连续性。各种生物膜在功能上的联系：膜融合是细胞融合（如植物体细胞杂胶臻物考物的过程的键，第七章细胞质基质与内膜系统也与大分子物质进出细胞的内吞作用和外排作用密切相关，通过膜之间的联系，使细胞内各种细胞器在独立完成各自生理功能的同时，又能有效的协调工作，保证细胞生命活动的正常进行，如分泌蛋白的形成。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_31","kind":"short","q":"膜流（membranefluidity）","a":"细胞内膜系统中各细胞器膜性成分的相互移位和转移。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_32","kind":"short","q":"图解说明细胞内膜系统的各种细胞器在结构与功能上的联系。","a":"答由于绘图不便，略。细胞内膜系统的各种细胞器在结构与功能上是相互联系的。从功能上看，细胞内膜结合细胞器的分布是功能越重要越靠近中央；从层次看，上游的靠臻生激考外咨细胞校和细胞的中央，它是细胞中最重要的细胞器，有两层膜结构。细胞核的外膜与内质网的膜是联系在一起的，细胞核的外膜是糙面内质网的一部分。糙面内质网的功能是参与蛋白质合成，其作用仅次于细胞核，所以内质网位于细胞核的外侧。高尔基体在内质网的外侧，接受来自内质网的蛋白质和脂肪，然后对它们进行修饰和分选，它所完成的是内质网的下游工作。溶酶体是含有水解酶的囊泡，它是由高尔基体分泌而来。内体是由内吞作用产生的具有分选作用的细胞器，它能向溶酶体传递从细胞外摄取的物质，这种细胞器一般位于细胞质的外侧。另外还有线粒体、过氧化物酶体等分布在细胞的不同部位。如果是植物细胞还有叶绿体和中央大液泡，它们也是按功能定位的。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch02_33","kind":"short","q":"以葡萄糖运输为例，简述胰岛素降低血糖的机制。","a":"胰岛素是体内唯一降低血糖的激素，也是唯一同时促进糖原、脂肪、蛋白质合成的激素。血糖升高时，立即引起胰岛素分泌。其降血糖是多方面作用的结果：①促进葡萄糖转运人细胞，降低血液中糖含量。②通过共价修饰使糖原合成酶活性增加，磷酸化酶活性降低，加速糖原合成，抑制糖原分解。③激活丙酮酸脱氢酶，加快糖的有氧氧化。4通过抑制PEP羧激酶的合成以及减少糖异生的原料，抑制糖异生。5抑制脂肪组织内的脂肪酶，减少脂肪动员，使组织利用葡萄糖增加。","src":"华东师范大学，2009年","kp":null},{"id":"jyq_ch02_34","kind":"judge","q":"雌性哺乳动物细胞的巴氏小体属于兼性异染色体。","a":"对","src":"华中师范大学，2007年","kp":null,"oe":["巴氏小体是失活的X染色体，同一染色体可异染色质化，属兼性异染色质。","若把它当作结构（组成型）异染色质则错，兼性异染色质由常染色质转变而来。"]},{"id":"jyq_ch02_35","kind":"judge","q":"常染色质状态不仅是基因转录的必要条件，而且是充分条件。","a":"错","src":"南京师范大学，2008年","kp":null,"e":"常染色质（疏松、转录活跃状态）只是基因转录的必要条件之一，是否转录还取决于启动子、转录因子等调控因素，并非充分条件。","oe":["选“对”：错误。常染色质是转录的必要条件，但仅有疏松染色质并不足以启动转录。","选“错”：正确。基因转录还需转录因子、启动子和调控序列等条件，常染色质只是必要条件而非充分条件。"]}],"outline":["流动镶嵌模型","膜组成(脂/蛋白/糖)","膜特性(流动/不对称)","跨膜运输(被动/主动/协同)","膜电位"],"outlineMap":[0,0,1,0,1],"narrative":"细胞质膜把细胞与外界分开，并承担物质运输、信息接收与细胞识别。1972 年 Singer 与 Nicolson 提出流动镶嵌模型：磷脂双分子层为基本骨架、蛋白镶嵌其中、膜具流动性与不对称性。膜脂（甘油磷脂、鞘脂、胆固醇）与膜蛋白（内在、外周、脂锚定）共同决定膜性质；温度、脂肪酸饱和度与胆固醇调节流动性。物质跨膜分被动运输（简单扩散、协助扩散）与主动运输（泵、协同运输）；Na⁺/K⁺ 泵维持离子梯度与膜电位，水通道、离子通道与载体各司其职。2003 年 Agre 与 MacKinnon 因水通道与钾通道研究获诺奖。"};